// Generated from the merged, de-duplicated interview guides (7 markdown sources → 175 unique questions).
// Block format: ['p'|'quote', text] · ['h', text] · ['ul'|'ol', items] · ['code', lang, text] · ['table', header, rows]
export const GUIDE_QA = [{"id":2714,"category":"JavaScript","difficulty":"Junior","question":"What is the difference between var, let and const? Does const make an object immutable?","answer":"const prevents reassignment of the variable, not mutation of an object.","highlights":["No. It prevents reassignment of the binding. The object can still be mutated unless it is otherwise made immutable."],"body":[["h","Quick recap"],["ul",["**Does const make an object immutable?** No. It prevents reassignment of the binding. The object can still be mutated unless it is otherwise made immutable."]],["table",["Feature","`var`","`let`","`const`"],[["Scope","Function","Block","Block"],["Redeclaration","Yes","No","No"],["Reassignment","Yes","Yes","No"],["Hoisted","Yes, initialized as `undefined`","Yes, but TDZ","Yes, but TDZ"],["Recommended","Legacy code","Normal mutable variable","Default choice"]]],["code","js","var x = 10;\nvar x = 20; // allowed\n\nlet y = 10;\ny = 20;     // allowed\n// let y = 30; // SyntaxError\n\nconst z = 10;\n// z = 20;   // TypeError"],["code","js","const user = { name: \"Gopi\" };\nuser.name = \"Krishna\"; // allowed\n\n// user = {}; // not allowed"]],"realWorld":[["h","Real-world example"],["p","Prefer `const` for dependencies and values that do not get reassigned:"],["code","js","const API_URL = \"/api/users\";\n\nfunction getUser(id) {\n  return fetch(`${API_URL}/${id}`);\n}"],["p","Use `let` when a value genuinely changes:"],["code","js","let retryCount = 0;\n\nwhile (retryCount < 3) {\n  retryCount++;\n}"],["p","Avoid `var` in modern JavaScript unless maintaining legacy code."],["p","**In practice.** On a pull request, a reviewer flags `var total` inside a loop of a billing script: it leaks outside the block and was reused by a later calculation, producing a wrong invoice total. Changing it to `const`/`let` limits the scope to the block and the bug disappears."]]},{"id":2715,"category":"JavaScript","difficulty":"Junior","question":"Hoisting with Real Execution Examples","answer":"JavaScript processes declarations before executing the code in their scope. The exact behavior differs by declaration type.","highlights":[],"body":[["p","What is hoisting?"],["h","var"],["code","js","console.log(name);\nvar name = \"Gopi\";"],["p","Conceptually:"],["code","js","var name;\nconsole.log(name); // undefined\nname = \"Gopi\";"],["p","Output:"],["code","text","undefined"],["h","let and const"],["code","js","console.log(name);\nlet name = \"Gopi\";"],["p","This throws:"],["code","text","ReferenceError"],["p","The variable is technically created during scope setup but cannot be accessed before its declaration because it is in the **Temporal Dead Zone (TDZ)**."],["h","Function declarations"],["code","js","sayHello();\n\nfunction sayHello() {\n  console.log(\"Hello\");\n}"],["p","This works because function declarations are available during the setup phase."],["h","Function expression"],["code","js","sayHello(); // TypeError\n\nvar sayHello = function () {\n  console.log(\"Hello\");\n};"],["p","The variable is hoisted as `undefined`, but the function assignment happens later."]],"realWorld":[["p","**Why it matters.** Hoisting explains confusing 'undefined' and ReferenceError bugs, and interviewers use it to test whether you understand the creation phase of an execution context."],["p","**Example.** A teammate calls `calculateTax()` at the top of a billing script and it works because function declarations are hoisted, but `const rate = 0.18` declared below it throws a ReferenceError (temporal dead zone) when the function reads it too early. Declaring constants first and using `const`/`let` instead of `var` removes this whole class of bug."]]},{"id":2716,"category":"JavaScript","difficulty":"Mid","question":"What are closures and where do you use them in real projects?","answer":"A closure occurs when a function remembers variables from its lexical scope even after the outer function has finished executing. count remains accessible because the returned function closes over it.","highlights":["They preserve access to lexical state, enabling private state, callbacks, factories, memoization, and reusable abstractions.","Data privacy","Function factories"],"body":[["h","Quick recap"],["ul",["**Why are closures useful?** They preserve access to lexical state, enabling private state, callbacks, factories, memoization, and reusable abstractions."]],["code","js","function createCounter() {\n  let count = 0;\n\n  return function () {\n    count++;\n    return count;\n  };\n}\n\nconst counter = createCounter();\n\nconsole.log(counter()); // 1\nconsole.log(counter()); // 2\nconsole.log(counter()); // 3"]],"realWorld":[["h","Real-world use case: private state"],["code","js","function createBankAccount(initialBalance) {\n  let balance = initialBalance;\n\n  return {\n    deposit(amount) {\n      balance += amount;\n    },\n\n    getBalance() {\n      return balance;\n    }\n  };\n}\n\nconst account = createBankAccount(1000);\n\naccount.deposit(500);\nconsole.log(account.getBalance()); // 1500"],["p","External code cannot directly access `balance`."],["h","Common use cases"],["ul",["Data privacy","Function factories","Memoization","Event handlers","React hooks","Callbacks","Maintaining state between calls"]],["p","**In practice.** A shopping-cart module exposes `addItem()` and `getTotal()` but keeps the `items` array private inside a closure, so no other script can corrupt the cart. The same idea powers React hooks, memoised selectors and rate-limited API wrappers that remember their last call time."]]},{"id":2717,"category":"JavaScript","difficulty":"Mid","question":"Why does setTimeout(fn, 0) not run immediately?","answer":"Run this function after at least the requested delay, when the JavaScript runtime is free to process the timer. JavaScript runs synchronous code first. The callback from setTimeout is placed into the task/macrotask queue after the timer becomes eligible. The event loop can execute it only when the current call stack is empty and the runtime gets to timers.","highlights":["No. It schedules a task that can run after the current stack and relevant microtasks have completed, subject to timer/runtime scheduling.","A runs immediately.","Timer is registered."],"body":[["h","Quick recap"],["ul",["**Is setTimeout(fn, 0) immediate?** No. It schedules a task that can run after the current stack and relevant microtasks have completed, subject to timer/runtime scheduling."]],["h","Simple explanation"],["p","`setTimeout(fn, 0)` means:"],["p","It does **not** mean \"run right now.\""],["h","Example"],["code","js","console.log(\"A\");\n\nsetTimeout(() => {\n  console.log(\"B\");\n}, 0);\n\nconsole.log(\"C\");"],["p","Output:"],["code","text","A\nC\nB"],["p","Why?"],["ol",["`A` runs immediately.","Timer is registered.","`C` runs immediately.","Current synchronous work finishes.","The timer callback can then execute."]],["h","Important interview point"],["p","A `0ms` timer is **not an exact scheduling guarantee**. If the JavaScript thread is busy for 2 seconds, the callback can be delayed for roughly 2 seconds or more."],["h","Interview answer"],["quote","`setTimeout(0)` doesn't execute immediately because JavaScript is single-threaded for JavaScript execution. The timer callback has to wait until the timer is eligible and the current call stack is empty. A zero delay means minimum delay, not immediate execution."]],"realWorld":[["h","Real-world example"],["p","Imagine a mobile app doing expensive JSON processing:"],["code","js","setTimeout(() => {\n  console.log(\"Timer\");\n}, 0);\n\nfor (let i = 0; i < 1e9; i++) {\n  // Expensive synchronous work\n}"],["p","The timer cannot interrupt that loop."],["p","**In practice.** A developer shows a 'Saving...' spinner and calls `setTimeout(save, 0)` expecting an instant update, but a heavy loop earlier delays it by 2 seconds. Understanding the queue explains why long synchronous work must be split (or moved to a worker) so the UI can paint between tasks."]]},{"id":2718,"category":"JavaScript","difficulty":"Mid","question":"How does the event loop prioritise promises (microtasks) over timers (macrotasks)?","answer":"Promises use the microtask queue, while setTimeout callbacks are generally tasks/macrotasks. After the current synchronous code finishes, JavaScript normally processes pending microtasks before moving on to the next task such as a timer.","highlights":[],"body":[["h","Example"],["code","js","console.log(\"1\");\n\nsetTimeout(() => {\n  console.log(\"2 - timer\");\n}, 0);\n\nPromise.resolve().then(() => {\n  console.log(\"3 - promise\");\n});\n\nconsole.log(\"4\");"],["p","Typical browser/Node output:"],["code","text","1\n4\n3 - promise\n2 - timer"],["h","Why?"],["p","The flow is approximately:"],["code","text","Synchronous code\n      ↓\nMicrotasks\n(Promise callbacks)\n      ↓\nNext task\n(timer callback)"],["h","Another example"],["code","js","setTimeout(() => console.log(\"timer\"), 0);\n\nPromise.resolve().then(() => {\n  console.log(\"promise 1\");\n\n  Promise.resolve().then(() => {\n    console.log(\"promise 2\");\n  });\n});"],["p","Output:"],["code","text","promise 1\npromise 2\ntimer"],["p","The newly-created microtask is processed before the runtime moves to the timer."],["h","Production trap"],["p","Too many microtasks can delay timers and other work:"],["code","js","function createMicrotasks() {\n  Promise.resolve().then(createMicrotasks);\n}\n\ncreateMicrotasks();"],["p","This can effectively starve other event-loop work."],["h","Interview answer"],["quote","Promises use the microtask queue. Timers such as `setTimeout` use a task/macrotask mechanism. Once synchronous execution finishes, microtasks are processed before the runtime proceeds to the next task, so a resolved promise commonly runs before a zero-delay timer."],["p","What is the difference between microtasks and macrotasks?"],["p","JavaScript has a call stack, while the runtime environment provides APIs and queues for asynchronous work."],["p","Simplified flow:"],["code","text","JavaScript Code\n      |\n      v\n   Call Stack\n      |\n      +---- Web/Node APIs\n      |         |\n      |         v\n      |      Task Queues\n      |\n      v\n Event Loop\n      |\n      v\n Call Stack"],["p","Example:"],["code","js","console.log(\"A\");\n\nsetTimeout(() => {\n  console.log(\"B\");\n}, 0);\n\nconsole.log(\"C\");"],["p","Output:"],["code","text","A\nC\nB"],["p","`setTimeout(..., 0)` does not mean \"execute immediately\". It means the callback becomes eligible after the timer phase and queue processing rules allow it."]],"realWorld":[["h","Real-world importance"],["p","A large microtask chain can delay timers and UI work:"],["code","js","function createManyMicrotasks() {\n  for (let i = 0; i < 100000; i++) {\n    queueMicrotask(() => {});\n  }\n}"],["p","Do not accidentally create huge chains of microtasks in performance-sensitive code."],["p","**In practice.** When a click handler updates state inside `.then()` and also schedules `setTimeout(log, 0)`, the promise callback always runs first. This ordering is why a chain of resolved promises can starve timers and freeze animations if it never yields."]]},{"id":2719,"category":"JavaScript","difficulty":"Mid","question":"What are call, apply and bind?","answer":"call: invokes immediately; arguments individually; apply: invokes immediately; arguments as an array; bind: returns a new function","highlights":[],"body":[["p","All three can explicitly control `this`."],["code","js","const user = {\n  name: \"Gopi\"\n};\n\nfunction greet(city, role) {\n  console.log(`${this.name} works as ${role} in ${city}`);\n}\n\ngreet.call(user, \"Chennai\", \"Developer\");\n\ngreet.apply(user, [\"Chennai\", \"Developer\"]);\n\nconst boundGreet = greet.bind(user);\nboundGreet(\"Chennai\", \"Developer\");"]],"realWorld":[["h","Real-world example"],["code","js","const logger = {\n  prefix: \"API\",\n  log(message) {\n    console.log(`[${this.prefix}] ${message}`);\n  }\n};\n\nconst log = logger.log.bind(logger);\n\nsetTimeout(() => {\n  log(\"Request completed\");\n}, 1000);"],["p","**In practice.** A shared utility `formatPrice` is reused with a different `this` using `formatPrice.call(currencyConfig, 100)`. `bind` is used to fix `this` for callbacks, for example `button.addEventListener('click', this.handleClick.bind(this))` in older class components, and `apply` passes an array of arguments, as in `Math.max.apply(null, prices)`."]]},{"id":2720,"category":"JavaScript","difficulty":"Mid","question":"How does this behave in regular functions vs arrow functions?","answer":"`this` is decided by how a function is called, not where it is written. Arrow functions skip that rule and capture `this` from the surrounding scope, which is why they fix so many callback bugs.","highlights":[],"body":[["h","Regular functions"],["code","js","const user = {\n  name: \"Gopi\",\n  greet() {\n    console.log(this.name);\n  }\n};\n\nuser.greet(); // Gopi"],["h","Arrow functions"],["p","Arrow functions do not create their own `this`. They capture `this` lexically."],["code","js","const user = {\n  name: \"Gopi\",\n\n  greet() {\n    const fn = () => {\n      console.log(this.name);\n    };\n\n    fn();\n  }\n};\n\nuser.greet(); // Gopi"],["p","A common mistake:"],["code","js","const user = {\n  name: \"Gopi\",\n\n  greet: () => {\n    console.log(this.name);\n  }\n};"],["p","Do not use an arrow function for an object method when you expect dynamic method-call `this`."]],"realWorld":[["p","**Why it matters.** `this` is decided by how a function is called, not where it is written. Arrow functions skip that rule and capture `this` from the surrounding scope, which is why they fix so many callback bugs."],["p","**Example.** In a class-based timer component, `setInterval(function () { this.count++ })` loses `this` and updates nothing, while `setInterval(() => this.count++)` works because the arrow function keeps the component's `this`. The opposite also bites: an arrow function as an object method gets the outer `this`, so use a normal method there."]]},{"id":2721,"category":"JavaScript","difficulty":"Mid","question":"How does prototypal inheritance work?","answer":"Objects can delegate property lookup to another object through the prototype chain.","highlights":[],"body":[["code","js","const animal = {\n  eat() {\n    console.log(\"Eating\");\n  }\n};\n\nconst dog = Object.create(animal);\n\ndog.bark = function () {\n  console.log(\"Barking\");\n};\n\ndog.eat();  // inherited\ndog.bark(); // own property"],["p","Lookup is approximately:"],["code","text","dog\n |\n v\nanimal\n |\n v\nObject.prototype\n |\n v\nnull"],["h","Classes use prototypes internally"],["code","js","class Animal {\n  eat() {\n    console.log(\"Eating\");\n  }\n}\n\nclass Dog extends Animal {\n  bark() {\n    console.log(\"Barking\");\n  }\n}"],["p","Methods are generally stored on prototypes rather than copied into every instance."]],"realWorld":[["p","**Why it matters.** Prototypes are how JavaScript shares behaviour. ES6 `class` is just cleaner syntax over the same mechanism, so knowing the prototype chain lets you debug 'method is not a function' errors."],["p","**Example.** Every `new Customer()` object does not get its own copy of `getDiscount()`. The method lives once on `Customer.prototype`, and a million customer objects in an e-commerce cart service share it, saving memory. A `PremiumCustomer extends Customer` simply links its prototype to the parent's."]]},{"id":2722,"category":"JavaScript","difficulty":"Mid","question":"What is the difference between shallow copy and deep copy, and when does it break apps?","answer":"A shallow copy creates a new outer object but keeps references to nested objects. A deep copy recursively creates independent nested structures. This becomes dangerous when application state contains nested objects and we accidentally mutate a shared reference, causing stale UI, incorrect Redux state, or unpredictable side effects.","highlights":["Use structuredClone where supported, or an appropriate library/serialization strategy for your data.","Unexpected state changes","React components not updating correctly"],"body":[["h","Shallow copy"],["p","A shallow copy copies only the **top-level properties**."],["code","js","const original = {\n  name: \"Gopi\",\n  address: {\n    city: \"Vellore\"\n  }\n};\n\nconst copy = { ...original };\n\ncopy.address.city = \"Chennai\";\n\nconsole.log(original.address.city);\n// Chennai"],["p","Why?"],["p","The nested `address` object is still shared."],["code","text","original.address ─────┐\n                      ├──> same object\ncopy.address ─────────┘"],["h","Deep copy"],["p","A deep copy creates independent nested objects."],["code","js","const original = {\n  name: \"Gopi\",\n  address: {\n    city: \"Vellore\"\n  }\n};\n\nconst copy = structuredClone(original);\n\ncopy.address.city = \"Chennai\";\n\nconsole.log(original.address.city);\n// Vellore"],["h","When does this break an application?"],["p","Suppose you update a user's nested state:"],["code","js","const newUser = { ...user };\n\nnewUser.profile.name = \"John\";"],["p","You may think you created a new user object, but `profile` may still be shared."],["p","This can cause:"],["ul",["Unexpected state changes","React components not updating correctly","Redux state mutation","Incorrect undo/redo behavior","Cached data becoming corrupted","Hard-to-reproduce bugs"]],["h","Better immutable update"],["code","js","const newUser = {\n  ...user,\n  profile: {\n    ...user.profile,\n    name: \"John\"\n  }\n};"],["h","Important caution"],["p","`JSON.parse(JSON.stringify(value))` is not a general-purpose deep clone. It loses or changes values such as `undefined`, `Date`, `Map`, `Set`, and special numeric values."],["p","Use `structuredClone` where supported, or an appropriate library/serialization strategy for your data."]],"realWorld":[["h","Real-world example"],["p","In an e-commerce app:"],["code","js","const cart = {\n  items: [\n    {\n      id: 1,\n      quantity: 2\n    }\n  ]\n};"],["p","If two parts of the application share the same nested object and one changes `quantity` directly, another screen can unexpectedly show the changed value."],["p","**In practice.** A shopping cart is cloned with the spread operator (`{ ...cart }`), but the nested `items` array is still shared. Editing the copy's first item changes the original cart too, so the 'undo' feature breaks. `structuredClone(cart)` creates an independent deep copy."]]},{"id":2723,"category":"JavaScript","difficulty":"Mid","question":"What makes an object mutable and why is immutability important in UI frameworks?","answer":"JavaScript objects are mutable by default. In UI frameworks, immutability makes state changes predictable and allows efficient reference comparisons. Instead of mutating existing state, I create a new object or array with the required changes.","highlights":[],"body":[["h","Mutable object"],["p","An object is mutable when its properties can be changed after creation."],["code","js","const user = {\n  name: \"Gopi\"\n};\n\nuser.name = \"John\";\n\nconsole.log(user.name);\n// John"],["p","`const` does **not** make the object immutable."],["p","It only prevents reassignment of the variable:"],["code","js","const user = {};\n// user = {}; // Error"],["p","But this is allowed:"],["code","js","user.name = \"John\";"],["h","Immutability"],["p","Instead of changing the existing object, create a new object:"],["code","js","const user = {\n  name: \"Gopi\"\n};\n\nconst updatedUser = {\n  ...user,\n  name: \"John\"\n};"],["h","Why does this matter in UI frameworks?"],["p","Frameworks such as React often use **reference equality** to efficiently determine whether something changed."],["p","Example:"],["code","js","const oldUser = {\n  name: \"Gopi\"\n};\n\nconst newUser = oldUser;\n\nconsole.log(oldUser === newUser);\n// true"],["p","No new reference was created."],["p","Now:"],["code","js","const newUser = {\n  ...oldUser,\n  name: \"John\"\n};\n\nconsole.log(oldUser === newUser);\n// false"],["p","React and state-management libraries can use these reference changes to make efficient update decisions."],["h","Important point"],["p","Immutability does not mean objects are magically impossible to change. It is an **application design practice**: treat state as read-only and create new values when state changes."]],"realWorld":[["h","Real-world example"],["p","Bad:"],["code","js","user.profile.name = \"John\";\nsetUser(user);"],["p","Better:"],["code","js","setUser(prev => ({\n  ...prev,\n  profile: {\n    ...prev.profile,\n    name: \"John\"\n  }\n}));"],["p","**In practice.** React compares references to decide whether to re-render. Pushing into the same array (`list.push(item); setList(list)`) keeps the same reference, so nothing updates. Creating a new array (`setList([...list, item])`) changes the reference and the UI refreshes; it also makes undo and time-travel debugging possible."]]},{"id":2724,"category":"JavaScript","difficulty":"Junior","question":"What is the difference between == and ===?","answer":"`==` applies type coercion with surprising rules (`0 == ''` is true), while `===` compares type and value. Strict equality makes behaviour predictable and bugs easier to find.","highlights":[],"body":[["p","What is the difference?"],["p","`==` performs type coercion."],["code","js","\"5\" == 5; // true"],["code","js","\"5\" === 5; // false"],["p","Prefer:"],["code","js","if (userId === requestedId) {\n  // ...\n}"],["h","Interesting example"],["code","js","0 == false;  // true\n0 === false; // false"],["p","For predictable code, use `===` and `!==` by default."]],"realWorld":[["p","**Why it matters.** `==` applies type coercion with surprising rules (`0 == ''` is true), while `===` compares type and value. Strict equality makes behaviour predictable and bugs easier to find."],["p","**Example.** A search form reads `quantity` from an input as the string `'0'`. `if (quantity == 0)` treats it as zero and an `if (quantity === 0)` check does not, so an order of 'zero items' slipped through validation in one codebase until the team enforced `===` with an ESLint rule (`eqeqeq`) and converted the value with `Number()` explicitly."]]},{"id":2725,"category":"JavaScript","difficulty":"Mid","question":"What is currying? Implement infinite currying and explain real use cases.","answer":"Currying converts a function that accepts multiple arguments into a sequence of functions that each accept one argument.","highlights":["Reusable API helpers","Logging functions","Validation functions"],"body":[["h","What is currying?"],["p","Normal function:"],["code","js","function add(a, b) {\n  return a + b;\n}\n\nadd(2, 3);"],["p","Curried version:"],["code","js","function add(a) {\n  return function (b) {\n    return a + b;\n  };\n}\n\nadd(2)(3);\n// 5"],["h","Why is currying useful?"],["p","It allows us to create a partially configured function."],["code","js","function multiplyBy(x) {\n  return function (y) {\n    return x * y;\n  };\n}\n\nconst multiplyBy10 = multiplyBy(10);\n\nmultiplyBy10(5);\n// 50"],["h","Infinite currying"],["p","A common interview example is:"],["code","js","sum(1)(2)(3)(4)();"],["p","Expected result:"],["code","text","10"],["p","Implementation:"],["code","js","function sum(a) {\n  let total = a;\n\n  return function next(b) {\n    if (b === undefined) {\n      return total;\n    }\n\n    total += b;\n    return next;\n  };\n}\n\nconsole.log(sum(1)(2)(3)(4)());\n// 10"],["h","How it works"],["code","text","sum(1)\n  ↓\ntotal = 1\n  ↓\n(2)\n  ↓\ntotal = 3\n  ↓\n(3)\n  ↓\ntotal = 6\n  ↓\n(4)\n  ↓\ntotal = 10\n  ↓\n()\n  ↓\nreturn 10"],["h","Interview answer"],["quote","Currying transforms a multi-argument function into a sequence of functions. I use it when I want to preconfigure part of a function and reuse the resulting function. Infinite currying is an interview-style extension where the function keeps accepting values until a terminating call returns the accumulated result."],["p","What is currying?"],["p","Currying converts a function that takes multiple arguments into a sequence of functions that each take one argument."],["code","js","function multiply(a) {\n  return function (b) {\n    return function (c) {\n      return a * b * c;\n    };\n  };\n}\n\nconsole.log(multiply(2)(3)(4)); // 24"],["p","Arrow version:"],["code","js","const multiply = a => b => c => a * b * c;"]],"realWorld":[["h","Real-world example: API configuration"],["code","js","function createApiClient(baseUrl) {\n  return function (endpoint) {\n    return function (options = {}) {\n      return fetch(`${baseUrl}${endpoint}`, options);\n    };\n  };\n}\n\nconst api = createApiClient(\"https://api.example.com\");\n\napi(\"/users\")({\n  method: \"GET\"\n});"],["p","The base URL can be configured once and reused."],["h","Real-world use cases"],["p","Currying can be useful for:"],["ul",["Reusable API helpers","Logging functions","Validation functions","Configuration","Function composition","Functional programming","Creating specialized utilities"]],["h","Real-world example"],["code","js","const hasRole = requiredRole => user =>\n  user.roles.includes(requiredRole);\n\nconst isAdmin = hasRole(\"admin\");\n\nisAdmin({ roles: [\"user\", \"admin\"] }); // true"],["p","Currying is useful for reusable configuration and functional programming patterns."]]},{"id":2726,"category":"JavaScript","difficulty":"Mid","question":"Debouncing vs throttling: what is the difference and when do you use each?","answer":"Both limit how often a handler runs. Debounce waits for a pause in events, throttle guarantees a maximum rate. Choosing the right one protects the server and keeps the UI smooth.","highlights":["Search box","Auto-save","Validation"],"body":[["h","Debouncing"],["p","Typical use:"],["ul",["Search box","Auto-save","Validation"]],["code","js","function debounce(fn, delay) {\n  let timer;\n\n  return (...args) => {\n    clearTimeout(timer);\n\n    timer = setTimeout(() => {\n      fn(...args);\n    }, delay);\n  };\n}\n\nconst search = debounce(query => {\n  console.log(\"API call:\", query);\n}, 300);"],["h","Throttling"],["p","Run at most once per interval."],["p","Typical use:"],["ul",["Scroll events","Mouse movement","Window resize","Analytics events"]],["code","js","function throttle(fn, delay) {\n  let lastCall = 0;\n\n  return (...args) => {\n    const now = Date.now();\n\n    if (now - lastCall >= delay) {\n      lastCall = now;\n      fn(...args);\n    }\n  };\n}"],["h","Easy interview rule"],["code","text","Debounce = wait until the activity stops\nThrottle = limit how often activity can run"]],"realWorld":[["p","**Why it matters.** Both limit how often a handler runs. Debounce waits for a pause in events, throttle guarantees a maximum rate. Choosing the right one protects the server and keeps the UI smooth."],["p","**Example.** A product search box calls the API only 300 ms after the user stops typing (debounce), so typing 'laptop' fires one request instead of six. A scroll listener that updates a 'back to top' button or tracks reading progress uses throttle, running at most once every 100 ms while the user keeps scrolling."]]},{"id":2727,"category":"JavaScript","difficulty":"Senior","question":"How do memory leaks happen and how does garbage collection work (browser and Node.js)?","answer":"Event listeners not removed; Timers not cleared; Long-lived global references; Closures retaining large objects; Caches growing without limits; Subscriptions not cleaned up","highlights":[],"body":[["p","What causes memory leaks in JavaScript?"],["p","Common causes:"],["p","Example:"],["code","js","const button = document.querySelector(\"#button\");\n\nfunction handleClick() {\n  console.log(\"clicked\");\n}\n\nbutton.addEventListener(\"click\", handleClick);\n\n// Later:\nbutton.removeEventListener(\"click\", handleClick);"],["p","In React:"],["code","js","useEffect(() => {\n  const handler = () => console.log(window.scrollY);\n\n  window.addEventListener(\"scroll\", handler);\n\n  return () => {\n    window.removeEventListener(\"scroll\", handler);\n  };\n}, []);"],["h","Also worth knowing"],["p","JavaScript engines automatically reclaim objects that are no longer reachable."],["p","Conceptually:"],["code","text","Root\n |\n v\nObject A ---> Object B\n\nIf no root can reach A/B:\nA and B can eventually be garbage collected."],["p","Example:"],["code","js","function createLargeObject() {\n  const data = new Array(1_000_000).fill(\"data\");\n  return data;\n}\n\nlet cache = createLargeObject();\n\ncache = null;"],["p","Once no references remain, the object becomes eligible for garbage collection."],["p","Important: setting a variable to `null` does not force garbage collection. It only removes one reference."],["h","Also worth knowing"],["p","Common causes:"],["code","text","Global collections\nUnbounded caches\nEvent listener accumulation\nLong-lived closures\nUnclosed resources\nLarge request objects retained"],["p","A simple dangerous cache:"],["code","js","const cache = new Map();\n\napp.get(\"/data/:id\", async (req, res) => {\n  const data = await load(req.params.id);\n  cache.set(req.params.id, data);\n  res.json(data);\n});"],["p","If IDs are effectively unlimited and the cache never expires, memory can continuously grow."],["p","Use bounded caches, TTLs, eviction policies, and monitoring."]],"realWorld":[["p","**Why it matters.** Leaks make long-lived apps slower until they crash. Knowing what stays reachable (listeners, timers, closures, caches) is more useful than memorising garbage-collector names."],["p","**Example.** A dashboard adds a `resize` listener and a `setInterval` poller in every route change but never removes them. After an hour the tab holds hundreds of detached DOM nodes and uses 1 GB. In Node.js the same pattern appears as an unbounded in-memory cache keyed by user id. Fix: clean up in `useEffect` return functions, use `WeakMap`, and cap caches (LRU)."]]},{"id":2728,"category":"JavaScript","difficulty":"Mid","question":"What happens internally when you use the new keyword?","answer":"Creates a new object.; Links the object's prototype to User.prototype.; Calls User with this pointing to the new object.; Returns the object, unless the constructor explicitly returns another object.","highlights":[],"body":[["p","Consider:"],["code","js","function User(name) {\n  this.name = name;\n}\n\nconst user = new User(\"Gopi\");"],["p","Conceptually, `new` does these steps:"],["p","Equivalent conceptual code:"],["code","js","const user = Object.create(User.prototype);\n\nUser.call(user, \"Gopi\");\n\nreturn user;"],["p","This is why:"],["code","js","user instanceof User; // true"]],"realWorld":[["p","**Why it matters.** Explaining `new` step by step proves you understand constructors, prototypes and `this` binding rather than treating classes as magic."],["p","**Example.** When you write `new Order(items)` in a checkout module, JavaScript creates an empty object, links it to `Order.prototype`, runs the constructor with `this` set to that object and returns it. Forgetting `new` on a constructor function silently sets properties on the global object in sloppy mode, a real source of 'ghost' global variables in legacy code."]]},{"id":2729,"category":"TypeScript","difficulty":"Junior","question":"interface vs type: which should you use?","answer":"Both describe shapes, but `interface` supports declaration merging and `extends`, while `type` handles unions, intersections and mapped types. Teams need a consistent rule.","highlights":["interface for public object/class contracts","type for unions, tuples, mapped/conditional types, and aliases"],"body":[["p","Both can describe object shapes."],["code","ts","interface User {\n  id: number;\n  name: string;\n}\n\ntype UserType = {\n  id: number;\n  name: string;\n};"],["p","`interface` supports declaration merging:"],["code","ts","interface User {\n  email: string;\n}"],["p","`type` is more flexible for unions and advanced compositions:"],["code","ts","type Status = \"pending\" | \"success\" | \"failed\";\n\ntype ID = string | number;"],["h","Practical guideline"],["p","Use either consistently. A common convention is:"],["ul",["`interface` for public object/class contracts","`type` for unions, tuples, mapped/conditional types, and aliases"]]],"realWorld":[["p","**Why it matters.** Both describe shapes, but `interface` supports declaration merging and `extends`, while `type` handles unions, intersections and mapped types. Teams need a consistent rule."],["p","**Example.** A public SDK exposes `interface User` so consuming projects can augment it. Internally, a `type PaymentStatus = 'PENDING' | 'PAID' | 'FAILED'` union models allowed states, something an interface cannot express. A common team guideline: interface for object shapes and class contracts, type for unions and utility compositions."]]},{"id":2730,"category":"TypeScript","difficulty":"Junior","question":"Optional vs Nullable Fields","answer":"Nullable means the property exists conceptually but may contain null. Use optional for \"may not be provided\" and nullable for \"known field with no value\".","highlights":[],"body":[["p","Optional means the property may not exist."],["code","ts","interface User {\n  name: string;\n  nickname?: string;\n}"],["p","`nickname` can be absent."],["code","ts","interface User {\n  name: string;\n  nickname: string | null;\n}"],["p","These are different:"],["code","ts","const a: User = {\n  name: \"Gopi\"\n  // nickname absent\n};\n\nconst b: User = {\n  name: \"Gopi\",\n  nickname: null\n};"]],"realWorld":[["p","**Why it matters.** `?` means a property may be missing, `| null` means it is present but empty. Mixing them up causes runtime errors that TypeScript can no longer catch."],["p","**Example.** A user profile API returns `middleName: null` when the user has none, and omits `phone` until verified. Typing them `middleName: string | null` and `phone?: string` forces the UI to handle both cases, so the profile page never renders 'null' text or crashes on `phone.length`."]]},{"id":2731,"category":"TypeScript","difficulty":"Mid","question":"When and why should you use generics?","answer":"Generics allow reusable code while preserving type information.","highlights":["When an algorithm or data structure should preserve relationships between types while remaining reusable."],"body":[["h","Quick recap"],["ul",["**When should you use generics?** When an algorithm or data structure should preserve relationships between types while remaining reusable."]],["p","Without generics:"],["code","ts","function identity(value: any): any {\n  return value;\n}"],["p","With generics:"],["code","ts","function identity<T>(value: T): T {\n  return value;\n}\n\nconst result = identity(\"hello\");\n// result is string"]],"realWorld":[["h","Real-world API example"],["code","ts","interface ApiResponse<T> {\n  data: T;\n  message: string;\n  success: boolean;\n}\n\ninterface User {\n  id: number;\n  name: string;\n}\n\nconst response: ApiResponse<User> = {\n  data: {\n    id: 1,\n    name: \"Gopi\"\n  },\n  message: \"OK\",\n  success: true\n};"],["p","Generics are valuable when the structure stays the same but the data type changes."],["p","**In practice.** One generic `fetchJson<T>(url): Promise<T>` helper replaces separate `getUsers`, `getOrders` and `getProducts` functions, and each caller gets correct types: `const orders = await fetchJson<Order[]>('/api/orders')`. The compiler then flags misuse of `orders` without any duplicated code."]]},{"id":2732,"category":"TypeScript","difficulty":"Mid","question":"Which TypeScript utility types (Partial, Pick, Omit, Readonly) do you use most?","answer":"Utility types derive new types from existing ones, so you do not duplicate definitions and they stay in sync when the original changes.","highlights":[],"body":[["h","Partial"],["p","Makes properties optional."],["code","ts","interface User {\n  id: number;\n  name: string;\n  email: string;\n}\n\ntype UpdateUser = Partial<User>;"],["p","Useful for PATCH requests."],["h","Pick"],["p","Select specific properties."],["code","ts","type UserPreview = Pick<User, \"id\" | \"name\">;"],["h","Omit"],["p","Remove properties."],["code","ts","type PublicUser = Omit<User, \"email\">;"],["h","Readonly"],["p","Prevents assignment through that type."],["code","ts","const user: Readonly<User> = {\n  id: 1,\n  name: \"Gopi\",\n  email: \"gopi@example.com\"\n};\n\n// user.name = \"New Name\"; // error"]],"realWorld":[["p","**Why it matters.** Utility types derive new types from existing ones, so you do not duplicate definitions and they stay in sync when the original changes."],["p","**Example.** A form for editing a customer reuses `Partial<Customer>` so only changed fields are sent in a PATCH request. A public API response uses `Omit<Customer, 'passwordHash'>` so the hash can never leak, and a list view picks just `Pick<Customer, 'id' | 'name'>` for a dropdown."]]},{"id":2733,"category":"TypeScript","difficulty":"Mid","question":"Enums vs Union Types","answer":"Enums can be useful when a named runtime object is desirable.","highlights":[],"body":[["p","Enum:"],["code","ts","enum Role {\n  Admin = \"admin\",\n  User = \"user\"\n}"],["p","Union:"],["code","ts","type Role = \"admin\" | \"user\";"],["p","For many frontend applications, unions are simpler and have less runtime overhead:"],["code","ts","function hasAccess(role: \"admin\" | \"user\") {\n  return role === \"admin\";\n}"]],"realWorld":[["p","**Why it matters.** Enums generate runtime code and have quirks, while union literal types are erased and work naturally with JSON. Many teams prefer unions or `as const` objects."],["p","**Example.** An order status coming from the backend as the string 'SHIPPED' maps directly to `type OrderStatus = 'PLACED' | 'SHIPPED' | 'DELIVERED'` with no conversion. A numeric enum would need translation, and an accidental `OrderStatus.Placed = 5` style mismatch would not be caught when data arrives from JSON."]]},{"id":2734,"category":"TypeScript","difficulty":"Mid","question":"Type Narrowing Strategies","answer":"Narrowing lets TypeScript prove which variant you hold inside a branch, so you can access the right properties without unsafe casts.","highlights":[],"body":[["h","typeof"],["code","ts","function print(value: string | number) {\n  if (typeof value === \"string\") {\n    console.log(value.toUpperCase());\n  } else {\n    console.log(value.toFixed(2));\n  }\n}"],["h","in"],["code","ts","type Dog = { bark(): void };\ntype Cat = { meow(): void };\n\nfunction speak(animal: Dog | Cat) {\n  if (\"bark\" in animal) {\n    animal.bark();\n  } else {\n    animal.meow();\n  }\n}"],["h","Discriminated unions"],["code","ts","type Result =\n  | { status: \"success\"; data: string }\n  | { status: \"error\"; error: string };\n\nfunction handle(result: Result) {\n  if (result.status === \"success\") {\n    console.log(result.data);\n  } else {\n    console.error(result.error);\n  }\n}"],["p","This is one of the strongest patterns for safe application state."]],"realWorld":[["p","**Why it matters.** Narrowing lets TypeScript prove which variant you hold inside a branch, so you can access the right properties without unsafe casts."],["p","**Example.** A payment result is `{ status: 'success', receiptId } | { status: 'failed', reason }`. Checking `if (result.status === 'success')` narrows the type, so `receiptId` is available only in that branch and `reason` only in the other, and a new `'pending'` variant triggers compile errors wherever it is not handled."]]},{"id":2735,"category":"TypeScript","difficulty":"Mid","question":"unknown vs any: why prefer unknown?","answer":"`any` switches type checking off; `unknown` forces you to validate before use. It is the safe type for data you do not control.","highlights":["unknown forces validation/narrowing before use, while any disables many type checks."],"body":[["h","Quick recap"],["ul",["**Why prefer unknown over any?** `unknown` forces validation/narrowing before use, while `any` disables many type checks."]],["code","ts","let value: any = \"hello\";\n\nvalue.notARealMethod(); // TypeScript allows it"],["p","`unknown` forces you to validate before use."],["code","ts","let value: unknown = \"hello\";\n\nif (typeof value === \"string\") {\n  console.log(value.toUpperCase());\n}"],["p","Prefer `unknown` for untrusted external data."]],"realWorld":[["p","**Why it matters.** `any` switches type checking off; `unknown` forces you to validate before use. It is the safe type for data you do not control."],["p","**Example.** `JSON.parse(localStorage.getItem('cart'))` returns `any` and a corrupted value crashes the checkout page later. Typing the result as `unknown`, then validating with a small schema check (or Zod) before use, turns a mysterious runtime crash into an explicit 'could not read cart' path."]]},{"id":2736,"category":"TypeScript","difficulty":"Mid","question":"How do you type API responses safely? Does an interface validate JSON at runtime?","answer":"Do not assume an API response is valid simply because you created a TypeScript type. This describes what you expect. It does not validate runtime JSON.","highlights":["No. TypeScript types are erased at runtime. External data needs runtime validation if you need runtime guarantees."],"body":[["h","Quick recap"],["ul",["**Does an interface validate API JSON at runtime?** No. TypeScript types are erased at runtime. External data needs runtime validation if you need runtime guarantees."]],["code","ts","interface User {\n  id: number;\n  name: string;\n}"],["p","For high-confidence systems, validate external data using a runtime schema library such as Zod:"],["code","ts","import { z } from \"zod\";\n\nconst UserSchema = z.object({\n  id: z.number(),\n  name: z.string()\n});\n\ntype User = z.infer<typeof UserSchema>;\n\nconst response: unknown = await fetch(\"/api/user\")\n  .then(r => r.json());\n\nconst user = UserSchema.parse(response);"],["p","The key senior-level distinction is:"],["code","text","TypeScript = compile-time safety\nRuntime validation = runtime safety"]],"realWorld":[["p","**Why it matters.** Types are erased at runtime, so an interface does not prove the server sent that shape. Safe typing combines compile-time types with runtime validation at the boundary."],["p","**Example.** A mobile app typed `interface Policy { premium: number }`, but the API started returning premium as a string `'1200.50'`. Nothing failed until a sum showed `NaN` in the UI. Parsing the response with a schema (Zod/io-ts) at the fetch layer would have thrown a clear error at the boundary."]]},{"id":2737,"category":"TypeScript","difficulty":"Mid","question":"Type-Safe Forms in React","answer":"Form state is a classic source of runtime bugs. Typing field names and values lets the compiler catch typos and missing validations.","highlights":[],"body":[["code","tsx","type LoginForm = {\n  email: string;\n  password: string;\n};\n\nconst [form, setForm] = useState<LoginForm>({\n  email: \"\",\n  password: \"\"\n});\n\nfunction updateField<K extends keyof LoginForm>(\n  key: K,\n  value: LoginForm[K]\n) {\n  setForm(prev => ({\n    ...prev,\n    [key]: value\n  }));\n}"],["p","Now:"],["code","ts","updateField(\"email\", \"gopi@example.com\"); // valid\nupdateField(\"password\", \"secret\");        // valid\n// updateField(\"email\", 123);             // error"]],"realWorld":[["p","**Why it matters.** Form state is a classic source of runtime bugs. Typing field names and values lets the compiler catch typos and missing validations."],["p","**Example.** A registration form defines `type RegisterForm = { name: string; email: string; age: number }` and passes it to React Hook Form. Writing `register('emial')` or reading `errors.age.message` incorrectly becomes a compile error, so refactoring the form in a banking onboarding flow stays safe."]]},{"id":2738,"category":"TypeScript","difficulty":"Mid","question":"Why TypeScript Scales Better in Large Apps","answer":"The important point is not \"TypeScript prevents all bugs\". It reduces a large category of mistakes before runtime.","highlights":["Refactoring safety","Better IDE support","Explicit contracts"],"body":[["p","TypeScript provides:"],["ul",["Refactoring safety","Better IDE support","Explicit contracts","Safer API boundaries","Better documentation through types","Earlier bug detection","Improved onboarding","Better component contracts"]]],"realWorld":[["p","**Why it matters.** In large codebases the compiler becomes documentation and a safety net: renames are safe, contracts between teams are explicit and bugs shift from production to build time."],["p","**Example.** On a 40-developer insurance platform, changing the `Claim` type from `amount: number` to a `Money` object produced 200 compile errors showing exactly every place that needed updating. Without TypeScript those would have been found one by one in production."]]},{"id":2739,"category":"React","difficulty":"Junior","question":"What is React, and why is component-based architecture useful?","answer":"Component architecture lets us separate UI responsibilities into reusable units. In my previous work, I also built reusable React components and design tokens so common UI patterns could be reused across teams, reducing repetitive development.","highlights":["Reusability","Maintainability","Easier testing"],"body":[["p","Instead of one huge component:"],["code","text","DocumentPage.jsx\n  3000 lines"],["p","break it into:"],["code","text","DocumentPage\n ├── SearchBar\n ├── FilterPanel\n ├── DocumentList\n ├── DocumentRow\n └── DocumentViewer"],["h","Benefits"],["ul",["Reusability","Maintainability","Easier testing","Clear responsibilities","Easier team development"]],["h","Interview answer"],["quote","React is a JavaScript library for building user interfaces using reusable components. It allows applications to break complex screens into smaller components and manage UI updates based on state and props."],["quote","I use React because componentization improves reusability and maintainability, while React's rendering model allows efficient UI updates."],["h","Example"],["code","jsx","function DocumentCard({ document }) {\n  return (\n    <div>\n      <h3>{document.name}</h3>\n      <p>{document.status}</p>\n    </div>\n  );\n}"]],"realWorld":[["h","Real-world example"],["p","Your resume mentions a reusable React component library that reduced feature development time by approximately 30%."],["p","**In practice.** A design system built from small components (`Button`, `Input`, `Modal`) lets five teams in a large insurance company build screens consistently and fix an accessibility bug once, in one place, instead of in fifty pages."]]},{"id":2740,"category":"React","difficulty":"Junior","question":"What is the Virtual DOM and how does it differ from the real DOM?","answer":"The DOM (Document Object Model) is the browser's representation of the HTML document.","highlights":["A common interview mistake is:","Virtual DOM makes React faster because it updates the entire DOM.","That is incorrect."],"body":[["h","What is the Real DOM?"],["p","Example:"],["code","html","<div id=\"user\">\n    <h1>Arjun</h1>\n</div>"],["p","The browser creates a DOM tree:"],["code","text","Document\n   |\n   +-- div#user\n          |\n          +-- h1\n               |\n               +-- \"Arjun\""],["p","JavaScript can directly modify it:"],["code","javascript","document.getElementById(\"user\").innerHTML =\n    \"<h1>Arjun Kumar</h1>\";"],["h","What is the Virtual DOM?"],["p","React maintains an in-memory representation of the UI."],["p","Example:"],["code","jsx","function User() {\n    return <h1>Arjun</h1>;\n}"],["p","Conceptually:"],["code","text","React Virtual DOM\n        |\n        v\n    <h1>Arjun</h1>"],["p","When state changes:"],["code","text","Before:\n<h1>Arjun</h1>\n\nAfter:\n<h1>Arjun Kumar</h1>"],["p","React determines what changed and commits the required DOM updates."],["h","Important clarification"],["p","A common interview mistake is:"],["quote","Virtual DOM makes React faster because it updates the entire DOM."],["p","That is incorrect."],["p","React does **not** simply replace the entire DOM every time state changes."],["p","A simplified model is:"],["code","text","State/Props change\n       |\n       v\nReact renders\n       |\n       v\nNew React element tree\n       |\n       v\nReconciliation\n       |\n       v\nDetermine required changes\n       |\n       v\nCommit DOM updates"],["p","The actual React implementation is more sophisticated and uses Fiber and scheduling mechanisms."],["h","Interview answer"],["quote","The Real DOM is the browser's actual document tree. React works with its own representation of the UI and uses reconciliation to determine the necessary changes before committing updates to the real DOM. The important benefit is that React lets developers describe the desired UI declaratively while React manages efficient updates."],["h","Also worth knowing"],["p","The Virtual DOM is React's in-memory representation of the UI."],["p","When state changes:"],["code","text","State changes\n     ↓\nReact creates new UI representation\n     ↓\nReact determines what changed\n     ↓\nRequired UI updates are applied"],["h","Example"],["code","jsx","function Counter() {\n  const [count, setCount] = useState(0);\n\n  return (\n    <button onClick={() => setCount(count + 1)}>\n      {count}\n    </button>\n  );\n}"],["p","When `count` changes, React determines the necessary update rather than requiring the developer to manually manipulate the DOM."],["h","Interview answer"],["quote","The Virtual DOM is a lightweight in-memory representation of the UI. When state or props change, React calculates the new representation and determines what needs to be updated. The important benefit is that developers work declaratively rather than manually manipulating the DOM."],["h","Also worth knowing"],["p","React represents UI as a tree of elements."],["p","When state changes:"],["code","text","State change\n    |\n    v\nReact renders\n    |\n    v\nNew element tree\n    |\n    v\nReconciliation\n    |\n    v\nMinimal necessary DOM updates"],["p","React does not simply replace the entire DOM on every render."],["p","Example:"],["code","tsx","function Counter() {\n  const [count, setCount] = useState(0);\n\n  return (\n    <button onClick={() => setCount(count + 1)}>\n      Count: {count}\n    </button>\n  );\n}"],["p","A state update causes React to calculate what needs to change."]],"realWorld":[["h","Real-world e-commerce example"],["p","Suppose a shopping cart contains:"],["code","text","Laptop\nMouse\nKeyboard"],["p","When the quantity of the laptop changes:"],["code","text","Laptop quantity:\n1 -> 2"],["p","React determines which UI output needs to change instead of manually requiring you to update every DOM node."],["p","**In practice.** Instead of rewriting the whole list DOM when one row changes, React builds a new virtual tree, diffs it against the previous one and updates only the changed row in the browser. Developers still need stable keys and memoisation, as the virtual DOM is not magically free."]]},{"id":2741,"category":"React","difficulty":"Mid","question":"How does React reconciliation work, and why do keys matter in lists?","answer":"Reconciliation is the process React uses to determine how the rendered UI should change when props or state change.","highlights":["React uses keys to match items across renders. Stable keys preserve the correct component identity and state.","Consider:","Use stable keys:"],"body":[["h","Quick recap"],["ul",["**Why should list keys be stable?** React uses keys to match items across renders. Stable keys preserve the correct component identity and state."]],["h","Simplified flow"],["code","text","State changes\n     |\n     v\nComponent renders again\n     |\n     v\nNew element tree\n     |\n     v\nReconciliation\n     |\n     v\nDetermine changes\n     |\n     v\nCommit\n     |\n     v\nBrowser DOM"],["h","Example"],["p","Initial:"],["code","jsx","<ul>\n    <li>Apple</li>\n    <li>Orange</li>\n</ul>"],["p","New:"],["code","jsx","<ul>\n    <li>Apple</li>\n    <li>Mango</li>\n</ul>"],["p","React can identify that:"],["code","text","Apple -> unchanged\nOrange -> Mango"],["p","and update the required DOM node."],["h","Keys are important"],["p","Consider:"],["code","jsx","{users.map(user => (\n    <User key={user.id} user={user} />\n))}"],["p","Use stable keys:"],["code","jsx","key={user.id}"],["p","Avoid using array index as a key when list items can be inserted, deleted, or reordered."],["p","Bad:"],["code","jsx","{users.map((user, index) => (\n    <User key={index} user={user} />\n))}"],["p","Better:"],["code","jsx","{users.map(user => (\n    <User key={user.id} user={user} />\n))}"],["h","Why keys matter"],["p","Suppose:"],["code","text","Before:\n\nA\nB\nC"],["p","Insert:"],["code","text","X\nA\nB\nC"],["p","Stable IDs allow React to identify existing items correctly."],["p","Poor keys can cause:"],["ul",["Incorrect component state association","Unnecessary work","UI bugs in dynamic lists"]],["h","Interview answer"],["quote","Reconciliation is React's process of comparing the newly rendered element tree with the previous one and determining what needs to change. React uses element type and keys as important identity signals. The resulting changes are then committed to the DOM."],["h","Also worth knowing"],["code","tsx","users.map(user => (\n  <UserRow key={user.id} user={user} />\n));"],["p","Keys help React identify which items correspond between renders."],["p","Avoid array indexes when list order can change:"],["code","tsx","users.map((user, index) => (\n  <UserRow key={index} user={user} />\n));"],["p","If items are inserted, deleted, or reordered, index keys can cause state to be associated with the wrong item."]],"realWorld":[["p","**Why it matters.** Reconciliation is how React decides the minimum DOM changes after state updates, and keys are its identity tag for list items."],["p","**Example.** In a to-do or order list where items can be reordered or deleted, using array index as key makes React reuse the wrong component instance, so a typed-in input or checkbox appears on the wrong row. Using the stable order id as key keeps each row's state attached to the right item."]]},{"id":2742,"category":"React","difficulty":"Junior","question":"State vs Props","answer":"Props flow down and are read-only; state is owned and changed by the component. This one-way flow is what makes React apps predictable.","highlights":[],"body":[["h","Props"],["p","Data passed from parent to child."],["code","tsx","function UserCard({ name }: { name: string }) {\n  return <h2>{name}</h2>;\n}\n\n<UserCard name=\"Gopi\" />;"],["h","State"],["p","Data owned by a component that can change."],["code","tsx","const [count, setCount] = useState(0);"],["p","Simple rule:"],["code","text","Props = input from parent\nState = internal changing data"]],"realWorld":[["p","**Why it matters.** Props flow down and are read-only; state is owned and changed by the component. This one-way flow is what makes React apps predictable."],["p","**Example.** A `ProductCard` receives `price` and `name` as props from the product list page, but owns a `quantity` state for its own '+ / -' buttons. When the parent re-renders with a new price from the API, the card shows it immediately while keeping its quantity."]]},{"id":2743,"category":"React","difficulty":"Mid","question":"Controlled vs Uncontrolled Components","answer":"Controlled inputs are useful for validation and dynamic UI. Uncontrolled inputs can be simpler for certain forms and integrations.","highlights":[],"body":[["h","Controlled"],["p","React owns the value."],["code","tsx","function Form() {\n  const [email, setEmail] = useState(\"\");\n\n  return (\n    <input\n      value={email}\n      onChange={e => setEmail(e.target.value)}\n    />\n  );\n}"],["h","Uncontrolled"],["p","The DOM owns the current value."],["code","tsx","function Form() {\n  const inputRef = useRef<HTMLInputElement>(null);\n\n  function submit() {\n    console.log(inputRef.current?.value);\n  }\n\n  return <input ref={inputRef} />;\n}"]],"realWorld":[["p","**Why it matters.** Controlled inputs keep the value in React state; uncontrolled inputs keep it in the DOM and are read via refs. The choice affects validation, performance and testing."],["p","**Example.** A login form with live password-strength feedback is controlled because the UI reacts to every keystroke. A file-upload input is uncontrolled (`<input type='file' ref={fileRef} />`) because its value cannot be set programmatically and you only need it on submit."]]},{"id":2744,"category":"React","difficulty":"Junior","question":"Lifting State Up","answer":"If two sibling components need the same state, move the state to their nearest common parent.","highlights":[],"body":[["code","tsx","function Parent() {\n  const [selectedId, setSelectedId] = useState<number | null>(null);\n\n  return (\n    <>\n      <List onSelect={setSelectedId} />\n      <Details id={selectedId} />\n    </>\n  );\n}"],["p","This creates a single source of truth."]],"realWorld":[["p","**Why it matters.** When two components need the same data, the state should live in their closest common parent. This avoids out-of-sync copies of the same value."],["p","**Example.** A flight search page has a filter sidebar and a results list. The selected 'max price' lives in the page component and is passed down to both, so changing the slider updates the results instantly. Keeping separate copies in each child led to the list and the sidebar showing different filters."]]},{"id":2745,"category":"React","difficulty":"Junior","question":"Fragments","answer":"Fragments let you return multiple elements without adding an unnecessary DOM element.","highlights":[],"body":[["code","tsx","return (\n  <>\n    <Header />\n    <Content />\n    <Footer />\n  </>\n);"],["p","This avoids an extra `<div>`."]],"realWorld":[["p","**Why it matters.** Fragments let a component return several elements without adding extra DOM nodes, keeping markup valid and CSS layouts intact."],["p","**Example.** A table row component returning `<td>` cells must not be wrapped in a `<div>`, because that makes invalid HTML and breaks the table layout. `<>...</>` (or `<Fragment key={id}>` in lists) returns the cells with no wrapper."]]},{"id":2746,"category":"React","difficulty":"Junior","question":"useState vs useRef vs useContext: when do you use each?","answer":"useState is for reactive component state. useRef is for persistent mutable values or DOM references where changing the value should not itself trigger a render. useContext is for consuming values shared through a React context. I choose based on whether the value should trigger rendering, whether I need a mutable reference, or whether the data is shared across a component tree.","highlights":["Context is not automatically a replacement for every state-management problem.","When the context value changes, consumers that depend on that context may need to render again.","For large applications, consider:"],"body":[["p","These three hooks solve different problems."],["table",["Hook","Main purpose"],[["`useState`","Store state that affects rendering"],["`useRef`","Store a mutable value or DOM reference without causing a render"],["`useContext`","Read shared values from a React context"]]],["h","useState"],["p","Use `useState` when changing the value should cause the component to render again."],["code","jsx","import { useState } from \"react\";\n\nfunction Counter() {\n\n    const [count, setCount] = useState(0);\n\n    return (\n        <button onClick={() => setCount(count + 1)}>\n            {count}\n        </button>\n    );\n}"],["p","Flow:"],["code","text","setCount()\n    |\n    v\nState changes\n    |\n    v\nComponent renders again"],["h","useRef"],["p","`useRef` stores a mutable value that persists between renders."],["p","Changing `.current` does not itself trigger a render."],["code","jsx","import { useRef } from \"react\";\n\nfunction Timer() {\n\n    const timerId = useRef(null);\n\n    function start() {\n        timerId.current = setInterval(() => {\n            console.log(\"running\");\n        }, 1000);\n    }\n\n    function stop() {\n        clearInterval(timerId.current);\n    }\n\n    return (\n        <>\n            <button onClick={start}>Start</button>\n            <button onClick={stop}>Stop</button>\n        </>\n    );\n}"],["h","DOM reference example"],["code","jsx","function SearchBox() {\n\n    const inputRef = useRef(null);\n\n    function focusInput() {\n        inputRef.current.focus();\n    }\n\n    return (\n        <>\n            <input ref={inputRef} />\n            <button onClick={focusInput}>\n                Focus\n            </button>\n        </>\n    );\n}"],["h","useContext"],["p","Use context when a value needs to be available to many components without passing it manually through every intermediate component."],["p","Example:"],["code","jsx","const ThemeContext = createContext(\"light\");"],["p","Provider:"],["code","jsx","<ThemeContext.Provider value=\"dark\">\n    <App />\n</ThemeContext.Provider>"],["p","Consumer:"],["code","jsx","function Button() {\n\n    const theme = useContext(ThemeContext);\n\n    return (\n        <button className={theme}>\n            Save\n        </button>\n    );\n}"],["h","Important useContext performance point"],["p","Context is not automatically a replacement for every state-management problem."],["p","When the context value changes, consumers that depend on that context may need to render again."],["p","For large applications, consider:"],["code","text","Context\n+\nComponent composition\n+\nMemoization\n+\nState-management library where justified"],["h","Also worth knowing"],["code","tsx","const [count, setCount] = useState(0);\n\nsetCount(count + 1);"],["p","When the next state depends on the previous state, use the functional form:"],["code","tsx","setCount(prev => prev + 1);"],["p","This is especially important when multiple updates are queued."],["h","Also worth knowing"],["p","`useState` changes trigger rendering."],["p","`useRef` stores a mutable value without causing a render when changed."],["code","tsx","const [count, setCount] = useState(0);\n\nconst renderCount = useRef(0);\nrenderCount.current++;"],["p","Use refs for:"],["ul",["DOM references","Timers","Previous values","Mutable instance-like values"]],["p","Use state for values that affect what the UI displays."]],"realWorld":[["h","Real-world banking example"],["p","A banking application might have:"],["code","text","AuthContext\nThemeContext\nFeatureFlagContext"],["p","For example:"],["code","jsx","const AuthContext = createContext(null);"],["p","Components can access the current authenticated user."],["p","**In practice.** A checkout form uses `useState` for the typed card number, `useRef` to focus the first invalid field and to store a timeout id without re-rendering, and `useContext` to read the logged-in user and theme provided higher in the tree."]]},{"id":2747,"category":"React","difficulty":"Mid","question":"How does useEffect work, what are the lifecycle equivalents, and why return a cleanup function?","answer":"Cleanup runs before the effect is re-run and when the component unmounts.","highlights":["To remove subscriptions, timers, event listeners, abort requests, or otherwise undo external synchronization.","Browser APIs","Network subscriptions"],"body":[["h","Quick recap"],["ul",["**Why return cleanup from useEffect?** To remove subscriptions, timers, event listeners, abort requests, or otherwise undo external synchronization."]],["p","`useEffect` is for synchronizing a component with external systems such as:"],["ul",["Browser APIs","Network subscriptions","Timers","Event listeners","External libraries"]],["code","tsx","useEffect(() => {\n  const controller = new AbortController();\n\n  fetch(\"/api/users\", {\n    signal: controller.signal\n  });\n\n  return () => {\n    controller.abort();\n  };\n}, []);"],["h","Cleanup"],["code","tsx","useEffect(() => {\n  const id = setInterval(() => {\n    console.log(\"tick\");\n  }, 1000);\n\n  return () => clearInterval(id);\n}, []);"],["h","Common dependency mistake"],["code","tsx","useEffect(() => {\n  fetchUser(userId);\n}, []); // potentially stale userId"],["p","If the effect depends on `userId`, normally include it:"],["code","tsx","useEffect(() => {\n  fetchUser(userId);\n}, [userId]);"],["p","Do not treat the dependency array as a way to suppress legitimate dependencies."],["h","Also worth knowing"],["p","`useEffect` is used to synchronize a component with an external system or perform side effects after rendering."],["h","API example"],["code","jsx","useEffect(() => {\n  fetchUser(userId);\n}, [userId]);"],["p","When `userId` changes, the effect runs again."],["h","Interview trap"],["p","Don't say:"],["quote","`useEffect` is for every piece of code that runs after render."],["p","Better:"],["quote","`useEffect` is mainly for synchronizing React with external systems."],["h","Also worth knowing"],["p","Modern React mainly uses function components and Hooks."],["p","Conceptually, a component has:"],["code","text","Mount\n ↓\nUpdate\n ↓\nUnmount"],["h","useState"],["p","Stores component state."],["code","jsx","const [count, setCount] = useState(0);\n\n<button onClick={() => setCount(count + 1)}>\n  {count}\n</button>"],["h","useEffect"],["p","Used for side effects."],["code","jsx","useEffect(() => {\n\n    fetchUser();\n\n    return () => {\n        // cleanup\n    };\n\n}, []);"],["p","Examples:"],["ul",["API calls","subscriptions","timers","browser integrations"]],["h","useRef"],["p","Stores a mutable value without causing re-render."],["code","jsx","const inputRef = useRef(null);\n\nfunction focusInput() {\n    inputRef.current.focus();\n}"]],"realWorld":[["p","**Why it matters.** `useEffect` synchronises a component with something outside React: network, timers, subscriptions. Dependencies and cleanup are where most bugs come from."],["p","**Example.** A live order-tracking screen subscribes to a WebSocket in `useEffect` and returns a cleanup that closes it. Without the cleanup, navigating between orders leaves old sockets open and the UI shows updates from the previous order. A missing dependency in a data-fetching effect shows stale data after the user id changes."]]},{"id":2748,"category":"React","difficulty":"Mid","question":"useMemo vs useCallback vs useEffect: what is the difference and when should you use them?","answer":"useMemo caches a computed value, useCallback caches a function reference, and useEffect is for side effects such as API calls, subscriptions or timers. I don't use memoization everywhere; I use it when profiling shows it provides a benefit.","highlights":["When a calculation is expensive or stable reference identity provides a meaningful optimization. Profile before optimizing."],"body":[["h","Quick recap"],["ul",["**When should you use useMemo?** When a calculation is expensive or stable reference identity provides a meaningful optimization. Profile before optimizing."]],["p","Hook          Purpose"],["h","useMemo"],["code","jsx","const filteredProducts = useMemo(() => {\n    return products.filter(p =>\n        p.price > 1000\n    );\n}, [products]);"],["h","useCallback"],["code","jsx","const handleSelect = useCallback((id) => {\n    selectProduct(id);\n}, []);"],["p","Useful when passing callbacks to memoized child components."],["h","useEffect"],["code","jsx","useEffect(() => {\n    loadProducts();\n}, []);"],["h","Also worth knowing"],["p","Memoizes a calculated value."],["code","tsx","const filteredUsers = useMemo(() => {\n  return users.filter(user =>\n    user.name.includes(search)\n  );\n}, [users, search]);"],["p","Use it when computation is meaningfully expensive or referential stability matters."],["p","Do not add `useMemo` everywhere. Memoization has its own overhead and complexity."],["h","Also worth knowing"],["p","Memoizes a function reference."],["code","tsx","const handleSelect = useCallback((id: number) => {\n  setSelectedId(id);\n}, []);"],["p","This can matter when passing callbacks to memoized children:"],["code","tsx","const Child = memo(function Child({\n  onSelect\n}: {\n  onSelect: (id: number) => void;\n}) {\n  // ...\n});"],["p","`useCallback` is not automatically a performance improvement. It is useful when function identity affects rendering or dependencies."],["h","Also worth knowing"],["p","`useMemo` caches the result of a calculation."],["code","jsx","const filteredDocuments = useMemo(() => {\n  return documents.filter(doc =>\n    doc.name.includes(searchText)\n  );\n}, [documents, searchText]);"],["p","The calculation is reused until its dependencies change."],["h","When useful"],["code","text","Expensive calculation\n        +\nStable dependencies\n        +\nRepeated renders\n        ↓\nuseMemo may help"],["h","When it can hurt"],["p","If the calculation is trivial:"],["code","js","const fullName = firstName + \" \" + lastName;"],["p","using `useMemo` may add complexity without meaningful benefit."],["h","Interview answer"],["quote","`useMemo` is a performance optimization, not a default coding pattern. I use it when profiling or the component's behavior indicates an expensive calculation is being repeated unnecessarily."]],"realWorld":[["p","**Why it matters.** These three hooks are often confused: `useMemo` caches a value, `useCallback` caches a function, and `useEffect` runs side effects after render."],["p","**Example.** A reports page filters 50,000 rows. Wrapping the filter in `useMemo` avoids recomputing it on every keystroke elsewhere in the page, `useCallback` keeps the `onRowClick` handler stable for a memoised table row component, and `useEffect` fetches new data when the date range changes."]]},{"id":2749,"category":"React","difficulty":"Mid","question":"Custom Hooks","answer":"A custom hook extracts reusable stateful logic. Custom hooks improve reuse without forcing components into inheritance.","highlights":[],"body":[["code","tsx","function useDebouncedValue<T>(value: T, delay: number) {\n  const [debounced, setDebounced] = useState(value);\n\n  useEffect(() => {\n    const timer = setTimeout(() => {\n      setDebounced(value);\n    }, delay);\n\n    return () => clearTimeout(timer);\n  }, [value, delay]);\n\n  return debounced;\n}"],["p","Usage:"],["code","tsx","const debouncedSearch = useDebouncedValue(search, 300);"]],"realWorld":[["p","**Why it matters.** Custom hooks package reusable stateful logic so components stay short and logic is testable in one place."],["p","**Example.** A `useDebouncedSearch(query)` hook used by the product search, the customer lookup and the claims search encapsulates the timer, API call and loading state. Each screen just calls `const { results, loading } = useDebouncedSearch(text)` instead of copy-pasting 30 lines."]]},{"id":2750,"category":"React","difficulty":"Senior","question":"Batching and React 18 Concurrency","answer":"React can batch multiple state updates so that they produce fewer renders. React 18 expanded automatic batching to many asynchronous contexts.","highlights":[],"body":[["code","tsx","function update() {\n  setCount(c => c + 1);\n  setFlag(f => !f);\n}"],["p","Concurrency also allows React to prioritize and interrupt rendering work. It does not mean JavaScript suddenly became multithreaded."],["p","Example:"],["code","tsx","const [isPending, startTransition] = useTransition();\n\nstartTransition(() => {\n  setSearchResults(expensiveResults);\n});"],["p","Use transitions for non-urgent UI updates."]],"realWorld":[["p","**Why it matters.** React 18 batches multiple state updates into one render and can interrupt rendering for urgent work. Understanding this explains why logs show fewer renders than setState calls."],["p","**Example.** A button handler that calls `setLoading(true)`, `setError(null)` and `setCount(c + 1)` now causes one render, even inside promises and timeouts. For a heavy filter list, wrapping the list update in `startTransition` keeps typing in the input responsive while the long list updates at lower priority."]]},{"id":2751,"category":"React","difficulty":"Mid","question":"Strict Mode Behavior","answer":"In development, React Strict Mode intentionally performs extra checks and may invoke certain lifecycle/render paths more than once. It is primarily a development-time diagnostic mechanism, not \"React making production render twice.\"","highlights":["Impure rendering","Missing cleanup","Unsafe side effects"],"body":[["p","Example:"],["code","tsx","<React.StrictMode>\n  <App />\n</React.StrictMode>"],["p","This helps expose:"],["ul",["Impure rendering","Missing cleanup","Unsafe side effects"]]],"realWorld":[["p","**Why it matters.** Strict Mode intentionally double-runs some code in development to expose impure renders and missing effect cleanup. It does not affect production."],["p","**Example.** A developer sees an API call fire twice on page load locally and thinks it is a bug. It is Strict Mode mounting, unmounting and re-mounting to verify the effect cleans up properly. Adding an `AbortController` cleanup removes duplicate calls and proves the effect is safe."]]},{"id":2752,"category":"React","difficulty":"Senior","question":"How do you optimise performance in large React applications?","answer":"Performance optimization should start with measurement rather than random memoization.","highlights":[],"body":[["h","1. Avoid unnecessary renders"],["p","Use:"],["code","jsx","React.memo()"],["p","when a component benefits from skipping renders with unchanged props."],["code","jsx","const ProductCard = React.memo(function ProductCard({\n    product\n}) {\n    return <div>{product.name}</div>;\n});"],["h","2. useMemo"],["p","Use `useMemo` for expensive derived calculations when memoization actually helps."],["code","jsx","const expensiveResult = useMemo(() => {\n    return calculateSomething(products);\n}, [products]);"],["p","Do not use `useMemo` everywhere automatically."],["h","3. useCallback"],["p","Useful when stable function identity matters, for example when passing callbacks to memoized children."],["code","jsx","const handleSelect = useCallback((id) => {\n    setSelectedId(id);\n}, []);"],["p","Again, unnecessary memoization can add complexity."],["h","4. Code splitting"],["p","Instead of loading the entire application immediately:"],["code","text","Application\n |\n +--> Home\n +--> Products\n +--> Orders\n +--> Admin\n +--> Reports"],["p","Load features when needed."],["code","jsx","const Admin = lazy(() => import(\"./Admin\"));"],["p","Then:"],["code","jsx","<Suspense fallback={<div>Loading...</div>}>\n    <Admin />\n</Suspense>"],["h","5. Virtualization"],["p","For thousands of rows, don't render every row at once."],["p","Example:"],["code","text","100,000 transactions\n        |\n        v\nOnly visible rows rendered"],["p","Libraries such as TanStack Virtual can help implement this pattern."],["h","6. Optimize API requests"],["p","Avoid:"],["code","text","Component A -> API\nComponent B -> API\nComponent C -> same API"],["p","when the data can be shared."],["p","Use an appropriate server-state/data-fetching strategy."],["h","7. Optimize images"],["p","Use:"],["code","text","Responsive images\nLazy loading\nModern image formats\nAppropriate dimensions\nCDN"],["p","Example:"],["code","html","<img\n    src=\"/product.webp\"\n    loading=\"lazy\"\n    alt=\"Laptop\"\n/>"],["h","8. Bundle optimization"],["p","Use:"],["code","text","Code splitting\nTree shaking\nCompression\nCaching\nCDN"],["h","9. Measure"],["p","Useful browser tools include:"],["code","text","Chrome DevTools\nReact DevTools Profiler\nLighthouse\nPerformance APIs"],["h","Interview answer"],["quote","For a large React application, I first measure the bottleneck using the React Profiler and browser performance tools. Then I optimize unnecessary renders, use memoization selectively, split bundles, virtualize large lists, optimize images and network requests, and cache appropriate server data. I avoid blindly adding `useMemo` or `useCallback` because memoization also has a cost."],["h","Also worth knowing"],["p","Strategies:"],["ol",["Keep state local where possible.","Avoid unnecessary global state.","Split large components.","Use `memo` when it provides measurable value.","Stabilize props when needed.","Virtualize large lists.","Avoid expensive calculations during render."]],["p","Example:"],["code","tsx","const UserRow = memo(function UserRow({\n  user\n}: {\n  user: User\n}) {\n  return <div>{user.name}</div>;\n});"],["p","Do not optimize based only on intuition. Profile first for difficult performance problems."],["h","Also worth knowing"],["p","A practical optimization process:"],["code","text","Measure\n  ↓\nFind expensive component/calculation\n  ↓\nUnderstand why it re-renders\n  ↓\nOptimize\n  ↓\nMeasure again"],["p","Useful techniques:"],["ul",["React DevTools Profiler","List virtualization","Code splitting","Memoization where justified","Server rendering","Image optimization","Avoiding unnecessary effects","Moving expensive work off the render path"]],["h","Also worth knowing"],["code","tsx","const AdminPage = React.lazy(() => import(\"./AdminPage\"));\n\nfunction App() {\n  return (\n    <Suspense fallback={<div>Loading...</div>}>\n      <AdminPage />\n    </Suspense>\n  );\n}"],["p","Benefits:"],["ul",["Smaller initial JavaScript","Faster initial loading","Load rarely used features only when needed"]],["p","Good candidates include:"],["ul",["Admin screens","Rich editors","Charts","Large third-party components"]],["h","Also worth knowing"],["p","Symptoms:"],["code","text","Typing feels slow\nLarge list renders slowly\nMany child components re-render"],["p","Investigation:"],["ol",["Profile with React DevTools.","Identify expensive components.","Check why they re-render.","Virtualize large lists.","Memoize only where useful.","Move expensive calculations out of render.","Split large bundles.","Consider server-side data fetching."]],["p","Do not immediately add `useMemo` and `useCallback` everywhere."]],"realWorld":[["h","E-commerce example"],["p","Imagine an e-commerce page displaying:"],["code","text","10,000 products"],["p","Do not render all 10,000 cards."],["p","Use:"],["code","text","Pagination / infinite scrolling\n+\nVirtualization\n+\nImage lazy loading\n+\nCaching\n+\nCode splitting"],["p","**In practice.** A support dashboard felt slow. The React Profiler showed one filter input re-rendering a 2,000-row table on every keystroke. Memoising the row component, debouncing the filter and virtualising the table removed the lag, and the team added a performance budget to CI."]]},{"id":2753,"category":"React","difficulty":"Senior","question":"How do you render 1,000 or 100,000 records in a React UI?","answer":"Rendering thousands of DOM nodes freezes the page. The answer combines fetching less data (pagination) and rendering less data (virtualisation).","highlights":["slow rendering","high memory usage","unnecessary re-renders"],"body":[["p","Rendering 1,000 rows can cause:"],["ul",["slow rendering","high memory usage","unnecessary re-renders","slow scrolling"]],["h","1. Pagination"],["p","Don't render everything."],["h","2. Virtualization"],["p","Only render visible rows."],["p","Libraries include:"],["ul",["react-window","TanStack Virtual"]],["p","Concept:"],["code","text","1000 records\n      ↓\nOnly 20 visible DOM nodes"],["h","3. React.memo"],["code","jsx","const ProductRow = React.memo(function ProductRow({ product }) {\n    return <div>{product.name}</div>;\n});"],["h","5. Debouncing"],["p","For search:"],["code","text","User types:\ni\nin\nins\ninsu\ninsur\ninsurance\n\nWait 300ms\n ↓\nOne API request"],["h","6. Backend pagination"],["p","Never rely only on frontend optimization."],["h","Also worth knowing"],["p","Don't load everything."],["p","Use:"],["code","text","Server-side filtering\n        ↓\nPagination / cursor pagination\n        ↓\nSmall API response\n        ↓\nEfficient rendering"],["p","For the UI:"],["code","text","Virtualized list\n+\nMemoized expensive components where useful\n+\nLazy loading"],["p","For document content:"],["code","text","Load metadata first\n       ↓\nLoad actual document\nonly when opened"]],"realWorld":[["p","**Why it matters.** Rendering thousands of DOM nodes freezes the page. The answer combines fetching less data (pagination) and rendering less data (virtualisation)."],["p","**Example.** A claims admin table with 100,000 rows loads 50 per page from the server, and when analysts need a long scroll the table uses a virtualised list (react-window) that renders only the ~20 visible rows. Memoised row components and stable keys keep scrolling at 60 fps."]]},{"id":2754,"category":"React","difficulty":"Mid","question":"How do you build infinite scrolling with pagination in React?","answer":"Use an index matching the query and avoid fetching unnecessary columns.","highlights":[],"body":[["p","Instead of loading 10,000 products:"],["code","text","Initial:\nProducts 1-20\n\nScroll\n\nProducts 21-40\n\nScroll\n\nProducts 41-60"],["h","React example"],["code","jsx","const [items, setItems] = useState([]);\nconst [page, setPage] = useState(0);\nconst [loading, setLoading] = useState(false);\n\nconst loadMore = async () => {\n\n    if (loading) return;\n\n    setLoading(true);\n\n    const response = await fetch(\n        `/api/products?page=${page}&size=20`\n    );\n\n    const data = await response.json();\n\n    setItems(prev => [...prev, ...data.content]);\n\n    setPage(prev => prev + 1);\n\n    setLoading(false);\n};"],["h","IntersectionObserver"],["code","jsx","useEffect(() => {\n\n    const observer = new IntersectionObserver(entries => {\n\n        if (entries[0].isIntersecting) {\n            loadMore();\n        }\n\n    });\n\n    if (loaderRef.current) {\n        observer.observe(loaderRef.current);\n    }\n\n    return () => observer.disconnect();\n\n}, [page, loading]);"],["h","Better production design"],["code","text","React\n ↓\nGET /products?page=0&size=20\n ↓\nAPI\n ↓\nDatabase\n ↓\nIndexed query"]],"realWorld":[["p","**Why it matters.** Infinite scroll feels natural but needs cursor-based pagination, loading states and a way to stop. Interviewers test your handling of edge cases."],["p","**Example.** A social/news feed fetches 20 items, then uses an `IntersectionObserver` on a sentinel element to request the next cursor when it becomes visible. It stops when the API returns no `nextCursor`, ignores duplicate calls while loading, and offers a retry button on failure."]]},{"id":2755,"category":"React","difficulty":"Mid","question":"Error Boundaries","answer":"Error boundaries catch rendering errors in descendant components. Error boundaries are useful around major UI sections so one rendering failure does not destroy the entire application experience.","highlights":[],"body":[["p","Class-based example:"],["code","tsx","class ErrorBoundary extends React.Component<\n  { children: React.ReactNode },\n  { hasError: boolean }\n> {\n  state = { hasError: false };\n\n  static getDerivedStateFromError() {\n    return { hasError: true };\n  }\n\n  componentDidCatch(error: Error, info: React.ErrorInfo) {\n    console.error(error, info);\n  }\n\n  render() {\n    if (this.state.hasError) {\n      return <h1>Something went wrong.</h1>;\n    }\n\n    return this.props.children;\n  }\n}"]],"realWorld":[["p","**Why it matters.** An uncaught render error unmounts the whole React tree and shows a blank page. Error boundaries contain the failure to one part of the UI."],["p","**Example.** A dashboard widget that renders a chart from malformed data throws. With an error boundary around each widget, the user sees 'This chart failed to load' with a retry button while the rest of the dashboard keeps working, and the error is sent to Sentry."]]},{"id":2756,"category":"React","difficulty":"Mid","question":"Context API and prop drilling: how do you avoid prop drilling?","answer":"Context allows values to be shared with components lower in the tree without manually passing props through every intermediate component. I use it for things such as theme, locale or application-level context, while using dedicated state-management or server-state tools when the problem is more complex.","highlights":["Context is not automatically the best replacement for every global state problem.","For complex state and server data, dedicated state/data tools may be more appropriate.","Authentication information"],"body":[["p","Suppose:"],["code","text","App\n ↓\nDashboard\n ↓\nDocumentPage\n ↓\nDocumentToolbar\n ↓\nButton"],["p","If every level passes the same user/theme/config:"],["code","jsx","<App user={user}>\n  <Dashboard user={user}>\n    <DocumentPage user={user}>\n      ...\n    </DocumentPage>\n  </Dashboard>\n</App>"],["p","This is prop drilling."],["p","Context can provide shared values:"],["code","jsx","const UserContext = createContext(null);\n\nfunction App() {\n  return (\n    <UserContext.Provider value={user}>\n      <Dashboard />\n    </UserContext.Provider>\n  );\n}"],["p","Then:"],["code","jsx","const user = useContext(UserContext);"],["h","Important"],["p","Context is not automatically the best replacement for every global state problem."],["p","For complex state and server data, dedicated state/data tools may be more appropriate."]],"realWorld":[["h","Good use cases"],["ul",["Theme","Locale","Authentication information","Stable application-level configuration"]],["p","**In practice.** A theme and a logged-in user are needed in 30 nested components. Passing them as props through every level is brittle, so a `UserContext` provider at the root lets any component read them directly. For frequently changing data, split contexts or use a state library to avoid re-rendering everything."]]},{"id":2757,"category":"React","difficulty":"Mid","question":"Search Box in a React Application","answer":"Search users as the user types without sending hundreds of requests. Backend should still rate-limit and validate the query. Debouncing is a UX/performance optimization, not a security control.","highlights":[],"body":[["p","Requirement:"],["p","Solution:"],["code","text","Input\n  |\n  v\nReact state\n  |\n  v\nDebounce 300ms\n  |\n  v\nAPI\n  |\n  v\nServer validation\n  |\n  v\nDatabase"],["p","React:"],["code","tsx","const [query, setQuery] = useState(\"\");\n\nconst debouncedQuery = useDebouncedValue(query, 300);\n\nuseEffect(() => {\n  if (!debouncedQuery.trim()) return;\n\n  fetch(`/api/users?q=${encodeURIComponent(debouncedQuery)}`);\n}, [debouncedQuery]);"]],"realWorld":[["p","**Why it matters.** A search box looks trivial but combines debouncing, request cancellation, race conditions and empty/error states."],["p","**Example.** On an e-commerce site, typing 'sam' then 'samsung' sends two requests. If the first response arrives last it overwrites the correct results. Debouncing 300 ms, cancelling the previous request with `AbortController` and showing a loading state avoids stale results and unnecessary API load."]]},{"id":2758,"category":"Next.js","difficulty":"Mid","question":"Pages Router vs App Router","answer":"For new applications, the App Router is generally the modern architecture.","highlights":["Server Components","Streaming","Nested routing"],"body":[["h","Pages Router"],["p","Uses:"],["code","text","pages/\n  index.tsx\n  users/\n    [id].tsx"],["p","Common APIs include:"],["code","text","getServerSideProps\ngetStaticProps\ngetStaticPaths"],["h","App Router"],["p","Uses:"],["code","text","app/\n  page.tsx\n  users/\n    [id]/\n      page.tsx"],["p","It supports modern Next.js patterns such as:"],["ul",["Server Components","Layouts","Streaming","Nested routing","Route handlers"]]],"realWorld":[["p","**Why it matters.** The App Router (React Server Components, nested layouts, streaming) is the modern default, while the Pages Router is still common in existing codebases. Teams need to migrate deliberately."],["p","**Example.** A company with a large Pages Router marketing site adds new product pages in the App Router, because both can coexist in one project. The new pages use server components to fetch data without shipping that code to the browser, and old pages keep working until they are migrated one by one."]]},{"id":2759,"category":"Next.js","difficulty":"Mid","question":"CSR vs SSR vs SSG vs ISR","answer":"Browser downloads JavaScript and fetches/render data on the client.","highlights":["Highly interactive dashboards","Private application interfaces","Personalized pages"],"body":[["h","CSR --- Client-Side Rendering"],["p","Good for:"],["ul",["Highly interactive dashboards","Private application interfaces"]],["h","SSR --- Server-Side Rendering"],["p","Server generates HTML for a request."],["p","Good for:"],["ul",["Personalized pages","Frequently changing server data"]],["h","SSG --- Static Site Generation"],["p","Pages are generated ahead of time."],["p","Good for:"],["ul",["Documentation","Marketing pages","Blogs"]],["h","ISR --- Incremental Static Regeneration"],["p","Static content can be regenerated/revalidated after deployment."],["p","Conceptually:"],["code","text","Cached page\n   |\n   | revalidation\n   v\nNew generated page"],["p","Choose based on data freshness and user requirements, not because one rendering mode is universally faster."]],"realWorld":[["p","**Why it matters.** Rendering strategy decides speed, SEO, freshness and server cost. The right answer depends on how often the data changes."],["p","**Example.** A news site uses ISR for article pages (static speed, revalidated every minute), SSR for a personalised 'my feed' that needs the user's cookies, SSG for the About page, and plain CSR for a logged-in analytics dashboard where SEO does not matter."]]},{"id":2760,"category":"Next.js","difficulty":"Mid","question":"What is hydration and why do hydration mismatches happen?","answer":"Hydration attaches React behavior to server-rendered HTML. A mismatch occurs when server output differs from the initial client render. The server and client can generate different timestamps.","highlights":["The process of attaching React behavior to server-rendered HTML."],"body":[["h","Quick recap"],["ul",["**What is hydration?** The process of attaching React behavior to server-rendered HTML."]],["p","Bad example:"],["code","tsx","function Component() {\n  return <div>{Date.now()}</div>;\n}"],["p","Another common source:"],["code","tsx","const width = window.innerWidth;"],["p","`window` does not exist during server rendering."],["p","Better:"],["code","tsx","const [width, setWidth] = useState<number | null>(null);\n\nuseEffect(() => {\n  setWidth(window.innerWidth);\n}, []);"]],"realWorld":[["p","**Why it matters.** A hydration mismatch means the server HTML differs from what React renders first on the client, causing warnings and flicker."],["p","**Example.** A component prints `new Date().toLocaleTimeString()` or reads `window.innerWidth` during render. The server renders 10:00:01, the browser renders 10:00:03, and React warns. Fix: render the value in `useEffect` after mount, or use `suppressHydrationWarning` only for harmless cases like timestamps."]]},{"id":2761,"category":"Next.js","difficulty":"Mid","question":"Server Components vs Client Components: when do you use each?","answer":"Keep components on the server when they do not need browser interactivity. This can reduce client JavaScript.","highlights":["They allow server-side work without shipping that component's implementation as client JavaScript, potentially reducing the browser bundle.","useEffect","Browser APIs"],"body":[["h","Quick recap"],["ul",["**Why use Server Components?** They allow server-side work without shipping that component's implementation as client JavaScript, potentially reducing the browser bundle."]],["p","In the App Router, components are server components by default unless marked:"],["code","tsx","\"use client\";"],["p","Client components are needed for:"],["ul",["`useState`","`useEffect`","Browser APIs","Event handlers","Interactive client-side behavior"]],["p","Example:"],["code","tsx","\"use client\";\n\nimport { useState } from \"react\";\n\nexport default function Counter() {\n  const [count, setCount] = useState(0);\n\n  return (\n    <button onClick={() => setCount(c => c + 1)}>\n      {count}\n    </button>\n  );\n}"]],"realWorld":[["p","**Why it matters.** Server components run only on the server and ship no JavaScript; client components handle interactivity. The skill is drawing the boundary in the right place."],["p","**Example.** A product page is a server component that queries the database directly and renders the description and reviews with zero client JS. Only the 'Add to cart' button and quantity picker are client components (`'use client'`), so the page loads fast and stays interactive where needed."]]},{"id":2762,"category":"Next.js","difficulty":"Junior","question":"Dynamic Routing","answer":"Dynamic routes are useful for product pages, user profiles, blog posts, etc.","highlights":[],"body":[["p","Example:"],["code","text","app/products/[id]/page.tsx"],["p","Then:"],["code","text","/products/123"],["p","can map to:"],["code","ts","export default async function ProductPage({\n  params\n}: {\n  params: Promise<{ id: string }>\n}) {\n  const { id } = await params;\n\n  return <div>Product {id}</div>;\n}"]],"realWorld":[["p","**Why it matters.** Dynamic routes map URL segments to parameters, which is how detail pages like `/products/42` are built from one file."],["p","**Example.** An insurance portal defines `app/policies/[policyId]/page.tsx`. Visiting `/policies/P-1029` passes `params.policyId` to load that policy, and `generateStaticParams` can pre-render the most-viewed policies at build time."]]},{"id":2763,"category":"Next.js","difficulty":"Mid","question":"Middleware Usage","answer":"Keep middleware lightweight. Do not turn it into a large backend application.","highlights":["Authentication checks","Redirects","Locale routing"],"body":[["p","Middleware can intercept requests for use cases such as:"],["ul",["Authentication checks","Redirects","Rewrites","Locale routing","Request-based policies"]],["p","Example concept:"],["code","ts","import { NextResponse } from \"next/server\";\nimport type { NextRequest } from \"next/server\";\n\nexport function middleware(request: NextRequest) {\n  const token = request.cookies.get(\"session\");\n\n  if (!token) {\n    return NextResponse.redirect(\n      new URL(\"/login\", request.url)\n    );\n  }\n\n  return NextResponse.next();\n}"]],"realWorld":[["p","**Why it matters.** Middleware runs before a request completes, so it is the right place for cheap checks that apply to many routes."],["p","**Example.** A banking app's middleware checks for a session cookie on every `/account/*` request and redirects anonymous visitors to `/login`, adds security headers, and rewrites `/in` to `/en-IN` based on locale, all before any page code runs."]]},{"id":2764,"category":"Next.js","difficulty":"Mid","question":"Image and Font Optimization","answer":"For fonts, Next.js provides font integration that can help optimize loading and avoid unnecessary layout shifts.","highlights":["Responsive sizing","Image optimization","Lazy loading"],"body":[["p","Use Next.js image tooling:"],["code","tsx","import Image from \"next/image\";\n\n<Image\n  src=\"/hero.jpg\"\n  alt=\"Dashboard\"\n  width={1200}\n  height={600}\n/>"],["p","Benefits can include:"],["ul",["Responsive sizing","Image optimization","Lazy loading","Better layout stability"]]],"realWorld":[["p","**Why it matters.** Images and fonts are the largest assets on most pages. Optimisation directly improves Core Web Vitals (LCP, CLS) and SEO."],["p","**Example.** A travel site replaces `<img>` tags with `next/image`, which serves WebP/AVIF at the right size with lazy loading, and loads fonts via `next/font` so there is no layout shift. Largest Contentful Paint dropped from 4 s to 1.8 s on mobile networks."]]},{"id":2765,"category":"Next.js","difficulty":"Mid","question":"Edge vs Serverless Functions","answer":"Trade-offs include cold starts and execution limits depending on platform.","highlights":["API endpoints","Background-ish request workloads","Variable traffic"],"body":[["h","Serverless"],["p","Good for:"],["ul",["API endpoints","Background-ish request workloads","Variable traffic"]],["h","Edge"],["p","Runs closer to users in distributed locations."],["p","Good for:"],["ul",["Low-latency request processing","Redirects","Personalization","Lightweight authorization logic"]],["p","Edge runtimes can have a different API/runtime environment than a full Node.js server."]],"realWorld":[["p","**Why it matters.** Edge functions run close to the user with low latency but a limited runtime; serverless functions run in a few regions with full Node.js capabilities."],["p","**Example.** A geolocation redirect and A/B test assignment run on the edge in a few milliseconds worldwide. A PDF-generation endpoint that needs Node libraries and a database connection runs as a regional serverless function."]]},{"id":2766,"category":"Next.js","difficulty":"Senior","question":"Caching and Revalidation","answer":"Caching should be designed around the data's freshness requirements. Do not cache sensitive personalized data in a shared cache.","highlights":[],"body":[["p","Examples:"],["code","text","Product catalog → cache aggressively\nUser account → request-specific\nStock price → short-lived cache/revalidation\nAdmin dashboard → fresh or controlled cache"],["p","A senior engineer should be able to explain:"],["code","text","Where is data cached?\nHow long?\nWho invalidates it?\nWhat happens after invalidation?"]],"realWorld":[["p","**Why it matters.** Next.js caches fetches and pages aggressively. Knowing when data is stale and how to revalidate prevents showing outdated prices or hiding fresh content."],["p","**Example.** A catalogue page uses `fetch(url, { next: { revalidate: 300 } })` so prices refresh every 5 minutes without a rebuild, and after an admin edits a product the API calls `revalidateTag('products')` so changes show up immediately."]]},{"id":2767,"category":"Next.js","difficulty":"Mid","question":"Next.js API routes vs a separate backend service: how do you decide?","answer":"BFF (Backend for Frontend); Small APIs; Form submissions; UI-specific endpoints","highlights":["Multiple clients","Complex domain logic","Independent scaling"],"body":[["h","Quick recap"],["ul",["**When would you use a separate backend?** When backend complexity, client diversity, independent scaling, domain boundaries, long-running jobs, or operational requirements exceed what a framework-integrated API layer should handle."]],["p","Next.js route handlers are convenient:"],["code","ts","export async function GET() {\n  return Response.json({\n    message: \"Hello\"\n  });\n}"],["p","They are a good fit for:"],["p","A separate backend service may be preferable when you need:"],["ul",["Multiple clients","Complex domain logic","Independent scaling","Long-running jobs","Extensive integrations","Separate deployment lifecycle"]]],"realWorld":[["p","**Why it matters.** Route handlers are convenient for light backend-for-frontend work, but a full backend is better for heavy, shared or long-running logic."],["p","**Example.** A Next.js app uses `/api/session` to set cookies and `/api/search` to proxy and shape a third-party response, while claims processing, queues and database transactions live in a Spring Boot/Node service shared with a mobile app."]]},{"id":2768,"category":"Next.js","difficulty":"Senior","question":"How do you handle authentication in Next.js (JWT, cookies, Auth.js)?","answer":"Important: signing a JWT does not automatically make its contents secret. Do not place sensitive information in a normal signed JWT payload.","highlights":[],"body":[["h","Cookie/session approach"],["p","The browser stores a secure session cookie."],["p","Recommended security attributes include:"],["code","text","HttpOnly\nSecure\nSameSite"],["h","JWT"],["p","A JWT can contain claims:"],["code","json","{\n  \"sub\": \"123\",\n  \"role\": \"admin\"\n}"],["h","Practical recommendation"],["p","For browser-based applications, secure, HTTP-only cookie-based sessions are often simpler and safer than storing tokens in `localStorage`."],["h","Also worth knowing"],["p","Recommended high-level architecture:"],["code","text","Browser\n   |\n   | HTTPS\n   v\nNext.js\n   |\n   +--> HTTP-only secure cookie\n   |\n   v\nSession/Auth layer\n   |\n   v\nDatabase"],["p","Avoid exposing private secrets through client bundles."],["p","Authorization must still be checked on the server for protected operations."]],"realWorld":[["p","**Why it matters.** Next.js adds server-side rendering and edge middleware to the auth picture. Where the token lives (HttpOnly cookie vs localStorage) decides security."],["p","**Example.** A customer portal uses Auth.js with an HttpOnly, Secure, SameSite cookie. Server components read the session on the server, middleware blocks unauthenticated routes, and no token is ever exposed to client JavaScript, reducing XSS risk."]]},{"id":2769,"category":"Next.js","difficulty":"Junior","question":"SEO Handling","answer":"Semantic HTML; Correct status codes; Canonical URLs; Structured data where appropriate; Crawlable content; Fast page delivery; Good mobile UX","highlights":[],"body":[["p","Next.js can provide metadata:"],["code","ts","export const metadata = {\n  title: \"Products\",\n  description: \"Browse our products\"\n};"],["p","SEO also depends on:"]],"realWorld":[["p","**Why it matters.** Search engines read the server-rendered HTML. Good metadata, structured data and fast rendering are what rank a page."],["p","**Example.** A recipe site exports `generateMetadata` for each page (title, description, Open Graph image), adds JSON-LD recipe schema and a sitemap. Server rendering means Googlebot sees the full content instead of an empty `<div id='root'>`."]]},{"id":2770,"category":"Next.js","difficulty":"Junior","question":"Environment Variables","answer":"Environment variables separate configuration and secrets from code. In Next.js only variables prefixed with `NEXT_PUBLIC_` reach the browser.","highlights":[],"body":[["p","Server-only:"],["code","env","DATABASE_URL=..."],["p","Client-exposed variables commonly use:"],["code","env","NEXT_PUBLIC_API_URL=..."],["p","Never expose:"],["code","env","DATABASE_PASSWORD=...\nJWT_PRIVATE_KEY=..."],["p","to client-side code."],["p","A useful rule:"],["code","text","If a value is secret, it must remain server-side."]],"realWorld":[["p","**Why it matters.** Environment variables separate configuration and secrets from code. In Next.js only variables prefixed with `NEXT_PUBLIC_` reach the browser."],["p","**Example.** The payment gateway secret key lives in `STRIPE_SECRET_KEY` (server only), while the publishable key is `NEXT_PUBLIC_STRIPE_KEY`. Accidentally prefixing a secret with `NEXT_PUBLIC_` would publish it in the JavaScript bundle for everyone."]]},{"id":2771,"category":"Next.js","difficulty":"Mid","question":"Why Next.js Can Improve Performance","answer":"The framework does not guarantee good performance automatically. Architecture, data access, bundle size, caching, and component design still matter.","highlights":["Server rendering","Static generation","Streaming"],"body":[["p","Next.js can combine:"],["ul",["Server rendering","Static generation","Streaming","Code splitting","Image optimization","Font optimization","Server Components","Caching"]]],"realWorld":[["p","**Why it matters.** Next.js improves performance through server rendering, automatic code splitting, image/font optimisation and caching, but only if used deliberately."],["p","**Example.** Moving a client-rendered dashboard to Next.js let it fetch data on the server near the database, send ready HTML, split each route's JS automatically and cache static parts, so first paint no longer waits for a chain of browser API calls."]]},{"id":2772,"category":"Node.js","difficulty":"Mid","question":"How does Node.js work internally, and how does a single thread handle many concurrent requests?","answer":"Node.js uses an event-driven, non-blocking architecture. The JavaScript execution environment uses a main thread, while asynchronous I/O can be handled by the runtime and operating system facilities.","highlights":["It avoids blocking the JavaScript thread for most I/O and uses event-driven asynchronous operations.","\"Node.js is single-threaded\" does not mean:","The entire server can only do one thing."],"body":[["h","Quick recap"],["ul",["**Why can Node handle many concurrent requests?** It avoids blocking the JavaScript thread for most I/O and uses event-driven asynchronous operations.","**Is JavaScript single-threaded?** JavaScript execution is generally single-threaded per agent, but the runtime provides asynchronous I/O and concurrency mechanisms. Node also supports worker threads."]],["h","Example"],["code","js","app.get(\"/users\", async (req, res) => {\n  const users = await db.query(\"SELECT * FROM users\");\n\n  res.json(users);\n});"],["p","While the database operation is waiting, Node.js can continue handling other work instead of synchronously waiting for the database."],["p","Conceptually:"],["code","text","Request A\n   ↓\nStart DB operation\n   ↓\nNode continues\n\nRequest B\n   ↓\nStart API operation\n   ↓\nNode continues\n\nDB A completes\n   ↓\nCallback/promise continuation\n   ↓\nResponse A"],["h","Important distinction"],["p","\"Node.js is single-threaded\" does **not** mean:"],["quote","The entire server can only do one thing."],["p","It means JavaScript execution is primarily handled on a main event-loop thread, while asynchronous operations can be handled by the OS/runtime and, for certain operations, a worker pool."],["h","What can still hurt Node?"],["p","CPU-heavy synchronous code:"],["code","js","app.get(\"/report\", (req, res) => {\n  for (let i = 0; i < 1e9; i++) {\n    // CPU-heavy operation\n  }\n\n  res.send(\"done\");\n});"],["p","That blocks the event loop."],["h","Interview answer"],["quote","Node.js handles concurrency through an event-driven, non-blocking model. The JavaScript thread starts asynchronous I/O and continues processing other requests. When the I/O completes, its callback or promise continuation is scheduled. CPU-heavy synchronous work can still block the event loop and hurt all requests."],["h","Also worth knowing"],["p","Node.js uses JavaScript execution through the V8 engine and an event-driven runtime built around asynchronous I/O."],["p","Simplified:"],["code","text","JavaScript\n    |\n    v\n   V8\n    |\n    v\nNode.js runtime\n    |\n    +--> Event loop\n    +--> Async I/O\n    +--> Timers\n    +--> OS resources\n    +--> libuv thread pool for certain operations"],["p","Node is especially effective for I/O-heavy workloads."],["h","Also worth knowing"],["p","Example:"],["code","js","server.on(\"request\", request => {\n  // handle request\n});"],["p","Instead of continuously blocking on every request, Node registers callbacks/events and continues processing other work."],["p","This model works particularly well for:"],["ul",["HTTP APIs","WebSockets","Streaming","I/O-heavy services"]],["h","Also worth knowing"],["p","The JavaScript execution model uses a main thread, but Node can handle many concurrent I/O operations because it does not block the main thread waiting for most I/O."],["p","Example:"],["code","js","const fs = require(\"fs\");\n\nfs.readFile(\"large.txt\", \"utf8\", (err, data) => {\n  console.log(data);\n});\n\nconsole.log(\"This can execute before file reading completes.\");"],["p","Node does not need one JavaScript thread per request."]],"realWorld":[["p","**Why it matters.** Node.js is single-threaded for JavaScript but delegates I/O to the OS and libuv, so one thread can wait on thousands of requests at once."],["p","**Example.** An API server handling 5,000 concurrent connections mostly waits on databases and HTTP calls. While one request waits for the DB, the event loop serves others. A synchronous `crypto.pbkdf2Sync` call or giant JSON parse, however, blocks every user until it finishes."]]},{"id":2773,"category":"Node.js","difficulty":"Mid","question":"Synchronous vs asynchronous and blocking vs non-blocking I/O in Node.js: why does it matter?","answer":"This is an especially important Node.js interview topic.","highlights":["They block the event loop and can delay unrelated requests.","await makes asynchronous code easier to read, but it does not mean the entire Node.js process becomes blocked like a synchronous API.","While the network operation is waiting, Node.js can handle other work."],"body":[["h","Quick recap"],["ul",["**Why are synchronous APIs dangerous in request handlers?** They block the event loop and can delay unrelated requests."]],["h","Synchronous operation"],["p","A synchronous operation blocks the current JavaScript execution until it completes."],["p","Example:"],["code","javascript","const fs = require(\"fs\");\n\nconst data = fs.readFileSync(\"large-file.txt\");\n\nconsole.log(\"File loaded\");"],["p","During the synchronous call, the JavaScript thread cannot continue processing other JavaScript work."],["h","Asynchronous operation"],["p","An asynchronous operation starts an operation and allows the event loop to continue handling other work."],["p","Example:"],["code","javascript","const fs = require(\"fs\");\n\nfs.readFile(\"large-file.txt\", (err, data) => {\n    if (err) {\n        console.error(err);\n        return;\n    }\n\n    console.log(\"File loaded\");\n});\n\nconsole.log(\"This can execute before the file callback\");"],["p","Modern Node.js also supports promises:"],["code","javascript","const fs = require(\"fs/promises\");\n\nasync function readFile() {\n    const data = await fs.readFile(\"large-file.txt\");\n    console.log(data.toString());\n}"],["h","Important point about async/await"],["p","`await` makes asynchronous code easier to read, but it does not mean the entire Node.js process becomes blocked like a synchronous API."],["p","Example:"],["code","javascript","async function getUser() {\n    const response = await fetch(\n        \"https://example.com/users/1\"\n    );\n\n    return response.json();\n}"],["p","While the network operation is waiting, Node.js can handle other work."],["h","Node.js Event Loop"],["p","Simplified:"],["code","text","                JavaScript\n                    |\n                    v\n               Event Loop\n                    |\n        +-----------+-----------+\n        |                       |\n    Immediate work        Async operations\n                                |\n                                v\n                         OS / libuv / system\n                                |\n                                v\n                           Completion\n                                |\n                                v\n                         Callback/Promise\n                                |\n                                v\n                           Event Loop"],["p","Node.js uses an event-driven architecture."],["p","Many I/O operations are handled without blocking the main JavaScript execution path."],["h","Why synchronous code can be dangerous in Node.js"],["p","Suppose:"],["code","javascript","app.get(\"/report\", (req, res) => {\n\n    const data = fs.readFileSync(\n        \"very-large-report.txt\"\n    );\n\n    res.send(data);\n});"],["p","If the file operation takes a long time, the JavaScript thread is blocked during that operation."],["p","Meanwhile:"],["code","text","User A -> /report\n              |\n              v\n       Blocking operation\n              |\nUser B -> /products ---- WAIT\nUser C -> /orders   ---- WAIT\nUser D -> /login    ---- WAIT"],["p","This can reduce throughput and increase latency."],["p","Prefer asynchronous I/O:"],["code","javascript","app.get(\"/report\", async (req, res) => {\n\n    const data = await fs.promises.readFile(\n        \"very-large-report.txt\"\n    );\n\n    res.send(data);\n});"],["h","CPU-bound vs I/O-bound operations"],["p","This distinction is extremely important in Node.js interviews."],["h","I/O-bound"],["p","Examples:"],["code","text","Database calls\nHTTP requests\nFile operations\nNetwork operations"],["p","Node.js handles these well using asynchronous APIs."],["h","CPU-bound"],["p","Examples:"],["code","text","Huge calculations\nImage processing\nComplex encryption workloads\nLarge data transformations"],["p","If CPU-heavy JavaScript runs on the main thread for a long time, it can block the event loop."],["p","Possible solutions include:"],["code","text","Worker Threads\nChild Processes\nSeparate services\nJob queues"],["p","Example:"],["code","javascript","const { Worker } = require(\"worker_threads\");\n\nconst worker = new Worker(\"./heavy-task.js\");"],["h","Synchronous vs Asynchronous Summary"],["table",["Feature","Synchronous","Asynchronous"],[["Blocks current JS execution","Usually yes","No while waiting for async I/O"],["Easy to understand","Yes","Slightly more complex"],["Good for high-concurrency I/O","Usually no","Yes"],["Common Node.js server pattern","Avoid blocking APIs","Preferred"],["Example","`readFileSync()`","`readFile()` / promises"]]],["h","Interview answer"],["quote","Synchronous operations block the current JavaScript execution until the operation completes. Asynchronous operations allow Node.js to continue handling other work while an I/O operation is in progress. This matters because Node.js uses an event loop and is particularly effective for I/O-heavy workloads. Blocking the event loop with synchronous or CPU-heavy operations can increase latency for other users. For CPU-heavy work, I would consider worker threads, separate processes, or an asynchronous job system."],["h","Also worth knowing"],["p","Node.js uses an event-driven architecture with an event loop."],["p","Simplified:"],["code","text","JavaScript code\n      |\n      v\n   Event Loop\n      |\n      +------------------+\n      |                  |\n   Ready work        Async I/O\n                         |\n                         v\n                    OS / libuv\n                         |\n                         v\n                    Completion\n                         |\n                         v\n                  Callback/Promise\n                         |\n                         v\n                    Event Loop"],["h","Example"],["code","javascript","console.log(\"A\");\n\nsetTimeout(() => {\n    console.log(\"B\");\n}, 0);\n\nconsole.log(\"C\");"],["p","Typical output:"],["code","text","A\nC\nB"],["p","The timer callback doesn't execute immediately just because the delay is `0`."],["p","It is scheduled for later."],["h","Promise example"],["code","javascript","console.log(\"A\");\n\nPromise.resolve().then(() => {\n    console.log(\"B\");\n});\n\nconsole.log(\"C\");"],["p","Typical output:"],["code","text","A\nC\nB"],["p","Promise callbacks are handled through the microtask mechanism and are processed before the event loop proceeds to later phases in the relevant turn."],["h","Async database example"],["code","javascript","app.get(\"/users/:id\", async (req, res) => {\n\n    const user = await userRepository.findById(\n        req.params.id\n    );\n\n    res.json(user);\n});"],["p","While the database request is waiting, Node.js can process other work."],["h","What blocks Node.js?"],["p","CPU-heavy JavaScript:"],["code","javascript","app.get(\"/report\", (req, res) => {\n\n    // Very expensive CPU calculation\n    const result = hugeCalculation();\n\n    res.json(result);\n});"],["p","If `hugeCalculation()` occupies the main thread for a long time, other requests can experience latency."],["p","Solutions:"],["code","text","Worker Threads\nChild Processes\nJob queues\nSeparate services\nAlgorithm optimization"],["h","Interview answer"],["quote","Node.js uses an event-driven architecture. Asynchronous I/O allows the process to continue handling other work while operations such as network or database I/O are pending. The event loop coordinates callbacks and promise continuations. The main concern is avoiding long-running CPU work on the event-loop thread because it can block other requests."],["h","Also worth knowing"],["p","Blocking:"],["code","js","const fs = require(\"fs\");\n\nconst data = fs.readFileSync(\"large.txt\", \"utf8\");\nconsole.log(data);"],["p","Non-blocking:"],["code","js","fs.readFile(\"large.txt\", \"utf8\", (err, data) => {\n  console.log(data);\n});"],["p","Avoid synchronous operations in latency-sensitive request paths."],["h","Interview answer"],["quote","Blocking I/O holds up the JavaScript execution thread until the operation completes. Non-blocking I/O starts the operation and allows Node.js to process other work while waiting. In production APIs, I avoid synchronous I/O on the request path unless there is a very specific reason."]],"realWorld":[["h","Real-world e-commerce example"],["p","Imagine:"],["code","text","GET /products"],["p","The server needs to query a database."],["p","Asynchronous:"],["code","text","Request\n   |\n   v\nNode.js\n   |\n   +--> DB request\n   |\n   +--> Handles other requests\n   |\n   +--> Handles other requests\n   |\n   +--> DB response\n            |\n            v\n          Response"],["p","This is why Node.js is well suited to I/O-heavy applications."],["h","Real-world banking example"],["p","Suppose:"],["code","text","POST /transactions"],["p","The API might need to call:"],["code","text","Transaction Service\n       |\n       +--> Fraud Service\n       |\n       +--> Account Service\n       |\n       +--> Notification Service"],["p","Some work may be asynchronous."],["p","For example, sending an email/SMS notification does not necessarily need to block the transaction response."],["p","A message broker can be used:"],["code","text","Transaction completed\n        |\n        v\nMessage Broker\n        |\n        +--> SMS Service\n        +--> Email Service\n        +--> Analytics"],["p","This improves decoupling and can reduce request latency."],["h","Real-world insurance example"],["p","After a claim is submitted:"],["code","text","POST /claims\n      |\n      v\nClaim Service\n      |\n      v\nClaim created\n      |\n      v\nMessage Broker\n   /      |       \\\n  v       v        v\nEmail   Document  Analytics"],["p","The customer does not necessarily need to wait for every downstream operation to finish."],["h","Real-world example"],["p","Imagine an API serving 100 users."],["p","If every request performs expensive synchronous file/database-related work on the event loop, one slow operation can delay other requests."],["p","Non-blocking I/O allows Node.js to keep processing other work while waiting for I/O."]]},{"id":2774,"category":"Node.js","difficulty":"Mid","question":"Streams and Buffers","answer":"Streams are important for large files because you do not need to load the entire file into memory.","highlights":[],"body":[["p","Buffers represent binary data:"],["code","js","const buffer = Buffer.from(\"Hello\");\n\nconsole.log(buffer);"],["p","Streams process data incrementally."],["code","js","const fs = require(\"fs\");\n\nconst stream = fs.createReadStream(\"large-file.txt\");\n\nstream.on(\"data\", chunk => {\n  console.log(\"Received chunk:\", chunk.length);\n});"]],"realWorld":[["p","**Why it matters.** Streams process data in chunks instead of loading everything into memory, which keeps memory flat for large files."],["p","**Example.** A report export endpoint pipes a 2 GB CSV from the database cursor through a transform stream straight to the HTTP response, using ~50 MB of memory. Reading it all with `readFile` first would exhaust memory with just a few simultaneous downloads."]]},{"id":2775,"category":"Node.js","difficulty":"Senior","question":"How do you handle CPU-intensive work in Node.js (worker threads, cluster, process vs thread)?","answer":"Creates multiple Node processes that can use multiple CPU cores. Each worker is a separate process with its own memory.","highlights":["When CPU-heavy JavaScript computation would otherwise block the event loop."],"body":[["h","Quick recap"],["ul",["**When should you use worker threads?** When CPU-heavy JavaScript computation would otherwise block the event loop."]],["h","Cluster"],["p","Conceptually:"],["code","text","             Load\n              |\n       +------+------+\n       |      |      |\n    Worker Worker Worker"],["h","Worker threads"],["p","Useful for CPU-intensive JavaScript work:"],["code","js","const { Worker } = require(\"node:worker_threads\");\n\nconst worker = new Worker(\"./worker.js\");\n\nworker.on(\"message\", result => {\n  console.log(result);\n});"],["p","Use worker threads when CPU work would otherwise block the event loop."],["h","Also worth knowing"],["p","Bad:"],["code","js","app.get(\"/report\", (req, res) => {\n  const result = expensiveCalculation();\n  res.json(result);\n});"],["p","If `expensiveCalculation()` blocks the event loop, other requests can suffer."],["p","Better approaches:"],["ul",["Worker threads","Job queues","Separate worker services","Background processing","Horizontal scaling"]],["h","Process"],["ul",["Own memory space","Strong isolation","Higher overhead","Communication through IPC or other mechanisms"]],["h","Thread"],["ul",["Shares process memory","Lower overhead","Can be useful for parallel CPU work","Requires careful synchronization when shared memory is involved"]],["p","Node's worker threads are different from spawning separate processes."],["h","Also worth knowing"],["p","Suppose:"],["code","js","app.get(\"/report\", (req, res) => {\n  const result = generateHugeReport();\n  res.json(result);\n});"],["p","If `generateHugeReport()` is CPU-heavy, it blocks the JavaScript thread."],["p","Better architecture:"],["code","text","HTTP Request\n     |\n     v\nCreate Job\n     |\n     v\nQueue\n     |\n     v\nWorker\n     |\n     v\nGenerate Report\n     |\n     v\nObject Storage"],["p","Client can poll:"],["code","text","GET /reports/:id"],["p","or receive completion through WebSocket/SSE/email depending on requirements."]],"realWorld":[["p","**Why it matters.** Node runs JavaScript on one thread, so using multiple CPU cores or offloading heavy work needs cluster, worker threads or separate services."],["p","**Example.** An image-resize API uses `worker_threads` so large resizes do not block other requests, and PM2/cluster runs one Node process per CPU core behind a load balancer to use the whole 8-core server. Heavier pipelines move to a queue with dedicated workers."]]},{"id":2776,"category":"Node.js","difficulty":"Senior","question":"How do you scale a Node.js application?","answer":"Avoid relying on process-local state.; Use shared databases/cache for shared state.; Use centralized logging.; Make services stateless where practical.","highlights":[],"body":[["p","Vertical scaling:"],["code","text","More CPU\nMore RAM"],["p","Horizontal scaling:"],["code","text","              Load Balancer\n              /    |    \\\n           Node  Node  Node"],["p","For horizontally scaled services:"]],"realWorld":[["p","**Why it matters.** Scaling Node means going horizontal: stateless processes behind a load balancer, plus caching and queues to keep each process light."],["p","**Example.** A ticket-booking API runs 10 containers behind a load balancer, stores sessions in Redis rather than memory so any instance can serve any user, moves email sending to a queue, and caches seat maps. Adding instances during sales needs no code change."]]},{"id":2777,"category":"Node.js","difficulty":"Mid","question":"What happens if a promise rejection is not handled? How do you handle errors in Node.js?","answer":"the runtime can report an unhandled promise rejection. The exact process-level behavior depends on the Node.js/runtime version and configuration, but in modern Node.js an unhandled rejection can terminate the process.","highlights":[],"body":[["p","Example:"],["code","js","Promise.reject(new Error(\"Database failed\"));"],["p","If there is no rejection handler:"],["code","js","Promise.reject(new Error(\"Database failed\"))\n  .catch(error => {\n    console.error(error);\n  });"],["h","Why is this dangerous?"],["p","Suppose:"],["code","js","async function processPayment() {\n  await paymentService.charge();\n}\n\nprocessPayment();"],["p","If `charge()` rejects and nobody handles the rejection, you can get an unhandled rejection."],["h","Better"],["code","js","async function processPayment() {\n  try {\n    await paymentService.charge();\n  } catch (error) {\n    logger.error(error);\n    throw error;\n  }\n}"],["p","At the request boundary:"],["code","js","app.post(\"/payment\", async (req, res, next) => {\n  try {\n    await processPayment();\n    res.sendStatus(200);\n  } catch (error) {\n    next(error);\n  }\n});"],["h","Interview answer"],["quote","An unhandled promise rejection is a production reliability issue. The runtime reports it and, depending on Node.js behavior/version, it can lead to process termination. I handle expected errors at the appropriate boundary and make sure background tasks also have explicit rejection handling."],["h","Also worth knowing"],["p","Async/await:"],["code","js","async function getUser() {\n  try {\n    const response = await fetch(\"https://example.com/user\");\n    return await response.json();\n  } catch (error) {\n    console.error(\"Failed to get user\", error);\n    throw error;\n  }\n}"],["p","For an HTTP server, centralize error handling rather than duplicating response logic everywhere."],["p","Never silently swallow errors:"],["code","js","try {\n  await doSomething();\n} catch {\n  // Bad: failure disappears\n}"]],"realWorld":[["h","Real-world example"],["p","A background job sends emails:"],["code","js","sendEmail()\n  .then(() => console.log(\"sent\"));"],["p","If it rejects without handling, the failure may be invisible or cause an application-level problem."],["p","**In practice.** A background job `await`s a call that rejects and nobody catches it. On modern Node.js an unhandled rejection can terminate the process, taking down every in-flight request. Wrapping calls in `try/catch`, adding a `process.on('unhandledRejection')` safety net that logs and exits cleanly, and letting the orchestrator restart the pod is the production pattern."]]},{"id":2778,"category":"Node.js","difficulty":"Senior","question":"How do you design error handling and logging for production (Express error middleware)?","answer":"I use consistent HTTP error responses, centralized error handling, structured logging, request IDs, monitoring, and proper redaction. Clients get safe messages, while internal logs contain enough diagnostic information to investigate the failure.","highlights":["Request IDs/correlation IDs","Structured logs","Appropriate log levels"],"body":[["p","I separate errors into categories."],["h","1. Expected/client errors"],["p","Examples:"],["code","text","400 → invalid request\n401 → not authenticated\n403 → not authorized\n404 → resource not found\n409 → conflict"],["h","2. Server errors"],["code","text","500 → unexpected server failure"],["h","Central error middleware"],["code","js","app.use((err, req, res, next) => {\n  logger.error({\n    error: err,\n    requestId: req.id,\n    path: req.path\n  });\n\n  res.status(err.statusCode || 500).json({\n    message: err.publicMessage || \"Internal server error\",\n    requestId: req.id\n  });\n});"],["h","Don't expose internal details"],["p","Bad:"],["code","json","{\n  \"message\": \"Mongo connection password xyz failed at internal.js:91\"\n}"],["p","Better:"],["code","json","{\n  \"message\": \"Internal server error\",\n  \"requestId\": \"abc-123\"\n}"],["p","The detailed information belongs in internal logs."],["h","Structured logging"],["p","Prefer logs such as:"],["code","js","logger.error({\n  event: \"document_upload_failed\",\n  userId,\n  documentId,\n  requestId,\n  error: error.message\n});"],["p","This makes searching and monitoring easier."],["h","Production considerations"],["p","Use:"],["ul",["Request IDs/correlation IDs","Structured logs","Appropriate log levels","Centralized log collection","Monitoring and alerts","Error tracking","Redaction of passwords/tokens/PII","Consistent API error responses"]],["h","Also worth knowing"],["p","Express error middleware has four parameters:"],["code","js","app.use((err, req, res, next) => {\n  console.error(err);\n\n  res.status(500).json({\n    message: \"Internal server error\"\n  });\n});"],["p","It should normally be registered after routes."],["p","A useful application architecture:"],["code","text","Route\n  ↓\nController\n  ↓\nService\n  ↓\nRepository/Database"],["p","Errors can then be translated into appropriate HTTP responses centrally."]],"realWorld":[["h","Real-world example"],["p","A document upload fails in production."],["p","The API returns:"],["code","json","{\n  \"message\": \"Upload failed\",\n  \"requestId\": \"req-7845\"\n}"],["p","The developer searches logs using `req-7845` and sees the internal failure without exposing sensitive details to the user."],["p","**In practice.** Express error middleware turns any thrown error into a consistent JSON response and logs it with a request id. Operators can search that id in the log platform to find the exact failing request without exposing stack traces to customers."]]},{"id":2779,"category":"Node.js","difficulty":"Junior","question":"How does middleware work in Express?","answer":"Middleware is a function that runs during the request/response lifecycle.","highlights":[],"body":[["p","Typical signature:"],["code","javascript","(req, res, next)"],["p","Example:"],["code","javascript","function logger(req, res, next) {\n\n    console.log(req.method, req.url);\n\n    next();\n}"],["p","Register:"],["code","javascript","app.use(logger);"],["p","Flow:"],["code","text","Request\n   |\n   v\nMiddleware 1\n   |\n   v\nMiddleware 2\n   |\n   v\nAuthentication\n   |\n   v\nController\n   |\n   v\nResponse"],["h","Authentication middleware"],["code","javascript","function authenticate(req, res, next) {\n\n    const token = req.headers.authorization;\n\n    if (!token) {\n        return res.status(401).json({\n            message: \"Unauthorized\"\n        });\n    }\n\n    // Validate token\n\n    next();\n}"],["p","Route:"],["code","javascript","app.get(\n    \"/orders\",\n    authenticate,\n    getOrders\n);"],["h","Error middleware"],["p","Express error middleware has four parameters:"],["code","javascript","function errorHandler(err, req, res, next) {\n\n    console.error(err);\n\n    res.status(500).json({\n        message: \"Internal server error\"\n    });\n}"],["h","Middleware order matters"],["p","Example:"],["code","javascript","app.use(requestLogger);\n\napp.use(authenticate);\n\napp.use(\"/api/orders\", orderRoutes);\n\napp.use(errorHandler);"],["p","A middleware can:"],["code","text","1. Modify req/res\n2. End the response\n3. Call next()\n4. Pass an error to error handling"],["h","Interview answer"],["quote","Express middleware functions run during the request-response lifecycle. They can inspect or modify the request and response, terminate the request, or call `next()` to continue. Middleware is commonly used for logging, authentication, authorization, validation, rate limiting, and error handling."],["h","Also worth knowing"],["p","Middleware can inspect or modify a request before the next handler."],["code","js","app.use((req, res, next) => {\n  console.log(req.method, req.url);\n  next();\n});"],["p","Flow:"],["code","text","Request\n   |\n   v\nMiddleware 1\n   |\n   v\nMiddleware 2\n   |\n   v\nRoute handler\n   |\n   v\nResponse"],["p","Middleware can:"],["ul",["Authenticate","Validate","Log","Parse","Add request context"]]],"realWorld":[["h","Banking example"],["p","Request:"],["code","text","POST /api/transfer"],["p","Middleware chain:"],["code","text","Request\n  |\n  v\nLogger\n  |\n  v\nRate Limiter\n  |\n  v\nAuthentication\n  |\n  v\nAuthorization\n  |\n  v\nValidation\n  |\n  v\nTransfer Controller"],["p","This separation makes cross-cutting concerns easier to manage."],["p","**In practice.** A request to `/api/orders` passes through logging, CORS, JSON body parsing, authentication and a rate limiter before reaching the route handler. Because middleware order matters, authentication must be registered before protected routes or anonymous users can slip through."]]},{"id":2780,"category":"Node.js","difficulty":"Junior","question":"Explain the request-response lifecycle: how do the client and server communicate?","answer":"Explain API flow from request to response.","highlights":[],"body":[["h","Example"],["code","text","GET /api/documents/123\n          ↓\nAuthentication middleware\n          ↓\nController\n          ↓\nService\n          ↓\nRepository\n          ↓\nPostgreSQL\n          ↓\nEntity/DTO\n          ↓\nController response\n          ↓\nJSON\n          ↓\nReact"],["h","Backend example"],["code","js","app.get(\"/documents/:id\", async (req, res, next) => {\n  try {\n    const document = await documentService.findById(req.params.id);\n\n    if (!document) {\n      return res.status(404).json({\n        message: \"Document not found\"\n      });\n    }\n\n    res.json(document);\n  } catch (error) {\n    next(error);\n  }\n});"],["h","Flow"],["code","text","Client\n  ↓\nHTTP Request\n  ↓\nNode.js Server\n  ↓\nMiddleware\n  ↓\nRoute\n  ↓\nController\n  ↓\nService\n  ↓\nDatabase / External API\n  ↓\nResponse\n  ↓\nClient"],["h","Example"],["code","js","app.get(\"/users/:id\", async (req, res, next) => {\n  try {\n    const user = await userService.getUser(req.params.id);\n\n    res.status(200).json(user);\n  } catch (error) {\n    next(error);\n  }\n});"],["h","Interview answer"],["quote","The client sends an HTTP request to the Node.js server. The request passes through middleware such as authentication or logging, then reaches the matching route/controller. The controller calls the service layer, which performs business logic and communicates with the database or external services. Once the operation completes, the server sends an HTTP response back to the client."],["h","Also worth knowing"],["p","They communicate using a network protocol, commonly HTTP/HTTPS."],["h","Example"],["code","http","GET /api/documents/123\nAuthorization: Bearer <token>\nAccept: application/json"],["p","Server:"],["code","http","HTTP/1.1 200 OK\nContent-Type: application/json"],["code","json","{\n  \"id\": \"123\",\n  \"name\": \"Policy.pdf\"\n}"],["h","Interview answer"],["quote","The client communicates with the server through HTTP or HTTPS requests. The request contains the method, URL, headers and sometimes a body. The server processes it and returns a status code, headers and response body. In a frontend application, an API client such as RTK Query can manage these requests and their state."]],"realWorld":[["h","Real-world example"],["p","For your document platform, the request could be:"],["code","text","User clicks \"View Document\"\n        ↓\nFrontend requests document\n        ↓\nBackend verifies access\n        ↓\nBackend retrieves document metadata\n        ↓\nDocument/viewer information returned\n        ↓\nViewer renders document"],["p","**In practice.** When a customer opens their order page, the browser sends `GET /orders/42` to the API, the server authenticates the token, queries the database, builds a JSON response and returns status 200. A trace of this path (browser, gateway, API, DB) is also exactly how you find which hop is slow."]]},{"id":2781,"category":"Node.js","difficulty":"Mid","question":"How do you handle file uploads (including large files) in Node.js?","answer":"This prevents large files from unnecessarily passing through your application server.","highlights":["File size","MIME type","Actual file signature where appropriate"],"body":[["p","Use multipart/form-data."],["p","Express example with Multer:"],["code","js","import multer from \"multer\";\n\nconst upload = multer({\n  dest: \"uploads/\"\n});\n\napp.post(\n  \"/upload\",\n  upload.single(\"file\"),\n  (req, res) => {\n    res.json({\n      filename: req.file.filename\n    });\n  }\n);"],["h","Production considerations"],["p","Never rely only on the file extension."],["p","Validate:"],["ul",["File size","MIME type","Actual file signature where appropriate","Filename/path safety","User permissions","Storage limits"]],["p","For large production systems, upload directly to object storage such as S3-compatible storage using signed URLs:"],["code","text","Browser\n   |\n   | request signed URL\n   v\nAPI\n   |\n   | signed upload URL\n   v\nObject Storage"],["h","Also worth knowing"],["p","Poor architecture:"],["code","text","Browser\n   |\n   v\nNode/Next server\n   |\n   v\nStorage"],["p","Better for large files:"],["code","text","Browser\n   |\n   | 1. Request signed URL\n   v\nAPI\n   |\n   | 2. Signed URL\n   v\nBrowser\n   |\n   | 3. Direct upload\n   v\nObject Storage"],["p","Benefits:"],["ul",["Lower application-server bandwidth","Better scalability","Reduced memory pressure","Better handling of large files"]]],"realWorld":[["p","**Why it matters.** File uploads combine security, memory and reliability concerns: size limits, type checks, streaming and storage."],["p","**Example.** A KYC document upload uses `multer` with a 5 MB limit and MIME checks, streams the file directly to S3 (not local disk), stores only the S3 key in the database, scans for malware, and uses pre-signed URLs for very large files so the Node server never touches the bytes."]]},{"id":2782,"category":"API Design","difficulty":"Mid","question":"RESTful API Design Principles","answer":"Consistent REST design makes an API predictable, cacheable and easy for other teams to consume.","highlights":[],"body":[["p","Good:"],["code","text","GET    /api/v1/users\nGET    /api/v1/users/123\nPOST   /api/v1/users\nPATCH  /api/v1/users/123\nDELETE /api/v1/users/123"],["p","Avoid action-heavy endpoints when a resource operation communicates the intent:"],["code","text","POST /users/123/delete"],["p","can often be:"],["code","text","DELETE /users/123"],["p","Use HTTP status codes meaningfully:"],["code","text","200 OK\n201 Created\n204 No Content\n400 Bad Request\n401 Unauthorized\n403 Forbidden\n404 Not Found\n409 Conflict\n422 Unprocessable Content\n429 Too Many Requests\n500 Internal Server Error"]],"realWorld":[["p","**Why it matters.** Consistent REST design makes an API predictable, cacheable and easy for other teams to consume."],["p","**Example.** An e-commerce API exposes `GET /orders`, `POST /orders`, `GET /orders/42`, `PATCH /orders/42` using nouns, correct status codes (201 Created, 404 Not Found), pagination and versioning. A mobile team can guess most endpoints without reading docs."]]},{"id":2783,"category":"API Design","difficulty":"Mid","question":"Pagination: offset vs cursor, and why does pagination matter?","answer":"Pagination means returning data in smaller pages instead of returning the entire dataset.","highlights":["It can provide more stable and efficient pagination for large, changing datasets.","Network payload","Backend processing"],"body":[["h","Quick recap"],["ul",["**Why use cursor pagination?** It can provide more stable and efficient pagination for large, changing datasets."]],["h","Without pagination"],["code","http","GET /documents"],["p","Could return:"],["code","text","500,000 documents"],["p","This is expensive."],["h","With pagination"],["code","http","GET /documents?page=1&limit=50"],["p","Response:"],["code","json","{\n  \"data\": [],\n  \"page\": 1,\n  \"limit\": 50,\n  \"total\": 500000\n}"],["h","Why?"],["p","Pagination reduces:"],["ul",["Network payload","Backend processing","Database result size","Client memory","Rendering work"]],["h","Offset pagination"],["code","sql","SELECT *\nFROM documents\nORDER BY id\nLIMIT 50 OFFSET 1000;"],["p","Simple, but very large offsets can become expensive."],["h","Cursor/keyset pagination"],["p","Conceptually:"],["code","http","GET /documents?limit=50&after=DOC1050"],["p","This can perform better for very large datasets when designed appropriately."],["h","Interview answer"],["quote","Pagination prevents the application from loading huge datasets at once. For normal screens, offset pagination can be simple and effective. For very large or frequently changing datasets, cursor-based pagination can be more efficient and consistent."],["h","Offset pagination"],["code","text","GET /users?page=3&limit=20"],["p","Easy to implement, but can become inconsistent or expensive with large changing datasets."],["h","Cursor pagination"],["code","text","GET /users?limit=20&cursor=abc123"],["p","The server returns a cursor for the next page."],["p","Cursor pagination is often better for large, frequently changing datasets."],["p","Example response:"],["code","json","{\n  \"data\": [],\n  \"nextCursor\": \"abc123\"\n}"]],"realWorld":[["p","**Why it matters.** Returning all rows kills performance and memory. Pagination bounds response size and gives predictable latency."],["p","**Example.** A document search that returned 100,000 records timed out and crashed the browser. Switching to `?page=1&size=50` (offset) for admin tables and cursor-based `?after=docId` for the infinite-scroll feed gave constant response times and stable results while new documents arrive."]]},{"id":2784,"category":"API Design","difficulty":"Senior","question":"How do you design API rate limiting (login attempts, token bucket, sliding window)?","answer":"I would implement layered rate limiting at the edge and authentication service. I would consider IP, account, device, and combined identity signals rather than relying on a single key. For a distributed system, the rate-limit state should be shared, for example through Redis. Token Bucket or Sliding Window are possible algorithms. After the threshold is exceeded, I would return 429 and apply progressive delays, MFA or additional verification depending on risk.","highlights":["Allows controlled bursts","Controls average request rate"],"body":[["p","Authentication endpoints need strong protection because attackers can perform:"],["code","text","Brute-force attacks\nCredential stuffing\nPassword spraying"],["h","Basic design"],["code","text","Client\n  |\n  v\nWAF / API Gateway\n  |\n  v\nRate Limiter\n  |\n  +--> Allowed --> Auth Service\n  |\n  +--> Blocked --> 429 Too Many Requests"],["h","What should we rate-limit?"],["p","Do not rely only on IP."],["p","Possible dimensions:"],["code","text","IP address\nUsername/account\nDevice/session\nIP + username\nASN/network signals\nGeographic/risk signals"],["p","Why?"],["p","If you only rate-limit IP:"],["code","text","Attacker\n |\n +--> IP 1\n +--> IP 2\n +--> IP 3\n +--> IP 4"],["p","They can rotate IP addresses."],["p","If you only rate-limit username, an attacker could target many users."],["p","Use layered controls."],["h","Example policy"],["p","Illustrative only:"],["code","text","Per IP:\n    100 attempts / minute\n\nPer account:\n    10 failed attempts / 10 minutes\n\nRepeated failures:\n    progressive delay / additional verification\n\nHigh-risk behavior:\n    CAPTCHA / MFA / block"],["p","Exact limits should be determined from the application's threat model and normal traffic."],["h","Distributed rate limiting"],["p","If there are multiple authentication servers:"],["code","text","              Load Balancer\n              /     |     \\\n             v      v      v\n           Auth1  Auth2  Auth3\n             \\      |      /\n              \\     |     /\n                   v\n                 Redis"],["p","All instances can use shared counters."],["h","Token Bucket"],["p","A common algorithm is the **Token Bucket**."],["p","Conceptually:"],["code","text","Bucket capacity = 10 tokens\n\nEach request:\n    consume 1 token\n\nTokens refill gradually.\n\nNo token:\n    reject/throttle"],["p","Advantages:"],["ul",["Allows controlled bursts","Controls average request rate"]],["h","Sliding Window"],["p","Another approach:"],["code","text","10 requests\nwithin last 60 seconds"],["p","Can be implemented using counters or sorted sets depending on the system."],["h","Response"],["p","Typically:"],["code","http","HTTP/1.1 429 Too Many Requests"],["p","The API may include a `Retry-After` header when appropriate."],["h","Also worth knowing"],["p","Rate limiting protects APIs from abuse and accidental overload."],["p","Example policy:"],["code","text","100 requests / minute / user"],["p","A common distributed approach uses Redis:"],["code","text","Request\n   |\n   v\nRate limiter\n   |\n   +--> limit exceeded → 429\n   |\n   v\nApplication"],["p","Common algorithms:"],["ul",["Fixed window","Sliding window","Token bucket","Leaky bucket"]],["p","For distributed deployments, a centralized/shared rate-limit store is usually preferable to a per-process in-memory counter."]],"realWorld":[["h","Banking example"],["code","text","Login\n  |\n  +--> IP reputation\n  +--> Account attempt counter\n  +--> Device risk\n  +--> MFA\n  +--> Fraud/risk engine"],["p","Authentication rate limiting should be combined with broader fraud and account-protection controls."],["p","**In practice.** A bank limits login attempts to 5 per 15 minutes per account and IP using Redis counters with a sliding window. After the limit the API returns `429 Too Many Requests` with a `Retry-After` header, which blunts credential-stuffing attacks without blocking real customers at other IPs."]]},{"id":2785,"category":"API Design","difficulty":"Mid","question":"Input Validation and Sanitization","answer":"Sanitization/encoding should be applied according to the context in which data will be used.","highlights":[],"body":[["p","Never trust client input."],["p","Example using Zod:"],["code","ts","import { z } from \"zod\";\n\nconst CreateUserSchema = z.object({\n  name: z.string().min(1).max(100),\n  email: z.string().email()\n});\n\nconst result = CreateUserSchema.safeParse(req.body);\n\nif (!result.success) {\n  return res.status(400).json({\n    message: \"Invalid request\"\n  });\n}\n\nconst data = result.data;"],["p","Validation checks shape and constraints."]],"realWorld":[["p","**Why it matters.** Never trust client input. Validation rejects bad data early, sanitisation removes dangerous content, and both prevent injection and corrupt records."],["p","**Example.** A registration endpoint validates email, age and password length with Joi/Zod before touching the database, uses parameterised queries to stop SQL injection and escapes user-supplied names before rendering them in emails, preventing stored XSS."]]},{"id":2786,"category":"API Design","difficulty":"Mid","question":"API Versioning","answer":"Versioning is useful for breaking API changes. Prefer backward-compatible evolution when possible. For example, adding a new response field is generally less disruptive than renaming/removing an existing field.","highlights":[],"body":[["p","Common strategy:"],["code","text","/api/v1/users\n/api/v2/users"]],"realWorld":[["p","**Why it matters.** Versioning lets you change an API without breaking existing clients, especially mobile apps that users do not update immediately."],["p","**Example.** A bank exposes `/api/v1/accounts` to old mobile app versions and `/api/v2/accounts` with a new response shape for the latest release. v1 stays alive for months with a deprecation header and sunset date, then is removed once usage drops to near zero."]]},{"id":2787,"category":"API Design","difficulty":"Mid","question":"What is CORS? Is it an API security mechanism?","answer":"CORS controls whether browser JavaScript from one origin can access resources from another origin. These are different origins because the host differs.","highlights":["CORS primarily controls browser cross-origin access. It is not authentication and does not stop direct non-browser HTTP clients."],"body":[["h","Quick recap"],["ul",["**Is CORS an API security mechanism?** CORS primarily controls browser cross-origin access. It is not authentication and does not stop direct non-browser HTTP clients."]],["p","Example:"],["code","text","Frontend:\nhttps://app.example.com\n\nAPI:\nhttps://api.example.com"],["p","Express configuration:"],["code","js","import cors from \"cors\";\n\napp.use(cors({\n  origin: \"https://app.example.com\",\n  credentials: true\n}));"],["p","Do not blindly use:"],["code","js","origin: \"*\""],["p","especially when credentials/cookies are involved."],["p","Important: CORS is primarily a browser security mechanism. It is not an authentication system and does not stop non-browser clients from directly calling an API."]],"realWorld":[["p","**Why it matters.** CORS is a browser rule that controls which origins can read responses. It is not authentication and does nothing for non-browser clients."],["p","**Example.** A React app on `app.example.com` calling `api.example.com` fails with a CORS error until the API returns `Access-Control-Allow-Origin: https://app.example.com`. Setting `*` with credentials is blocked, and cURL or Postman ignore CORS entirely, so the API still needs real authentication."]]},{"id":2788,"category":"API Design","difficulty":"Mid","question":"API Design Checklist","answer":"A checklist keeps API design reviews consistent and catches missing concerns like auth, validation and idempotency early.","highlights":[],"body":[["p","A good REST API should consider:"],["code","text","Resource naming\nHTTP method\nStatus codes\nValidation\nAuthentication\nAuthorization\nPagination\nSorting\nFiltering\nIdempotency\nError response\nVersioning\nRate limiting\nObservability"],["h","Example"],["code","http","GET /api/v1/orders?page=0&size=20"],["p","Create:"],["code","http","POST /api/v1/orders"],["p","Update:"],["code","http","PUT /api/v1/orders/123"],["p","Partial update:"],["code","http","PATCH /api/v1/orders/123"],["p","Delete:"],["code","http","DELETE /api/v1/orders/123"]],"realWorld":[["p","**Why it matters.** A checklist keeps API design reviews consistent and catches missing concerns like auth, validation and idempotency early."],["p","**Example.** Before shipping a new `POST /payments` endpoint a team walks the checklist: auth, input validation, idempotency key, rate limiting, pagination (for lists), error format, versioning, logging and documentation. Two gaps (no idempotency, no rate limit) were caught in review rather than in production."]]},{"id":2789,"category":"API Design","difficulty":"Mid","question":"HTTP Status Codes to Remember","answer":"Correct status codes tell clients how to react (retry, re-login, show a validation error) without parsing the message.","highlights":[],"body":[["p","Code Meaning"]],"realWorld":[["p","**Why it matters.** Correct status codes tell clients how to react (retry, re-login, show a validation error) without parsing the message."],["p","**Example.** A client retries `503` and `429` with backoff, redirects to login on `401`, shows field errors for `400/422`, and shows 'not allowed' for `403`. An API that returns `200` with an error inside the body breaks monitoring dashboards because every failure looks like a success."]]},{"id":2790,"category":"API Design","difficulty":"Senior","question":"How would you design scalable backend APIs?","answer":"I design APIs to be stateless where possible, validate inputs, enforce authorization, paginate large datasets, optimize database access, handle failures consistently and provide observability. As traffic grows, services can be scaled horizontally behind a load balancer.","highlights":["Authentication","Authorization","Validation"],"body":[["p","I would start with requirements and then design:"],["code","text","Client\n  ↓\nLoad Balancer/API Gateway\n  ↓\nStateless Services\n  ↓\nCache / Database\n  ↓\nExternal Services"],["h","API principles"],["code","text","GET     → retrieve\nPOST    → create\nPUT/PATCH → update\nDELETE  → delete"],["h","Important areas"],["ul",["Authentication","Authorization","Validation","Pagination","Rate limiting","Caching","Idempotency","Error handling","Logging","Monitoring","Database indexing","Horizontal scalability"]],["h","Example"],["code","http","GET /api/documents?status=ACTIVE&limit=50"],["p","The API should not return millions of records."]],"realWorld":[["p","**Why it matters.** Scalable APIs are stateless, bounded and observable: paginated, cached, rate-limited and backed by indexed queries."],["p","**Example.** A document service handles millions of requests by keeping instances stateless behind a load balancer, caching hot reads in Redis, paginating every list endpoint, indexing search columns, moving slow work (PDF generation, notifications) to a queue and exposing metrics for latency and error rate."]]},{"id":2791,"category":"GraphQL","difficulty":"Mid","question":"REST vs GraphQL: when do you use which?","answer":"REST is resource-oriented and uses standard HTTP semantics, making it simple and operationally familiar. GraphQL gives clients more control over the fields they request and can be useful when clients need flexible, nested data. I would choose based on client requirements, caching needs, query complexity, operational maturity, and team expertise rather than treating one as universally better.","highlights":[],"body":[["h","REST"],["p","REST commonly exposes resources through HTTP endpoints."],["p","Example:"],["code","text","GET /users/123\nGET /orders/456\nGET /products\nPOST /orders"],["p","Response:"],["code","json","{\n    \"id\": 123,\n    \"name\": \"Arjun\"\n}"],["h","GraphQL"],["p","GraphQL commonly exposes a schema and a query endpoint."],["p","Example:"],["code","graphql","query {\n    user(id: \"123\") {\n        id\n        name\n        orders {\n            id\n            total\n        }\n    }\n}"],["p","The client specifies the fields it needs."],["h","REST advantages"],["code","text","Simple\nHTTP-native\nEasy caching patterns\nEasy to understand\nWorks well for resource-oriented APIs"],["h","GraphQL advantages"],["code","text","Client controls requested fields\nCan reduce over-fetching\nUseful for complex frontend data requirements\nStrong schema\nCan combine related data in one query"],["h","REST disadvantages"],["p","Sometimes the frontend needs:"],["code","text","GET /user\nGET /user/orders\nGET /user/preferences"],["p","This can create multiple requests."],["h","GraphQL disadvantages"],["p","GraphQL introduces additional complexity around:"],["code","text","Caching\nAuthorization\nQuery complexity\nN+1 queries\nMonitoring\nRate limiting\nSchema management"],["h","N+1 problem"],["p","A GraphQL query might request:"],["code","text","User\n  |\n  +--> Order 1\n  +--> Order 2\n  +--> Order 3"],["p","A naive implementation could execute many database queries."],["p","Solutions include:"],["code","text","DataLoader\nBatching\nProper joins/query planning\nCaching"],["h","When I would choose REST"],["p","Use REST when:"],["code","text","Simple resource-oriented APIs\nPublic APIs\nStraightforward CRUD\nHTTP caching is important\nTeam wants simpler architecture"],["h","When I would choose GraphQL"],["p","Consider GraphQL when:"],["code","text","Multiple frontend clients need different fields\nComplex related data\nMobile/web clients have different data requirements\nFrontend teams need flexible queries"],["h","REST"],["p","Resource-oriented endpoints:"],["code","text","GET    /users\nGET    /users/123\nPOST   /users\nPATCH  /users/123\nDELETE /users/123"],["p","Advantages:"],["ul",["Simple mental model","Excellent HTTP tooling","Caching semantics","Easy observability"]],["h","GraphQL"],["p","Client asks for the exact fields it needs:"],["code","graphql","query {\n  user(id: \"123\") {\n    id\n    name\n    orders {\n      id\n    }\n  }\n}"],["p","Advantages:"],["ul",["Flexible queries","Strong schema","Avoids some over-fetching"]],["p","Trade-offs:"],["ul",["More complex caching","Query complexity control","Authorization can be more involved"]],["p","Choose based on product and client requirements."]],"realWorld":[["h","E-commerce example"],["p","REST:"],["code","text","GET /products/123\nGET /products/123/reviews\nGET /products/123/recommendations"],["p","GraphQL:"],["code","graphql","query {\n    product(id: \"123\") {\n        name\n        price\n        reviews {\n            rating\n        }\n        recommendations {\n            name\n            price\n        }\n    }\n}"],["p","**In practice.** A mobile app that needs one screen of data from five resources benefits from GraphQL (one request, only the fields needed), while a simple public product catalogue with heavy CDN caching is easier and cheaper to serve with REST."]]},{"id":2792,"category":"JWT","difficulty":"Junior","question":"Authentication vs authorization: JWT, OAuth 2.0, 401 vs 403","answer":"Never put sensitive secrets such as passwords inside JWT claims.","highlights":["Authentication establishes identity; authorization determines permissions."],"body":[["h","Quick recap"],["ul",["**Authentication vs authorization?** Authentication establishes identity; authorization determines permissions."]],["h","Authentication"],["p","Answers:"],["code","text","Who are you?"],["p","Example:"],["code","text","Username + password\nMFA\nIdentity provider"],["h","Authorization"],["p","Answers:"],["code","text","What can you access?"],["p","Example:"],["code","text","CUSTOMER -> Own orders\nADMIN    -> All orders"],["h","JWT"],["p","JWT is a token format."],["p","Example:"],["code","text","Authorization: Bearer <JWT>"],["p","Conceptually:"],["code","text","Header.Payload.Signature"],["p","A token may contain claims such as:"],["code","json","{\n    \"sub\": \"user123\",\n    \"roles\": [\"CUSTOMER\"],\n    \"exp\": 1760000000\n}"],["h","OAuth 2.0"],["p","OAuth 2.0 is primarily an authorization framework."],["p","For user authentication/login scenarios, OAuth 2.0 is commonly paired with **OpenID Connect (OIDC)**."],["p","A common browser/mobile pattern is:"],["code","text","User\n |\n v\nFrontend\n |\n v\nAuthorization Server\n |\n | authorization code\n v\nFrontend\n |\n | code + PKCE\n v\nAuthorization Server\n |\n v\nTokens\n |\n v\nAPI"],["h","Example architecture"],["code","text","React\n  |\n  v\nIdentity Provider\n  |\n  v\nAccess Token\n  |\n  v\nNode.js API\n  |\n  v\nAuthorization\n  |\n  v\nBusiness logic"],["h","Role-based authorization"],["code","javascript","function requireRole(role) {\n\n    return (req, res, next) => {\n\n        if (!req.user?.roles?.includes(role)) {\n            return res.status(403).json({\n                message: \"Forbidden\"\n            });\n        }\n\n        next();\n    };\n}"],["p","Example:"],["code","javascript","app.delete(\n    \"/admin/products/:id\",\n    authenticate,\n    requireRole(\"ADMIN\"),\n    deleteProduct\n);"],["h","401 vs 403"],["code","text","401 Unauthorized\n    |\n    +--> Authentication is missing/invalid\n\n403 Forbidden\n    |\n    +--> User is authenticated but not allowed"],["h","Security best practices"],["p","Use:"],["code","text","HTTPS\nStrong password hashing\nMFA where appropriate\nShort-lived access tokens\nSecure refresh-token strategy\nAuthorization checks\nRate limiting\nInput validation\nSecure cookie settings where cookies are used\nCSRF defenses where applicable\nAudit logging"],["h","Authentication"],["p","\"Who are you?\""],["p","Example:"],["code","text","User logs in with credentials."],["h","Authorization"],["p","\"What are you allowed to do?\""],["p","Example:"],["code","js","if (user.role !== \"admin\") {\n  return res.status(403).json({\n    message: \"Forbidden\"\n  });\n}"],["p","Remember:"],["code","text","401 = not authenticated / authentication required\n403 = authenticated but not allowed"]],"realWorld":[["p","**Why it matters.** Authentication proves who you are; authorisation decides what you may do. OAuth 2.0 delegates access and JWT is one token format."],["p","**Example.** A customer logs in (authentication) and receives a token with role `CUSTOMER`. Viewing their own policy is allowed, but opening another customer's policy returns `403 Forbidden` (authorisation). A missing or expired token returns `401 Unauthorized`."]]},{"id":2793,"category":"JWT","difficulty":"Mid","question":"How does JWT authentication work end to end (secure flow, refresh tokens)?","answer":"The client authenticates with the backend, the backend validates credentials and issues a signed access token, and the client sends that token with protected requests. The backend verifies the token and then performs authorization checks. JWT is not a replacement for authorization or secure token management.","highlights":["Use HTTPS.","Use short-lived access tokens where appropriate.","Protect signing secrets."],"body":[["p","JWT means **JSON Web Token**."],["p","A typical flow:"],["code","text","Mobile/Web Client\n      ↓\nPOST /login\n      ↓\nServer verifies credentials\n      ↓\nServer issues access token\n      ↓\nClient stores token securely\n      ↓\nClient sends token with API requests\n      ↓\nServer verifies signature/claims\n      ↓\nRequest is authorized"],["h","Login"],["code","http","POST /login\nContent-Type: application/json\n\n{\n  \"email\": \"user@example.com\",\n  \"password\": \"password\"\n}"],["p","Server verifies the credentials."],["p","Then:"],["code","js","const token = jwt.sign(\n  {\n    sub: user.id,\n    role: user.role\n  },\n  process.env.JWT_SECRET,\n  {\n    expiresIn: \"15m\"\n  }\n);"],["p","Response:"],["code","json","{\n  \"accessToken\": \"...\"\n}"],["h","API request"],["p","The client sends:"],["code","http","Authorization: Bearer <token>"],["p","Server verifies:"],["code","js","const payload = jwt.verify(\n  token,\n  process.env.JWT_SECRET\n);"],["p","Then authorization can check:"],["code","js","if (payload.role !== \"admin\") {\n  return res.status(403).json({\n    message: \"Forbidden\"\n  });\n}"],["h","Authentication vs authorization"],["p","**Authentication:**"],["quote","Who are you?"],["p","**Authorization:**"],["quote","What are you allowed to do?"],["p","JWT can carry identity/claims, but your application still needs authorization rules."],["h","Important security points"],["ul",["Use HTTPS.","Use short-lived access tokens where appropriate.","Protect signing secrets.","Validate issuer/audience where your architecture requires it.","Don't put sensitive secrets/passwords inside JWT payloads.","Have a token refresh/revocation strategy when needed.","For mobile apps, use secure platform storage rather than plain unprotected storage for sensitive credentials/tokens."]],["h","Architecture"],["code","text","React\n  |\n  | Login\n  ↓\nSpring Boot\n  |\n  | Validate credentials\n  ↓\nDatabase\n  |\n  ↓\nJWT\n  |\n  ↓\nReact"],["p","For subsequent API calls:"],["code","text","React\n  |\n  | Access Token\n  ↓\nAPI\n  |\n  ↓\nJWT Filter\n  |\n  ↓\nValidate Token\n  |\n  ↓\nController"],["h","JWT contains"],["p","Typical claims:"],["code","json","{\n  \"sub\": \"user123\",\n  \"roles\": [\"USER\"],\n  \"exp\": 1790000000\n}"],["p","Never put sensitive information such as passwords in a JWT."],["h","Spring Security example"],["code","java","@Bean\nSecurityFilterChain securityFilterChain(HttpSecurity http)\n        throws Exception {\n\n    return http\n        .csrf(csrf -> csrf.disable())\n        .authorizeHttpRequests(auth -> auth\n            .requestMatchers(\"/auth/login\").permitAll()\n            .requestMatchers(\"/admin/**\")\n                .hasRole(\"ADMIN\")\n            .anyRequest().authenticated()\n        )\n        .sessionManagement(session ->\n            session.sessionCreationPolicy(\n                SessionCreationPolicy.STATELESS\n            )\n        )\n        .addFilterBefore(\n            jwtAuthenticationFilter,\n            UsernamePasswordAuthenticationFilter.class\n        )\n        .build();\n}"],["h","Security best practices"],["p","Use:"],["ul",["HTTPS","short-lived access tokens","refresh-token rotation","secure storage strategy","password hashing with BCrypt/Argon2","issuer/audience validation","expiration validation","key rotation","rate limiting","logout/revocation strategy where required"]]],"realWorld":[["h","Real-world example"],["p","An insurance document application might have:"],["code","text","admin       → upload/delete/approve\nlegal_user  → review legal documents\nuser        → view permitted documents\nguest       → limited access"],["p","The JWT can carry a role or subject, but the backend must enforce access to the requested document."],["h","Real-world banking example"],["code","text","Customer Login\n ↓\nAuthentication Service\n ↓\nJWT Access Token\n ↓\nAccount API\n ↓\nTransaction API"],["p","For high-risk operations, require additional controls such as MFA or step-up authentication."]]},{"id":2794,"category":"JWT","difficulty":"Mid","question":"JWT vs Session-Based Authentication","answer":"For browser applications, avoid putting authentication tokens in localStorage when a secure HTTP-only cookie architecture is practical.","highlights":["Easy revocation","Server controls session state","Secure HTTP-only cookie model"],"body":[["h","Session"],["code","text","Browser\n  |\n  | session cookie\n  v\nServer\n  |\n  v\nSession store"],["p","Advantages:"],["ul",["Easy revocation","Server controls session state","Secure HTTP-only cookie model"]],["h","JWT"],["code","text","Client\n  |\n  | JWT\n  v\nAPI"],["p","Advantages:"],["ul",["Useful across distributed services","Can carry claims","Stateless verification can simplify some architectures"]],["p","Trade-offs:"],["ul",["Revocation is harder","Token lifetime/rotation matters","Storing JWTs insecurely creates significant risk"]]],"realWorld":[["p","**Why it matters.** Sessions store state on the server and are easy to revoke; JWTs are stateless and scale easily but are harder to invalidate."],["p","**Example.** An internal admin tool uses server-side sessions in Redis so a compromised account can be logged out instantly. A public mobile API uses short-lived JWT access tokens plus refresh tokens, so any API instance can verify requests without a shared session store."]]},{"id":2795,"category":"JWT","difficulty":"Senior","question":"How do you secure a full-stack application (JWT, OAuth2, Spring Security)?","answer":"The backend validates the token before allowing protected operations.","highlights":["Keep token lifetime appropriately short.","Validate signature.","Validate expiration."],"body":[["p","There are two important concepts:"],["h","Authentication"],["p","Verifies identity."],["code","text","Who is the user?"],["h","Authorization"],["p","Determines permissions."],["code","text","What can the user access?"],["h","JWT Authentication"],["p","Typical flow:"],["code","text","Frontend\n   |\n   | username/password\n   v\nBackend\n   |\n   | authenticate\n   v\nJWT issued\n   |\n   v\nFrontend\n   |\n   | Authorization: Bearer <token>\n   v\nBackend"],["p","Example HTTP request:"],["code","http","GET /api/orders\nAuthorization: Bearer eyJhbGciOi..."],["p","A JWT commonly contains claims such as:"],["code","json","{\n  \"sub\": \"user123\",\n  \"roles\": [\"CUSTOMER\"],\n  \"exp\": 1760000000\n}"],["h","Important JWT points"],["ul",["Keep token lifetime appropriately short.","Validate signature.","Validate expiration.","Validate issuer/audience when applicable.","Do not put passwords or sensitive secrets inside JWT claims.","Use HTTPS.","Consider refresh-token strategies carefully.","Revoke/rotate credentials appropriately when required."]],["h","OAuth 2.0"],["p","OAuth 2.0 is primarily an authorization framework."],["p","A common modern flow for user login is **Authorization Code + PKCE**."],["p","Example:"],["code","text","User\n |\n v\nFrontend\n |\n | redirect\n v\nAuthorization Server\n |\n | authorization code\n v\nFrontend\n |\n | code exchange\n v\nAuthorization Server\n |\n | tokens\n v\nFrontend\n |\n | access token\n v\nSpring Boot API"],["p","For enterprise systems, an Identity Provider can manage authentication, MFA, users, roles, and token issuance."],["h","Spring Security resource server example"],["p","A Spring Boot API can validate JWT access tokens:"],["code","java","@Configuration\n@EnableWebSecurity\npublic class SecurityConfig {\n\n    @Bean\n    SecurityFilterChain securityFilterChain(HttpSecurity http)\n            throws Exception {\n\n        http\n            .authorizeHttpRequests(auth -> auth\n                .requestMatchers(\"/public/**\").permitAll()\n                .requestMatchers(\"/admin/**\").hasRole(\"ADMIN\")\n                .anyRequest().authenticated()\n            )\n            .oauth2ResourceServer(\n                oauth2 -> oauth2.jwt()\n            );\n\n        return http.build();\n    }\n}"],["p","The exact configuration depends on your Spring Security version and identity provider."]],"realWorld":[["p","**Why it matters.** Securing a full-stack app means layering controls: strong auth, authorisation checks on the server, safe token storage, HTTPS, validation and monitoring."],["p","**Example.** A Spring Boot API acts as an OAuth2 resource server validating JWTs from the identity provider. Method security (`@PreAuthorize`) enforces roles, the React app keeps tokens in HttpOnly cookies, CORS allows only the known origin, and all traffic is HTTPS with rate limiting on login."]]},{"id":2796,"category":"JWT","difficulty":"Mid","question":"RBAC: how do you implement role-based access control?","answer":"RBAC means permissions are assigned based on roles.","highlights":["Authentication answers:","Who are you?","Authorization answers:"],"body":[["p","Example:"],["code","text","ADMIN\n ├── Create User\n ├── Delete User\n └── View Reports\n\nMANAGER\n ├── View Reports\n └── Approve Requests\n\nCUSTOMER\n └── View Own Account"],["h","Spring Security"],["code","java","@PreAuthorize(\"hasRole('ADMIN')\")\n@PostMapping(\"/users\")\npublic User createUser(@RequestBody UserRequest request) {\n    return userService.create(request);\n}"],["p","Enable method security:"],["code","java","@Configuration\n@EnableMethodSecurity\npublic class SecurityConfig {\n}"],["h","Important"],["p","Authentication answers:"],["quote","Who are you?"],["p","Authorization answers:"],["quote","What are you allowed to do?"]],"realWorld":[["h","Real-world insurance example"],["code","text","CUSTOMER\n → View own policies\n\nAGENT\n → Create/update customer policy\n\nCLAIMS_ADJUSTER\n → Review claims\n\nADMIN\n → Manage users and configuration"],["p","**In practice.** In a claims system, `ADJUSTER` can view and update claims, `MANAGER` can approve payouts and `AUDITOR` can only read. The API checks the role from the token on each endpoint (`@PreAuthorize(\"hasRole('MANAGER')\")`), and the UI hides buttons the user cannot use. The server check is the real protection."]]},{"id":2797,"category":"Database","difficulty":"Mid","question":"How does database indexing work internally (B-tree / B+tree)?","answer":"A database index is a separate data structure that helps the database find rows without scanning the entire table. Most relational databases commonly use B-tree-family indexes. A B+Tree keeps searchable key values in sorted order and uses a tree structure so the database can quickly navigate from the root to the relevant leaf pages.","highlights":["Indexes are not free.","Consume storage","Increase write/update overhead"],"body":[["h","Simple interview answer"],["p","Without an index:"],["code","text","Table\n |\n +-- Row 1\n +-- Row 2\n +-- Row 3\n +-- ...\n +-- Row 10,000,000\n\nSELECT * FROM users WHERE email = 'a@x.com';\n\nDatabase may scan many rows."],["p","With an index:"],["code","text","                 Root\n                  |\n          +-------+-------+\n          |               |\n       Internal         Internal\n          |               |\n       Leaf pages --> Leaf pages\n          |\n       matching key\n          |\n       row location"],["p","The database can navigate through the tree instead of checking every row."],["h","Why B-Tree/B+Tree is useful"],["p","The tree remains balanced, so the number of levels stays relatively small."],["p","A simplified B+Tree:"],["code","text","                         [50]\n                       /      \\\n                [10,20,30]   [70,80,90]\n                  / |  \\        / |  \\\n                 ... ... ...    ... ... ..."],["p","Leaf nodes contain the indexed keys and references/row identifiers, depending on the database and index type."],["p","B+Trees also keep leaf pages linked in key order, which makes range queries efficient."],["p","Example:"],["code","sql","SELECT *\nFROM orders\nWHERE order_date BETWEEN '2026-01-01' AND '2026-01-31';"],["p","An index on `order_date` can help the database locate the first matching key and then scan the relevant range."],["h","What happens during an indexed lookup?"],["p","Suppose:"],["code","sql","SELECT *\nFROM users\nWHERE email = 'arjun@example.com';"],["p","And:"],["code","sql","CREATE INDEX idx_users_email\nON users(email);"],["p","Conceptually:"],["code","text","Query\n  |\n  v\nFind index on email\n  |\n  v\nRoot page\n  |\n  v\nInternal page\n  |\n  v\nLeaf page\n  |\n  v\nMatching key\n  |\n  v\nRow/table data"],["p","The exact execution depends on the database engine, table layout, statistics, selectivity, and query plan."],["h","Why is it faster?"],["p","A full table scan is approximately:"],["code","text","O(N)"],["p","A balanced tree lookup is approximately:"],["code","text","O(log N)"],["p","This is a simplified algorithmic view. Real database performance also depends heavily on disk/page I/O, caching, selectivity, data distribution, and the query optimizer."],["h","Interview-ready answer"],["quote","A database index is a separate data structure that helps the database locate rows efficiently. B-tree or B+Tree indexes keep keys ordered in a balanced tree. For an equality lookup, the database traverses from the root through internal nodes to a leaf instead of scanning every row. B+Trees are also very useful for range queries because the leaf pages are ordered. The trade-off is that indexes consume storage and have to be maintained when data changes."],["h","Also worth knowing"],["p","An index is a data structure that helps the database find rows more efficiently."],["p","Without a suitable index, the database may need to inspect many rows."],["h","Example"],["code","sql","SELECT *\nFROM documents\nWHERE document_id = 'DOC123';"],["p","If `document_id` is frequently searched, an index can help:"],["code","sql","CREATE INDEX idx_documents_document_id\nON documents(document_id);"],["p","Conceptually:"],["code","text","Without index:\nSearch → scan many rows\n\nWith index:\nSearch → index lookup → matching rows"],["h","Important trade-off"],["p","Indexes are not free."],["p","They:"],["ul",["Consume storage","Increase write/update overhead","Need maintenance","Should be chosen based on actual query patterns"]],["h","Interview answer"],["quote","An index allows the database to locate matching records more efficiently instead of scanning the entire table. I choose indexes based on real query patterns and verify their effectiveness using query execution plans. I also consider the write and storage overhead of indexes."],["h","Also worth knowing"],["p","Indexing serves the same high-level purpose in both:"],["code","text","Reduce the amount of data that must be examined."],["p","But the implementation and index types differ by database."],["h","MySQL example"],["p","Suppose:"],["code","sql","SELECT *\nFROM users\nWHERE email = 'a@example.com';"],["p","Create:"],["code","sql","CREATE INDEX idx_users_email\nON users(email);"],["p","The database can use the index to locate matching rows efficiently."],["h","Composite index"],["p","Query:"],["code","sql","SELECT *\nFROM orders\nWHERE customer_id = ?\nORDER BY created_at DESC;"],["p","Possible index:"],["code","sql","CREATE INDEX idx_orders_customer_date\nON orders(customer_id, created_at);"],["p","Column order matters."],["h","MongoDB example"],["p","Documents:"],["code","json","{\n    \"_id\": 1,\n    \"email\": \"a@example.com\",\n    \"status\": \"ACTIVE\"\n}"],["p","Index:"],["code","javascript","db.users.createIndex({\n    email: 1\n});"],["p","Query:"],["code","javascript","db.users.find({\n    email: \"a@example.com\"\n});"],["h","MongoDB compound index"],["code","javascript","db.orders.createIndex({\n    customerId: 1,\n    createdAt: -1\n});"],["p","Useful for patterns such as:"],["code","javascript","db.orders.find({\n    customerId: \"C123\"\n}).sort({\n    createdAt: -1\n});"],["h","Index trade-off"],["p","MongoDB:"],["code","text","More indexes\n    |\n    +--> Faster reads\n    |\n    +--> More storage\n    |\n    +--> More write overhead"],["p","MySQL has the same broad trade-off."],["h","Important interview point"],["p","Do not say:"],["quote","Indexes always make queries faster."],["p","Correct answer:"],["quote","Indexes can improve appropriate queries, but they add storage and write-maintenance overhead, and the optimizer may decide that an index is not beneficial."],["p","Use query plans:"],["p","MySQL:"],["code","sql","EXPLAIN\nSELECT *\nFROM users\nWHERE email = 'a@example.com';"],["p","MongoDB:"],["code","javascript","db.users.find({\n    email: \"a@example.com\"\n}).explain(\"executionStats\");"]],"realWorld":[["h","Real-world banking example"],["p","Suppose a bank has 100 million transactions."],["code","sql","SELECT *\nFROM transactions\nWHERE transaction_id = 'TXN100001';"],["p","A unique index on `transaction_id` allows the database to find the transaction efficiently."],["h","Insurance example"],["p","Claims may be searched by:"],["code","sql","SELECT *\nFROM claims\nWHERE policy_number = 'POL12345';"],["p","An index on `policy_number` can make this lookup much faster when the column is selective."],["h","E-commerce example"],["code","sql","SELECT *\nFROM products\nWHERE sku = 'IPHONE-001';"],["p","An index on `sku` is very useful because SKU is generally highly selective."],["h","Real-world example"],["p","If your document platform contains millions of documents and users frequently search by:"],["code","text","document_id\nfilename\ncustomer_id"],["p","appropriate indexes can reduce query work significantly."]]},{"id":2798,"category":"Database","difficulty":"Senior","question":"When do indexes help and when do they hurt? Why do INSERT/UPDATE get slower?","answer":"Indexes improve performance when they allow the database to avoid scanning a large portion of the table, especially for selective equality, range, join, or ordering operations. They can slow down writes because every relevant index has to be maintained. They also consume storage and may not help low-selectivity or poorly targeted queries. I would validate the decision using query plans and workload measurements rather than blindly indexing every column.","highlights":["Memory/cache","Write resources","Maintenance resources"],"body":[["h","1. Queries filter on the indexed column"],["code","sql","SELECT *\nFROM customers\nWHERE email = ?;"],["p","Index:"],["code","sql","CREATE INDEX idx_customer_email\nON customers(email);"],["h","2. The column is selective"],["p","Example:"],["code","text","user_id\ntransaction_id\nemail\npolicy_number\nSKU"],["p","These often identify a small subset of rows."],["h","3. The index supports sorting/range access"],["p","Example:"],["code","sql","SELECT *\nFROM transactions\nWHERE account_id = ?\nORDER BY created_at DESC;"],["p","A suitable composite index may help."],["h","1. Too many indexes"],["p","Every write may require index maintenance."],["code","text","INSERT\n |\n +--> Table\n +--> Index 1\n +--> Index 2\n +--> Index 3\n +--> Index 4"],["h","2. Low selectivity"],["p","Example:"],["code","text","gender\nstatus\nboolean flags"],["p","A simple index may not be useful for some queries because a large percentage of rows match."],["p","This is database- and workload-dependent; the optimizer may still find an index useful in some cases."],["h","3. Index is unused"],["p","An unused index consumes:"],["ul",["Disk","Memory/cache","Write resources","Maintenance resources"]],["h","4. Small tables"],["p","For a tiny table, a full scan can be cheaper than using an index."],["h","5. Poor query pattern"],["p","An index may not help if the query applies a transformation that prevents efficient index use, depending on the database."],["p","Example:"],["code","sql","WHERE LOWER(email) = 'test@example.com'"],["p","A normal index on `email` may not be enough in some database systems. A functional/expression index or normalized column may be appropriate."],["h","How do you decide?"],["p","Do not guess."],["p","Use the query execution plan:"],["code","sql","EXPLAIN\nSELECT *\nFROM transactions\nWHERE account_id = 100;"],["p","Many databases also provide:"],["code","sql","EXPLAIN ANALYZE"],["p","which can provide actual execution information."],["h","Also worth knowing"],["p","This follows directly from index maintenance."],["h","SELECT"],["p","Without index:"],["code","text","SELECT\n  |\n  v\nScan many rows\n  |\n  v\nFind matching row"],["p","With index:"],["code","text","SELECT\n  |\n  v\nIndex\n  |\n  v\nFind matching key\n  |\n  v\nFetch row"],["p","Therefore, an appropriate index can significantly reduce the amount of data the database needs to examine."],["h","INSERT"],["p","Suppose:"],["code","sql","INSERT INTO users(email, name)\nVALUES ('a@example.com', 'Arjun');"],["p","The database must insert:"],["code","text","Table row"],["p","And potentially update:"],["code","text","email index\nname index\nother indexes"],["p","So:"],["code","text","INSERT\n |\n +--> Table\n +--> Index 1\n +--> Index 2\n +--> Index 3"],["h","UPDATE"],["p","If an indexed column changes:"],["code","sql","UPDATE users\nSET email = 'new@example.com'\nWHERE id = 100;"],["p","The database needs to update the relevant index entry."],["h","DELETE"],["p","Deleting a row also requires removing its entries from applicable indexes."],["code","text","DELETE\n |\n +--> Table row removed\n +--> Index 1 updated\n +--> Index 2 updated"],["h","Interview answer"],["quote","A SELECT can use an index to avoid scanning many rows. INSERT, UPDATE, and DELETE have additional work because the database must maintain the index entries. The more indexes a table has, the more write amplification it can experience. Therefore indexes represent a read-performance versus write-cost trade-off."],["h","Short answer"],["p","Yes, a frequently changing column **can** be indexed, but we should only do it when the performance benefit of reads justifies the maintenance cost."],["p","Example:"],["code","sql","CREATE INDEX idx_users_status\nON users(status);"],["p","Suppose:"],["code","text","status = ACTIVE / INACTIVE"],["p","If millions of users frequently change status, the index must also be updated."],["h","What happens during UPDATE?"],["p","Suppose:"],["code","sql","UPDATE users\nSET status = 'INACTIVE'\nWHERE id = 100;"],["p","Conceptually:"],["code","text","Update table row\n      |\n      +----> Update index entry"],["p","If several indexes include that column:"],["code","text","Update row\n   |\n   +--> Index 1\n   +--> Index 2\n   +--> Index 3\n   +--> Index 4"],["p","The write cost increases."],["h","Important trade-off"],["code","text","More indexes\n    |\n    +--> Faster reads\n    |\n    +--> More storage\n    |\n    +--> Slower INSERT\n    +--> Slower UPDATE\n    +--> Slower DELETE"],["h","Low-cardinality example"],["p","Consider:"],["code","text","status:\nACTIVE\nINACTIVE\nACTIVE\nACTIVE\nINACTIVE\n..."],["p","If almost every row has one of only two values, a simple index may not provide much benefit depending on the database and query."],["p","Compare with:"],["code","text","transaction_id:\nTXN000001\nTXN000002\nTXN000003\n..."],["p","A unique transaction ID is highly selective and is usually a much better index candidate."],["h","Interview answer"],["quote","Frequently changing columns can still be indexed. The trade-off is that every INSERT, UPDATE, or DELETE may require index maintenance. I would evaluate query frequency, selectivity, write volume, index size, and the actual execution plan before creating the index."]],"realWorld":[["h","Real-world example"],["p","Banking transactions are write-heavy."],["p","If a bank receives:"],["code","text","100,000 transactions/second"],["p","and every transaction updates many indexes, index maintenance can become expensive."],["p","But removing useful indexes can make important queries much slower."],["p","The goal is not:"],["quote","Maximum indexes"],["p","The goal is:"],["quote","The right indexes for the workload."]]},{"id":2799,"category":"Database","difficulty":"Mid","question":"What is query optimisation and how do you design efficient data retrieval?","answer":"I optimize queries by first understanding the actual query pattern and execution plan. Then I look at indexes, joins, selected columns, pagination and N+1 access patterns. I measure the improvement instead of assuming an optimization works.","highlights":["Appropriate indexes","Selecting only required columns","Efficient joins"],"body":[["p","Query optimization means making database access efficient in terms of:"],["code","text","Execution time\nCPU\nMemory\nI/O\nNetwork transfer"],["h","Example"],["p","Bad:"],["code","sql","SELECT *\nFROM documents;"],["p","if the UI only needs:"],["code","text","id\nname\nstatus"],["p","Better:"],["code","sql","SELECT id, name, status\nFROM documents;"],["h","Other techniques"],["ul",["Appropriate indexes","Selecting only required columns","Efficient joins","Pagination","Avoiding N+1 queries","Query execution plans","Proper filtering","Appropriate database schema"]],["h","Also worth knowing"],["p","Start from what the UI actually needs."],["p","Instead of:"],["code","text","Fetch entire document object\nFetch all related users\nFetch all audit history\nFetch every metadata field"],["p","return only the required information."],["h","Example"],["code","json","{\n  \"id\": \"DOC123\",\n  \"name\": \"Policy.pdf\",\n  \"status\": \"ACTIVE\",\n  \"updatedAt\": \"2026-10-06T10:00:00Z\"\n}"],["h","Combine with"],["code","text","Indexes\n+\nPagination\n+\nFiltering\n+\nProjection\n+\nCaching where appropriate"]],"realWorld":[["h","Real-world document example"],["p","For a search page showing 50 documents, don't retrieve the actual PDF content for all 50 documents."],["p","Retrieve:"],["code","text","metadata → list screen"],["p","and fetch:"],["code","text","document content → only when user opens it"],["p","This can dramatically reduce unnecessary data transfer."],["p","**In practice.** A policy search took 4 s because it filtered on an unindexed `customer_name` column and used `SELECT *`. Adding an index, selecting only the needed columns and reading the `EXPLAIN` plan to confirm an index scan brought it under 100 ms."]]},{"id":2800,"category":"Database","difficulty":"Mid","question":"Normalization vs Denormalization","answer":"Normalization reduces redundancy and update anomalies by separating data into related tables. Denormalization intentionally duplicates or precomputes data to optimize read-heavy workloads. I normally start with a normalized transactional model and denormalize when measurements and workload requirements justify it.","highlights":[],"body":[["h","Normalization"],["p","Normalization organizes relational data to reduce redundancy and update anomalies."],["p","Example:"],["p","Instead of:"],["code","text","Orders\n----------------------------------\norder_id\ncustomer_name\ncustomer_email\nproduct_name\nproduct_price"],["p","Separate tables:"],["code","text","Customers\n---------\ncustomer_id\nname\nemail\n\nOrders\n------\norder_id\ncustomer_id\n\nProducts\n--------\nproduct_id\nname\nprice\n\nOrderItems\n----------\norder_id\nproduct_id\nquantity"],["h","Benefits of normalization"],["code","text","Less duplicated data\nBetter consistency\nEasier updates\nClear relationships"],["h","Denormalization"],["p","Denormalization intentionally duplicates or precomputes data to improve read performance or simplify read paths."],["p","Example:"],["code","text","OrderSummary\n-----------------------\norder_id\ncustomer_name\ntotal_amount\nitem_count"],["p","Some information is duplicated."],["h","When to denormalize"],["p","Consider it when:"],["code","text","Read performance is critical\nJoins are expensive at scale\nData is read much more often than written\nA read model is useful\nAnalytics/search workloads need a different structure"]],"realWorld":[["h","Banking example"],["p","Transactional system:"],["code","text","Customers\nAccounts\nTransactions"],["p","Keep strong normalization where consistency is important."],["p","For reporting:"],["code","text","DailyAccountSummary\n-------------------\naccount_id\ndate\ntotal_debits\ntotal_credits\nclosing_balance"],["p","A precomputed summary can make reporting faster."],["h","E-commerce example"],["p","Normalized transactional model:"],["code","text","Orders\nOrderItems\nProducts\nCustomers"],["p","A search/read model might contain:"],["code","text","ProductSearchDocument\n---------------------\nproduct_id\nname\ncategory\nprice\nrating\navailability"],["p","This can be optimized for search/read access."]]},{"id":2801,"category":"Database","difficulty":"Mid","question":"What are database transactions and ACID? What should happen inside a transaction?","answer":"A transaction groups operations into one logical unit.","highlights":[],"body":[["p","The classic ACID properties are:"],["code","text","A - Atomicity\nC - Consistency\nI - Isolation\nD - Durability"],["h","Atomicity"],["p","All operations succeed or none do."],["code","text","Debit succeeds\nCredit fails\n     |\n     v\nRollback"],["h","Consistency"],["p","The database moves from one valid state to another according to constraints and transaction rules."],["h","Isolation"],["p","Concurrent transactions should not interfere in invalid ways."],["h","Durability"],["p","After a successful commit, the database is designed to preserve the committed result despite normal failures."],["h","Isolation levels"],["p","Common SQL isolation levels include:"],["code","text","READ UNCOMMITTED\nREAD COMMITTED\nREPEATABLE READ\nSERIALIZABLE"],["p","Higher isolation can reduce certain concurrency anomalies but may increase contention."],["h","Common concurrency problems"],["code","text","Dirty read\nNon-repeatable read\nPhantom read\nLost update"],["p","Exact behavior depends on the database engine and isolation level."],["h","Spring Boot transaction example"],["code","java","@Service\npublic class TransferService {\n\n    @Transactional\n    public void transfer(\n            Long fromId,\n            Long toId,\n            BigDecimal amount) {\n\n        accountRepository.debit(fromId, amount);\n\n        accountRepository.credit(toId, amount);\n    }\n}"],["p","If an unchecked exception causes the transaction to roll back under the configured transaction rules, the database can restore the transaction's prior state."],["h","Interview answer"],["quote","A database transaction groups multiple operations into one logical unit and provides ACID guarantees. For example, a bank transfer should debit one account and credit another atomically. I also consider the required isolation level because stronger isolation can increase contention and reduce concurrency."],["h","Also worth knowing"],["p","Suppose invoice creation performs:"],["code","text","1. Create invoice\n2. Create invoice items\n3. Update order status"],["p","What if:"],["code","text","1. Create invoice        → SUCCESS\n2. Create invoice items   → SUCCESS\n3. Update order status    → FAILURE"],["p","Without a transaction, the database could contain an incomplete state."],["p","With a transaction:"],["code","text","BEGIN\n  Create invoice\n  Create invoice items\n  Update order\nCOMMIT"],["p","If one operation fails:"],["code","text","ROLLBACK"],["p","The database returns to the previous consistent state."],["h","Also worth knowing"],["p","Database consistency operations should generally remain inside the transaction."],["p","Example:"],["code","text","BEGIN TRANSACTION\n\nValidate current order state\nCreate invoice\nCreate invoice items\nUpdate order status\nSave required invoice metadata\n\nCOMMIT"],["h","Avoid long external operations inside the transaction"],["p","For example, generating a large PDF by calling an external service can make a database transaction remain open unnecessarily."],["p","Better:"],["code","text","DB transaction\n    ↓\nCommit invoice data\n    ↓\nPublish event / queue job\n    ↓\nGenerate PDF asynchronously\n    ↓\nStore PDF\n    ↓\nNotify user"]],"realWorld":[["h","Banking example"],["p","Transfer:"],["code","text","Account A: ₹10,000\nAccount B: ₹5,000"],["p","Transfer ₹2,000:"],["code","text","Debit A: -₹2,000\nCredit B: +₹2,000"],["p","Both operations should succeed together."],["code","text","BEGIN\n\nUPDATE account\nSET balance = balance - 2000\nWHERE id = 'A';\n\nUPDATE account\nSET balance = balance + 2000\nWHERE id = 'B';\n\nCOMMIT"],["p","If something fails:"],["code","text","ROLLBACK"],["p","**In practice.** Transferring money debits one account and credits another. If the credit fails after the debit, the transaction rolls back so no money disappears. Isolation levels decide what concurrent readers see, and keeping transactions short prevents lock contention at peak times."]]},{"id":2802,"category":"Database","difficulty":"Senior","question":"Optimistic vs Pessimistic Locking","answer":"This prevents another transaction from modifying the same critical row at the same time.","highlights":["low contention","many reads","web applications"],"body":[["h","Optimistic locking"],["p","Assumes conflicts are uncommon."],["p","A version field is commonly used."],["h","Entity"],["code","java","@Entity\nclass Policy {\n\n    @Id\n    private Long id;\n\n    private BigDecimal premium;\n\n    @Version\n    private Long version;\n}"],["p","If two users read version 5:"],["code","text","User A → version 5\nUser B → version 5\n\nA updates → version 6\n\nB tries update version 5\n→ conflict"],["h","Good for"],["ul",["low contention","many reads","web applications","policy updates"]],["h","Pessimistic locking"],["p","Locks the database row while working."],["code","java","@Lock(LockModeType.PESSIMISTIC_WRITE)\n@Query(\"select a from Account a where a.id = :id\")\nOptional<Account> findAccountForUpdate(Long id);"],["h","Comparison"],["table",["","Optimistic","Pessimistic"],[["Assumption","Conflicts rare","Conflicts possible"],["Lock","No database lock during normal read","Locks resource"],["Performance","Usually better under low contention","Can reduce concurrency"],["Conflict","Detected during update","Prevented/blocked"]]]],"realWorld":[["h","Banking example"],["p","For a money transfer:"],["code","text","Account balance = ₹50,000\n\nTransaction A\n ↓\nLock account\n ↓\nDeduct ₹10,000\n ↓\nCommit\n ↓\nRelease lock"],["p","**In practice.** Two agents edit the same claim. With optimistic locking, each read includes a `version` number; the second save fails with 'record was modified, reload' and nobody overwrites the other's work silently. Pessimistic locks (`SELECT ... FOR UPDATE`) suit short, high-conflict operations like reserving the last seat."]]},{"id":2803,"category":"Database","difficulty":"Mid","question":"Aggregation pipelines in MongoDB","answer":"MongoDB aggregation processes documents through a sequence of stages.","highlights":[],"body":[["p","Example:"],["code","javascript","db.orders.aggregate([\n    {\n        $match: {\n            status: \"COMPLETED\"\n        }\n    },\n    {\n        $group: {\n            _id: \"$customerId\",\n            totalSpent: {\n                $sum: \"$amount\"\n            }\n        }\n    },\n    {\n        $sort: {\n            totalSpent: -1\n        }\n    }\n]);"],["p","Flow:"],["code","text","Orders\n  |\n  v\n$match\n  |\n  v\n$group\n  |\n  v\n$sort\n  |\n  v\nResult"],["h","Common stages"],["code","text","$match\n$project\n$group\n$sort\n$limit\n$lookup\n$unwind\n$count"],["h","Why put $match early?"],["p","If possible:"],["code","text","Filter early\n   |\n   v\nFewer documents\n   |\n   v\nLess work for later stages"],["p","Example:"],["code","javascript","{\n    $match: {\n        status: \"COMPLETED\"\n    }\n}"],["p","before expensive aggregation stages."],["p","An appropriate index can also help the initial filtering."],["h","Interview answer"],["quote","MongoDB aggregation pipelines process documents through stages such as `$match`, `$group`, `$project`, `$sort`, and `$lookup`. I usually filter early to reduce the amount of data passed through later stages, and I use appropriate indexes for the initial query patterns."]],"realWorld":[["h","E-commerce example"],["p","Find top customers by completed order value:"],["code","javascript","db.orders.aggregate([\n    {\n        $match: {\n            status: \"COMPLETED\"\n        }\n    },\n    {\n        $group: {\n            _id: \"$customerId\",\n            total: {\n                $sum: \"$amount\"\n            }\n        }\n    },\n    {\n        $sort: {\n            total: -1\n        }\n    },\n    {\n        $limit: 10\n    }\n]);"],["h","Insurance example"],["p","Find total claim amount per policy type:"],["code","javascript","db.claims.aggregate([\n    {\n        $match: {\n            status: \"APPROVED\"\n        }\n    },\n    {\n        $group: {\n            _id: \"$policyType\",\n            totalClaims: {\n                $sum: \"$amount\"\n            }\n        }\n    }\n]);"],["p","**In practice.** An analytics endpoint uses an aggregation pipeline: `$match` filters this month's orders first (using an index), `$group` totals revenue per category, and `$sort`/`$limit` return the top five. Putting `$match` early keeps the pipeline from scanning the whole collection."]]},{"id":2804,"category":"Database","difficulty":"Mid","question":"Database Design Interview Checklist","answer":"Good schema design prevents data anomalies and slow queries later; reviewers look for keys, relationships, constraints and indexes.","highlights":[],"body":[["p","When designing a database, discuss:"],["h","Tables"],["code","text","users\norders\npayments\nproducts"],["h","Primary key"],["code","sql","id BIGINT PRIMARY KEY"],["h","Foreign key"],["code","sql","user_id BIGINT REFERENCES users(id)"],["h","Index"],["code","sql","CREATE INDEX idx_orders_user_id\nON orders(user_id);"],["h","Unique constraint"],["code","sql","CREATE UNIQUE INDEX idx_users_email\nON users(email);"],["h","Transactions"],["p","For money movement:"],["code","text","BEGIN\n ↓\nDebit\n ↓\nCredit\n ↓\nRecord transaction\n ↓\nCOMMIT"]],"realWorld":[["p","**Why it matters.** Good schema design prevents data anomalies and slow queries later; reviewers look for keys, relationships, constraints and indexes."],["p","**Example.** For an orders system: `customers`, `orders`, `order_items`, `products` tables with primary keys, foreign keys, `NOT NULL`/`UNIQUE` constraints (email), and indexes on `orders(customer_id, created_at)` for the 'my orders' query. Money is stored as `DECIMAL`, never float."]]},{"id":2805,"category":"System Design","difficulty":"Senior","question":"Design a URL shortener (including invalid-URL protection / negative caching)","answer":"Requests for non-existent short codes still hit the database. Attackers or broken links can generate huge miss traffic. Negative caching and Bloom filters stop it cheaply.","highlights":["Rate limiting","WAF/bot protection","CDN caching where appropriate"],"body":[["p","Suppose the URL is:"],["code","text","https://short.example/abc123"],["p","But:"],["code","text","abc123"],["p","does not exist."],["p","If millions of bots repeatedly request:"],["code","text","/abc123"],["h","Problem"],["code","text","Request\n   |\n   v\nAPI\n   |\n   v\nDatabase\n   |\n   v\nNOT FOUND"],["p","Repeated requests:"],["code","text","Bot\n |\n +--> API --> DB --> NOT FOUND\n |\n +--> API --> DB --> NOT FOUND\n |\n +--> API --> DB --> NOT FOUND\n |\n +--> API --> DB --> NOT FOUND"],["h","Solution: Negative caching"],["p","Cache the fact that a key does not exist."],["code","text","Request\n   |\n   v\nCache\n   |\n   +--> \"NOT_FOUND\"\n   |\n   v\nReturn 404"],["p","Example:"],["code","text","Cache key:\nurl:abc123\n\nValue:\nNOT_FOUND"],["p","Use a TTL:"],["code","text","NOT_FOUND -> expires after a short period"],["p","This is important because a previously invalid key could theoretically become valid later."],["h","Better architecture"],["code","text","                  Request\n                     |\n                     v\n                Rate Limiter\n                     |\n                     v\n                   Cache\n                 /       \\\n             HIT          MISS\n              |             |\n              v             v\n          Redirect      Database\n                           |\n                    +------+------+\n                    |             |\n                  Found        Not Found\n                    |             |\n                    v             v\n                  Cache       Negative Cache"],["h","Redis example"],["p","Conceptually:"],["code","text","GET url:abc123"],["p","If:"],["code","text","NOT_FOUND"],["p","return `404`."],["p","If not cached:"],["code","text","SELECT original_url\nFROM urls\nWHERE short_code = 'abc123';"],["p","If missing:"],["code","text","SETEX url:abc123 60 NOT_FOUND"],["h","Why TTL matters"],["p","Never necessarily cache a permanent negative result."],["p","Use:"],["code","text","NOT_FOUND -> 30 seconds"],["p","or another value based on application behavior."],["h","Bloom filter"],["p","For very large systems, a Bloom filter can be used as an additional probabilistic membership check."],["code","text","Request\n   |\n   v\nBloom Filter\n   |\n   +--> Definitely not present\n   |          |\n   |          v\n   |        404\n   |\n   +--> Maybe present\n              |\n              v\n            Cache\n              |\n              v\n             DB"],["p","Important:"],["quote","A Bloom filter can tell you an item is definitely not present or possibly present. It can have false positives, but not false negatives when correctly used."],["h","Other protections"],["p","Use:"],["ul",["Rate limiting","WAF/bot protection","CDN caching where appropriate","Negative caching","Redis","Bloom filters for suitable high-scale designs"]],["h","Interview answer"],["quote","I would use negative caching. When a short code is not found, I would temporarily cache that negative result with a TTL. Future requests for the same invalid code can be rejected without hitting the database. For extremely high-scale systems, I could also use a Bloom filter to quickly identify keys that definitely don't exist. I would combine this with rate limiting and bot protection."],["h","Also worth knowing"],["p","Requirements:"],["code","text","Create short URL\nRedirect short URL\nHigh read traffic\nLow latency\nUnique short codes"],["h","Basic architecture"],["code","text","                 Client\n                   |\n                   v\n             Load Balancer\n                   |\n                   v\n             URL Service\n              /       \\\n             v         v\n          Redis      Database"],["h","Create URL"],["p","Request:"],["code","http","POST /urls"],["p","Body:"],["code","json","{\n    \"url\": \"https://example.com/products/123\"\n}"],["p","Response:"],["code","json","{\n    \"shortUrl\": \"https://short.example/aB91x\"\n}"],["h","Short code generation"],["p","Possible approaches:"],["code","text","Random Base62\nAuto-increment ID + Base62\nDistributed ID generator + Base62"],["p","Base62 characters:"],["code","text","A-Z\na-z\n0-9"],["p","Example:"],["code","text","123456789\n     |\n     v\nBase62\n     |\n     v\n8M0kP"],["h","Redirect flow"],["code","text","GET /aB91x\n     |\n     v\nRedis\n     |\n   HIT?\n  /   \\\nYes    No\n |      |\n v      v\nURL    DB\n |      |\n v      v\n302/301 Cache"],["p","For permanent/long-lived redirects, the exact HTTP redirect choice depends on application requirements."],["h","Invalid URL protection"],["p","Use negative caching:"],["code","text","aB91x -> NOT_FOUND"],["p","with a TTL."],["p","At extreme scale:"],["code","text","Bloom Filter"],["p","can reject definitely-invalid keys before deeper lookups."],["h","Scaling"],["code","text","                 Load Balancer\n                 /     |     \\\n                v      v      v\n              API1   API2   API3\n                \\      |      /\n                 \\     |     /\n                      Redis\n                        |\n                     Database"],["p","Read-heavy traffic makes caching especially valuable."],["h","Database schema"],["p","Example relational model:"],["code","text","urls\n--------------------------------\nid\nshort_code UNIQUE\noriginal_url\ncreated_at\nexpires_at"],["p","Important:"],["code","text","UNIQUE(short_code)"],["p","prevents duplicate short codes."],["h","Interview answer"],["quote","I would design the URL shortener as a read-heavy service behind a load balancer. Short codes would be generated using a collision-safe strategy and stored with a unique constraint. Redis would cache popular mappings to avoid repeated database lookups. Invalid codes could use negative caching with a TTL, and rate limiting would protect the service from abuse. The application tier would be stateless and horizontally scalable."]],"realWorld":[["p","**Why it matters.** Requests for non-existent short codes still hit the database. Attackers or broken links can generate huge miss traffic. Negative caching and Bloom filters stop it cheaply."],["p","**Example.** A URL shortener receives a million hits for random codes like `/x8Qz1`. Each would query the database and find nothing. Caching 'not found' in Redis for 60 seconds, or checking a Bloom filter first, answers those instantly and keeps the database for real links."]]},{"id":2806,"category":"System Design","difficulty":"Senior","question":"Build a scalable chat application","answer":"I would use WebSockets for real-time communication, a horizontally scalable WebSocket gateway, and a message broker to distribute messages between gateway instances. Messages would be persisted so offline users can retrieve history after reconnecting. I would define message ordering and delivery semantics explicitly and use message IDs for deduplication. Presence and notifications can be separate concerns.","highlights":[],"body":[["p","Requirements:"],["code","text","1-to-1 chat\nGroup chat\nMessage delivery\nOnline/offline status\nMessage history\nNotifications\nHigh concurrency"],["h","Basic architecture"],["code","text","Client\n  |\n  v\nLoad Balancer\n  |\n  v\nWebSocket Gateway\n  |\n  +-------------------+\n  |                   |\n  v                   v\nChat Service       Presence Service\n  |\n  v\nMessage Broker\n  |\n  +----------+----------+\n  |          |          |\n  v          v          v\nMessage DB  Push      Analytics"],["h","Why WebSockets?"],["p","Traditional HTTP:"],["code","text","Client -> Request\nServer -> Response"],["p","Chat needs real-time server-to-client communication."],["p","WebSocket provides a persistent connection:"],["code","text","Client <=================> Server"],["p","The server can send messages without waiting for a new HTTP request."],["h","Message flow"],["p","User A sends:"],["code","text","\"Hello\""],["p","Flow:"],["code","text","User A\n  |\n  v\nWebSocket Gateway\n  |\n  v\nChat Service\n  |\n  v\nMessage Broker\n  |\n  +--> User B connection\n  |\n  +--> Message DB"],["h","Why message broker?"],["p","Suppose:"],["code","text","WebSocket Server 1\nWebSocket Server 2\nWebSocket Server 3"],["p","User A is connected to Server 1."],["p","User B is connected to Server 3."],["p","A broker can distribute the event:"],["code","text","Server 1\n   |\n   v\nMessage Broker\n   |\n   v\nServer 3\n   |\n   v\nUser B"],["p","Possible technologies:"],["code","text","Kafka\nRabbitMQ\nRedis Pub/Sub"],["p","Choice depends on durability, ordering, scale, delivery semantics, and operational requirements."],["h","Message persistence"],["p","Store messages in a database."],["p","Example:"],["code","text","messages\n--------------------\nmessage_id\nconversation_id\nsender_id\ncontent\ncreated_at\nstatus"],["p","For very large chat systems, database choice and partitioning strategy become important."],["h","Offline users"],["p","If User B is offline:"],["code","text","Message\n   |\n   v\nMessage DB\n   |\n   +--> Push notification"],["p","When B reconnects:"],["code","text","GET messages after last_message_id"],["p","This is better than relying solely on live WebSocket delivery."],["h","Message ordering"],["p","A distributed chat system needs a clear ordering strategy."],["p","Possible approaches:"],["code","text","Server-generated sequence number\nConversation-level sequence\nLogical timestamps\nDatabase-generated ordering"],["p","Do not rely blindly on client timestamps because clocks can differ."],["h","Delivery semantics"],["p","Clarify:"],["code","text","At-most-once\nAt-least-once\nExactly-once business behavior"],["p","For many systems, practical design uses at-least-once delivery with deduplication/idempotency."]],"realWorld":[["p","**Why it matters.** Chat design tests real-time delivery, ordering, persistence and offline handling in one problem."],["p","**Example.** A WhatsApp-style app keeps WebSocket connections to chat servers, publishes messages through a broker (Kafka/Redis), stores them in a database partitioned by conversation, delivers to offline users via push notifications and uses per-conversation sequence numbers to preserve ordering."]]},{"id":2807,"category":"System Design","difficulty":"Senior","question":"Caching strategies: cache-aside, write-through, Redis and common pitfalls","answer":"Caching stores frequently used data closer to the application/user.","highlights":[],"body":[["code","text","Client\n  |\n  v\nCache\n  |\n  +--> HIT -> Return\n  |\n  +--> MISS -> Database"],["h","Cache-aside"],["p","Most common application pattern."],["code","text","Application\n    |\n    v\nCache\n   / \\\n HIT  MISS\n  |     |\n  v     v\nReturn Database\n         |\n         v\n       Cache"],["p","Example:"],["code","javascript","let product = await redis.get(`product:${id}`);\n\nif (!product) {\n    product = await database.getProduct(id);\n\n    await redis.set(\n        `product:${id}`,\n        JSON.stringify(product),\n        { EX: 300 }\n    );\n}"],["h","Write-through"],["p","Application writes to cache and cache writes through to the database."],["p","Conceptually:"],["code","text","Application\n    |\n    v\nCache\n    |\n    v\nDatabase"],["p","Useful when you want cache and database updates tightly coordinated through the caching layer."],["h","Write-behind / write-back"],["p","Write is initially accepted by the cache and persisted later."],["code","text","Application\n    |\n    v\nCache\n    |\n    | async\n    v\nDatabase"],["p","Can improve write latency but introduces durability and consistency risks."],["p","Use carefully."],["h","Read-through"],["p","Application asks the cache for data:"],["code","text","Application\n    |\n    v\nCache\n    |\n    +--> hit -> return\n    |\n    +--> miss -> cache loads from DB"],["p","The exact implementation depends on the caching technology."],["h","Cache invalidation"],["p","One of the hardest problems."],["p","Example:"],["code","text","Product price:\n₹1000"],["p","Cache:"],["code","text","product:123 -> ₹1000"],["p","Database changes:"],["code","text","₹900"],["p","If cache is not invalidated:"],["code","text","User sees ₹1000"],["p","Possible strategies:"],["code","text","TTL\nExplicit invalidation\nVersioned keys\nEvent-driven invalidation\nWrite-through"],["h","Cache stampede"],["p","Suppose:"],["code","text","Cache key expires\n      |\n      v\n10,000 requests\n      |\n      v\nAll query database"],["p","This can overload the database."],["p","Solutions:"],["code","text","Request coalescing\nLocks\nJittered TTLs\nEarly refresh\nStale-while-revalidate"],["h","Cache penetration"],["p","Requests repeatedly ask for data that does not exist."],["p","Example:"],["code","text","/product/INVALID\n/product/INVALID\n/product/INVALID"],["p","Use:"],["code","text","Negative caching\nBloom filters\nRate limiting"],["h","Cache avalanche"],["p","Many keys expire around the same time:"],["code","text","1 million cache entries\n        |\n        v\nAll expire together\n        |\n        v\nDatabase overload"],["p","Use:"],["code","text","Randomized TTL\nStaggered expiration\nPrewarming"],["h","Interview answer"],["quote","I usually start with cache-aside for application caching. I define a TTL and an invalidation strategy based on how stale the data can be. I also consider cache stampede, penetration, and avalanche problems. For critical transactional data, I avoid caching blindly and define the consistency requirements first."],["h","Also worth knowing"],["p","A common strategy is **Cache-Aside**."],["code","text","Application\n    |\n    v\nRedis\n /   \\\nHit   Miss\n |     |\n v     v\nReturn Database\n       |\n       v\n     Redis"],["h","Java example"],["code","java","@Cacheable(\n    value = \"products\",\n    key = \"#productId\"\n)\npublic Product getProduct(Long productId) {\n\n    return productRepository\n        .findById(productId)\n        .orElseThrow();\n}"],["h","Cache invalidation"],["p","When product changes:"],["code","text","Update DB\n   ↓\nEvict cache"],["code","java","@CacheEvict(\n    value = \"products\",\n    key = \"#productId\"\n)\npublic void updateProduct(\n        Long productId,\n        ProductRequest request) {\n    // update database\n}"]],"realWorld":[["h","Real-world banking example"],["p","Cache relatively stable data:"],["code","text","Branch information\nProduct configuration\nPublic exchange-rate display data\nNon-sensitive reference data"],["p","Do not blindly cache highly sensitive or rapidly changing account balances."],["p","The caching strategy must respect consistency and security requirements."],["h","E-commerce example"],["p","Good candidates:"],["code","text","Product catalog\nCategory data\nPopular products\nRecommendations"],["p","Less suitable without careful design:"],["code","text","Inventory count\nPayment status\nOrder status"],["p","These may require stronger freshness guarantees."],["h","Banking example"],["p","Cache relatively stable reference data:"],["code","text","Currency metadata\nBranch information\nProduct configuration"],["p","Do not blindly cache highly sensitive rapidly changing account balances."]]},{"id":2808,"category":"System Design","difficulty":"Senior","question":"Load balancing, horizontal vs vertical scaling","answer":"Vertical scaling means increasing the resources of an existing machine, such as CPU or RAM. Horizontal scaling means adding more instances and distributing traffic across them. I generally prefer horizontal scaling for stateless application services because it provides elasticity and redundancy. Vertical scaling can still be useful for databases or components where scaling out is more difficult or unnecessary.","highlights":["Fewer application instances","Can be useful for databases or systems that are difficult to distribute"],"body":[["h","Vertical scaling"],["p","Increase the capacity of one machine."],["code","text","Before:\n\nServer\n4 CPU\n16 GB RAM\n\n        |\n        v\n\nAfter:\n\nServer\n32 CPU\n128 GB RAM"],["h","Advantages"],["ul",["Simple","Fewer application instances","Can be useful for databases or systems that are difficult to distribute"]],["h","Disadvantages"],["ul",["Hardware limits","Can become expensive","Usually has a single-machine ceiling","Maintenance may require downtime depending on the system"]],["h","Horizontal scaling"],["p","Add more machines/instances."],["code","text","              Load Balancer\n              /     |     \\\n             v      v      v\n          Server1 Server2 Server3"],["h","Advantages"],["ul",["Handles large traffic","Better redundancy","Can scale incrementally","Works well with stateless services"]],["h","Disadvantages"],["ul",["More operational complexity","Requires load balancing","Distributed state becomes a design issue","Requires good observability"]],["h","When would I choose vertical scaling?"],["p","For example:"],["code","text","Database"],["p","If the database architecture benefits from more CPU/RAM and horizontal database scaling is not immediately justified, vertical scaling may be appropriate."],["h","When would I choose horizontal scaling?"],["p","For stateless API services:"],["code","text","Spring Boot API\nNode.js API"],["p","Example:"],["code","text","Load Balancer\n   |\n   +--> API 1\n   +--> API 2\n   +--> API 3"],["h","Why load balancing?"],["p","It provides:"],["code","text","Traffic distribution\nHigh availability\nHorizontal scaling\nHealth checks\nFailure isolation"],["h","Health checks"],["p","If Server 2 is unhealthy:"],["code","text","Load Balancer\n    |\n    +--> Server 1  OK\n    |\n    +--> Server 2  FAILED\n    |\n    +--> Server 3  OK"],["p","Stop sending traffic to Server 2."],["h","Stateless application servers"],["p","Prefer:"],["code","text","Server 1\nServer 2\nServer 3"],["p","to be interchangeable."],["p","Avoid storing critical session state only in:"],["code","text","Server 1 RAM"],["p","because the next request may go to Server 2."],["p","Instead use:"],["code","text","Redis\nDatabase\nSigned/stateless tokens"],["p","depending on the architecture."],["h","Horizontal scaling"],["code","text","Traffic increases\n      |\n      v\nAdd instances\n      |\n      v\nLoad Balancer\n      |\n +----+----+----+\n |    |    |    |\n v    v    v    v\n A    B    C    D"],["h","Vertical scaling"],["p","Increase resources:"],["code","text","8 CPU / 32 GB\n      |\n      v\n32 CPU / 128 GB"],["h","Auto scaling"],["p","Modern infrastructure can scale based on signals such as:"],["code","text","CPU\nMemory\nRequest count\nLatency\nQueue depth\nCustom metrics"],["p","Important:"],["quote","CPU alone is not always the best scaling metric."],["p","For example, a queue-based worker system may scale based on queue depth."],["h","Interview answer"],["quote","A load balancer distributes traffic across healthy application instances. Horizontal scaling adds more instances, while vertical scaling increases the resources of an existing instance. For stateless APIs, I prefer horizontal scaling because it provides elasticity and redundancy. I also use health checks and appropriate autoscaling metrics."]],"realWorld":[["h","Real-world e-commerce example"],["p","During a sale:"],["code","text","Normal traffic:\n3 API instances\n\nPeak traffic:\n20 API instances"],["p","Horizontal scaling lets the application add instances."],["h","Banking example"],["p","A transaction API can be horizontally scaled if the application tier is stateless and the database/transaction architecture can support the additional load."],["h","Insurance example"],["p","Claims APIs may scale horizontally during periods of unusually high claim submissions."],["h","E-commerce example"],["p","During a flash sale:"],["code","text","Normal:\n3 API instances\n\nSale:\n20 API instances"],["p","Load balancer distributes requests."],["p","Cache absorbs product reads."],["p","Queue absorbs asynchronous order-related work."],["p","Database is protected from unnecessary traffic."]]},{"id":2809,"category":"System Design","difficulty":"Senior","question":"If millions of users log in simultaneously, how would you architect the system?","answer":"I would keep the authentication service stateless and horizontally scalable behind a load balancer. I would protect the identity database with connection pooling, appropriate indexing, caching where safe, and capacity planning. Passwords would be stored using a strong password-hashing algorithm such as Argon2id or bcrypt, never plaintext. I would use distributed rate limiting, WAF protection, MFA and account-risk controls to protect against brute-force attacks. After authentication, clients would use short-lived access tokens so every API request does not require password verification.","highlights":["Connection pooling","Proper indexes","Read replicas where appropriate"],"body":[["p","This is a **system design** question."],["p","The first mistake is thinking:"],["code","text","Millions of users\n      |\n      v\nOne login server"],["p","That creates a bottleneck."],["p","Instead:"],["code","text","                         Internet\n                            |\n                            v\n                       Load Balancer\n                            |\n             +--------------+--------------+\n             |              |              |\n             v              v              v\n         Auth API 1      Auth API 2      Auth API 3\n             |              |              |\n             +--------------+--------------+\n                            |\n                     Authentication\n                       datastore\n                            |\n                +-----------+-----------+\n                |                       |\n                v                       v\n              Cache                 Database"],["h","Step 1: Load balancer"],["p","Distribute requests:"],["code","text","Login request\n     |\n     v\nLoad Balancer\n /    |    \\\nv     v     v\nA     B     C"],["p","The application servers should preferably be stateless so any healthy instance can process a request."],["h","Step 2: Horizontal scaling"],["p","Run many authentication service instances."],["code","text","Auth Service\n  |\n  +--> Instance 1\n  +--> Instance 2\n  +--> Instance 3\n  +--> ..."],["p","Scale based on traffic and capacity."],["h","Step 3: Protect the database"],["p","The database is often a critical bottleneck."],["p","Use:"],["ul",["Connection pooling","Proper indexes","Read replicas where appropriate","Efficient queries","Caching where safe","Capacity planning","Rate limiting"]],["p","For password authentication, do not simply cache passwords or raw credentials."],["h","Step 4: Password hashing"],["p","Never store:"],["code","text","password = \"mypassword123\""],["p","Use a modern password hashing algorithm such as:"],["code","text","Argon2id\nbcrypt\nscrypt"],["p","The password hash should be intentionally expensive enough to resist offline attacks while remaining operationally manageable."],["h","Step 5: Brute-force protection"],["p","Attackers may intentionally send huge numbers of login attempts."],["p","Use:"],["code","text","Rate limiting\nAccount protection\nIP/device signals\nProgressive delays\nMFA\nRisk-based controls"],["h","Step 6: Token-based authentication"],["p","After successful authentication:"],["code","text","username/password\n       |\n       v\nAuthentication Service\n       |\n       v\nAccess token\n       |\n       v\nClient"],["p","Subsequent API calls can use the access token rather than repeatedly sending the password."],["h","Step 7: Distributed rate limiting"],["p","If there are many application instances:"],["code","text","Request\n   |\n   +--> Server 1\n   +--> Server 2\n   +--> Server 3"],["p","An in-memory counter on each server is not sufficient for a global limit."],["p","Use a shared mechanism such as Redis:"],["code","text","Server 1 ----\\\nServer 2 -----+----> Redis rate-limit state\nServer 3 ----/"]],"realWorld":[["h","Banking example"],["p","For a banking login system:"],["code","text","User\n |\n v\nCDN/WAF\n |\n v\nLoad Balancer\n |\n v\nAuthentication Service\n |\n +--> Identity Store\n +--> Risk/Fraud Service\n +--> MFA Service\n |\n v\nToken"],["p","Additional controls can include:"],["ul",["MFA","Device risk","Geo/risk signals","Account lockout policies","Fraud detection","Audit logging"]],["h","Insurance example"],["p","Agents and customers may access different portals:"],["code","text","Customer Portal\nAgent Portal\n     |\n     v\nAuthentication Service\n     |\n     +--> Identity Provider\n     +--> MFA\n     +--> Authorization"],["h","E-commerce example"],["p","During a major sale:"],["code","text","Millions of users\n       |\n       v\nLoad Balancer\n       |\n       v\nMultiple Auth Instances\n       |\n       +--> Redis\n       |\n       +--> User DB"],["p","**In practice.** On Monday 9 a.m. a banking app gets 2 million logins. Load balancers spread traffic over many stateless auth servers, password hashing uses a tuned algorithm (bcrypt/argon2) on separate nodes, Redis stores rate limits and sessions, and the database is protected with caching and read replicas."]]},{"id":2810,"category":"System Design","difficulty":"Senior","question":"Design a scalable full-stack architecture","answer":"Use Redis or another suitable cache for frequently accessed data.","highlights":["Proper indexes","Query optimization","Connection pooling"],"body":[["p","A typical scalable architecture could look like:"],["code","text","                  Users\n                    |\n                    v\n              Load Balancer\n                    |\n                    v\n               API Gateway\n                    |\n        +-----------+-----------+\n        |           |           |\n        v           v           v\n     Service A   Service B   Service C\n        |           |           |\n        v           v           v\n      Cache       Cache       Cache\n        |           |           |\n        +-----------+-----------+\n                    |\n               Message Broker\n                    |\n        +-----------+-----------+\n        |           |           |\n        v           v           v\n    Database     Search      Object Storage"],["h","Frontend"],["p","Possible technologies:"],["code","text","React / Angular / Vue"],["p","Example React call:"],["code","javascript","async function getProducts() {\n    const response = await fetch(\"/api/products\");\n    return response.json();\n}"],["h","Backend"],["code","text","React\n  |\n  v\nAPI Gateway\n  |\n  v\nSpring Boot REST API\n  |\n  +--> Service\n  |\n  +--> Repository\n  |\n  +--> Database"],["h","1. Horizontal scaling"],["p","Run multiple instances:"],["code","text","              Load Balancer\n              /     |     \\\n             v      v      v\n          App-1   App-2   App-3"],["h","2. Caching"],["p","Example:"],["code","text","GET Product\n   |\n   v\nCache?\n /   \\\nYes   No\n |     |\n v     v\nReturn DB\n       |\n       v\n     Cache"],["h","3. Database optimization"],["p","Use:"],["ul",["Proper indexes","Query optimization","Connection pooling","Read replicas where appropriate","Partitioning/sharding when justified"]],["h","4. Asynchronous processing"],["p","Use a message broker for operations that do not need to block the user request."],["p","Example:"],["code","text","Order Created\n     |\n     v\nMessage Broker\n     |\n     +--> Notification Service\n     |\n     +--> Inventory Service\n     |\n     +--> Analytics Service"],["h","Also worth knowing"],["p","A typical scalable Java full-stack system can look like:"],["code","text","                         Users\n                           |\n                           v\n                    React Application\n                           |\n                           v\n                    CDN / Load Balancer\n                           |\n                           v\n                      API Gateway\n                           |\n        +------------------+------------------+\n        |                  |                  |\n        v                  v                  v\n   User Service       Order Service      Payment Service\n        |                  |                  |\n        |                  |                  |\n        +------------------+------------------+\n                           |\n                   +-------+-------+\n                   |               |\n                   v               v\n                 Redis           Kafka\n                                   |\n                    +--------------+--------------+\n                    |              |              |\n                    v              v              v\n              Notification      Analytics       Audit\n\nServices\n   |\n   v\nPostgreSQL / MySQL\n\nObservability\n   |\n   +-- Logs\n   +-- Metrics\n   +-- Traces\n   +-- Alerts"],["h","Also worth knowing"],["p","Let's combine React, Node.js, databases, caching, authentication, and scaling."],["code","text","                         Users\n                           |\n                           v\n                         CDN\n                           |\n                           v\n                         WAF\n                           |\n                           v\n                    Load Balancer\n                           |\n             +-------------+-------------+\n             |             |             |\n             v             v             v\n          React          React         React\n          App/CDN        App/CDN       App/CDN\n                           |\n                           v\n                      API Gateway\n                           |\n             +-------------+-------------+\n             |             |             |\n             v             v             v\n          Node API      Node API      Node API\n             |             |             |\n             +-------------+-------------+\n                           |\n          +----------------+----------------+\n          |                |                |\n          v                v                v\n       Redis           Message Broker     Database\n          |                |                |\n          |          +-----+-----+          |\n          |          |     |     |          |\n          v          v     v     v          v\n       Cache      Email  Worker Search    SQL/Mongo\n                  Service Services"],["h","Authentication flow"],["code","text","React\n  |\n  v\nIdentity Provider\n  |\n  v\nAccess Token\n  |\n  v\nAPI Gateway\n  |\n  v\nNode API\n  |\n  v\nAuthorization"],["h","Order flow"],["code","text","React\n  |\n  v\nPOST /orders\n  |\n  v\nNode API\n  |\n  v\nDatabase Transaction\n  |\n  v\nOrder Created\n  |\n  v\nMessage Broker\n  |\n  +--> Inventory\n  +--> Email\n  +--> Analytics"],["p","This prevents non-critical downstream work from unnecessarily blocking the main request."],["h","Also worth knowing"],["p","If the interviewer asks:"],["quote","How would you design a scalable Spring Boot full-stack application?"],["p","A strong answer is:"],["quote","I would start with a React or Angular frontend and expose REST APIs through an API gateway. The backend would use Spring Boot with a controller-service-repository structure. For larger systems, I would split independently deployable business capabilities into microservices. Each service would have a clear data ownership boundary. I would use PostgreSQL or another suitable relational database for transactional data, Redis for appropriate caching use cases, and Kafka or another message broker for asynchronous communication. I would secure the APIs using OAuth2/OIDC and JWT access tokens, with role or permission-based authorization. For scalability, I would keep services stateless, use horizontal scaling behind a load balancer, optimize database access, and use caching where appropriate. For reliability, I would add timeouts, retries where safe, circuit breakers, idempotency, and proper error handling. Finally, I would use Spring Boot Actuator, metrics, logs, tracing, and centralized monitoring for observability."]],"realWorld":[["h","E-commerce architecture example"],["code","text","React Web App\n      |\n      v\nAPI Gateway\n      |\n      +--> Product Service\n      +--> Cart Service\n      +--> Order Service\n      +--> Payment Service\n      +--> Inventory Service\n      +--> User Service"],["p","A product search request should not require the payment service to be available."],["h","E-commerce request flow"],["p","User opens product page:"],["code","text","React\n  |\n  v\nGET /products/123\n  |\n  v\nLoad Balancer\n  |\n  v\nNode API\n  |\n  v\nRedis\n  |\n  +--> HIT -> Product\n  |\n  +--> MISS\n         |\n         v\n       MySQL\n         |\n         v\n       Redis\n         |\n         v\n       Product"],["p","**In practice.** A retail platform is split into a CDN-served React front end, an API gateway, stateless services, a relational database with read replicas, Redis caching and a message queue. Each layer can be scaled and failed independently, which is the point interviewers want to hear."]]},{"id":2811,"category":"System Design","difficulty":"Senior","question":"Design a Food Delivery System","answer":"Services do not need direct synchronous calls for every event.","highlights":["browse restaurants","view menus","place orders"],"body":[["h","Requirements"],["p","Users should be able to:"],["ul",["browse restaurants","view menus","place orders","pay","track delivery","receive notifications"]],["h","High-level architecture"],["code","text","                    React / Mobile\n                         |\n                         v\n                  Load Balancer\n                         |\n                         v\n                    API Gateway\n                         |\n       +-----------------+------------------+\n       |                 |                  |\n       v                 v                  v\n User Service      Restaurant Service   Order Service\n                                           |\n                                           v\n                                    Payment Service\n                                           |\n                                           v\n                                      Delivery Service\n                                           |\n                                           v\n                                    Notification Service\n\n       Services\n          |\n          +---- PostgreSQL / MySQL\n          +---- Redis\n          +---- Kafka"],["h","Order flow"],["code","text","Customer\n ↓\nCreate Order\n ↓\nOrder Service\n ↓\nReserve / Validate\n ↓\nPayment\n ↓\nOrder Confirmed\n ↓\nKafka Event\n ↓\nRestaurant\n ↓\nDelivery Assignment\n ↓\nCustomer Notification"],["h","Why Kafka?"],["p","Use events such as:"],["code","text","OrderCreated\nPaymentCompleted\nOrderPrepared\nDriverAssigned\nOrderDelivered"]],"realWorld":[["p","**Why it matters.** Food-delivery design combines catalogue, ordering, payment, real-time tracking and asynchronous events."],["p","**Example.** Placing an order calls the order service, which reserves stock, charges payment, then publishes `OrderPlaced` to Kafka. Restaurant, delivery assignment and notification services consume the event independently, and a rider's GPS updates stream through WebSockets to the customer's tracking screen."]]},{"id":2812,"category":"System Design","difficulty":"Senior","question":"Notification Service for Millions of Users","answer":"The banking transaction should not wait for all notification providers.","highlights":["dead-letter topic","idempotency","rate limits"],"body":[["p","Notification types:"],["code","text","Email\nSMS\nPush Notification\nIn-App Notification"],["h","Architecture"],["code","text","Application Services\n       |\n       v\n      Kafka\n       |\n       +----------------+\n       |                |\n       v                v\n Email Workers      Push Workers\n       |                |\n       v                v\n Email Provider     FCM/APNs"],["h","Scaling"],["p","If there are millions of notifications:"],["code","text","Kafka Topic\n   |\n   +-- Consumer 1\n   +-- Consumer 2\n   +-- Consumer 3\n   +-- Consumer N"],["p","Increase consumers to process more messages."],["h","Important design points"],["ul",["retry","dead-letter topic","idempotency","rate limits","provider failure handling","user preferences","priority notifications"]],["h","Example"],["p","A bank publishes:"],["code","text","TransactionCompleted"],["p","Notification service consumes it and sends:"],["code","text","SMS\nPush\nEmail"]],"realWorld":[["p","**Why it matters.** Notifications must scale to millions without blocking core flows or spamming users, so they run asynchronously with retries and preferences."],["p","**Example.** A bank sends 5 million transaction alerts a day. Business services publish events to a queue, a notification service fans out to SMS, email and push workers, retries failed deliveries with backoff, deduplicates by event id and respects user opt-outs and rate limits."]]},{"id":2813,"category":"System Design","difficulty":"Mid","question":"Synchronous vs Asynchronous Communication","answer":"Synchronous calls are simple but couple services' availability; asynchronous messaging decouples them and absorbs spikes.","highlights":["notifications","analytics","audit events"],"body":[["h","Synchronous"],["code","text","Order\n ↓\nPayment\n ↓\nResponse"],["p","Order waits for payment."],["p","Use when immediate response is required."],["h","Asynchronous"],["code","text","Order\n ↓\nKafka\n ↓\nPayment Consumer"],["p","Use for:"],["ul",["notifications","analytics","audit events","background processing","long-running operations"]]],"realWorld":[["p","**Why it matters.** Synchronous calls are simple but couple services' availability; asynchronous messaging decouples them and absorbs spikes."],["p","**Example.** Checkout calls the payment service synchronously because the user must wait for the result. After payment, sending the confirmation email, updating analytics and notifying the warehouse happen asynchronously via events so a slow email provider never delays the order."]]},{"id":2814,"category":"System Design","difficulty":"Senior","question":"How do you approach a system design interview? (step-by-step framework)","answer":"When given a design question, don't immediately start drawing boxes.","highlights":[],"body":[["p","Use this sequence:"],["h","Step 1: Clarify requirements"],["p","Ask:"],["code","text","How many users?\nHow many requests per second?\nRead-heavy or write-heavy?\nStrong consistency required?\nAvailability requirement?\nData retention?\nSecurity requirements?"],["h","Step 2: Estimate scale"],["p","For example:"],["code","text","10 million users\n1 million daily active users\n100,000 requests/second peak"],["p","The exact numbers are hypothetical; the important part is showing that you think about scale."],["h","Step 3: Start with simple architecture"],["code","text","Client\n  |\nLoad Balancer\n  |\nApplication\n  |\nDatabase"],["p","Then identify bottlenecks."],["h","Step 4: Scale the bottlenecks"],["p","Add:"],["code","text","Cache\nMultiple app instances\nRead replicas\nMessage broker\nCDN\nRate limiter"],["p","Only add components when they solve a real problem."],["h","Step 5: Discuss failure cases"],["p","Ask:"],["code","text","What if Redis is unavailable?\nWhat if the database is slow?\nWhat if one application instance crashes?\nWhat if a downstream service times out?\nWhat if the same payment request arrives twice?"],["h","Step 6: Discuss observability"],["p","Include:"],["code","text","Logs\nMetrics\nTracing\nAlerts\nHealth checks"],["h","Also worth knowing"],["p","When interviewer says:"],["quote","Design a food delivery system."],["p","Do not immediately start drawing boxes."],["p","Use:"],["h","Step 1 --- Requirements"],["p","Ask:"],["code","text","What features?\nExpected users?\nTraffic?\nAvailability requirements?\nReal-time tracking?"],["h","Step 2 --- APIs"],["p","Example:"],["code","text","POST /orders\nGET /orders/{id}\nPOST /payments\nGET /restaurants"],["h","Step 3 --- Data model"],["code","text","User\nRestaurant\nMenu\nOrder\nPayment\nDelivery"],["h","Step 4 --- High-level architecture"],["code","text","Client\n ↓\nGateway\n ↓\nServices\n ↓\nDB / Cache / Kafka"],["h","Step 5 --- Scaling"],["p","Discuss:"],["ul",["horizontal scaling","caching","database indexes","read replicas","partitioning","Kafka partitions","CDN"]],["h","Step 6 --- Reliability"],["p","Discuss:"],["ul",["timeout","retry","circuit breaker","idempotency","fallback","dead-letter queues"]],["h","Step 7 --- Observability"],["p","Discuss:"],["ul",["logs","metrics","traces","alerts"]],["h","Also worth knowing"],["p","When the interviewer asks:"],["quote","Design a scalable application."],["p","Follow this sequence:"],["code","text","1. Clarify requirements\n        |\n        v\n2. Estimate scale\n        |\n        v\n3. Define APIs / data model\n        |\n        v\n4. Draw simple architecture\n        |\n        v\n5. Identify bottlenecks\n        |\n        v\n6. Add cache / queues / replicas / scaling\n        |\n        v\n7. Discuss failure scenarios\n        |\n        v\n8. Discuss security\n        |\n        v\n9. Discuss observability\n        |\n        v\n10. Explain trade-offs"]],"realWorld":[["p","**Why it matters.** A repeatable framework keeps system design answers structured under pressure and shows senior-level thinking."],["p","**Example.** Asked to 'design a ride-hailing system', start by clarifying scope (riders, drivers, surge pricing?), estimate scale (e.g. 1M rides/day), sketch simple services, then scale hot spots (location updates, matching), discuss failures (driver app offline) and observability (latency, matching success rate)."]]},{"id":2815,"category":"System Design","difficulty":"Mid","question":"Distributed Tracing","answer":"In microservices one request touches many services; distributed tracing shows where time and errors occur.","highlights":["OpenTelemetry","Datadog APM"],"body":[["p","A request may travel through:"],["code","text","React\n ↓\nAPI Gateway\n ↓\nOrder Service\n ↓\nPayment Service\n ↓\nNotification Service"],["p","Use distributed tracing."],["h","Trace"],["code","text","Trace ID: abc123\n\nGateway\n  ├── 50ms\n  |\n  └── Order Service\n       ├── 100ms\n       |\n       └── Payment Service\n             └── 4.5 sec"],["p","Now the bottleneck is clear."],["h","Technologies"],["ul",["OpenTelemetry","Jaeger","Zipkin","Datadog APM"]],["h","Correlation ID"],["p","A request ID can also be propagated:"],["code","text","X-Correlation-ID: abc123"],["p","Every service logs it."]],"realWorld":[["p","**Why it matters.** In microservices one request touches many services; distributed tracing shows where time and errors occur."],["p","**Example.** A checkout takes 6 seconds. The trace (Jaeger/Zipkin, with a correlation id passed in headers) shows 5 s spent in a call from the order service to an inventory service doing a slow query, so the team fixes that one service instead of guessing."]]},{"id":2816,"category":"Microservices","difficulty":"Senior","question":"How do you split a monolith into microservices (and build them with Spring Boot)?","answer":"A microservice architecture splits a system into independently deployable services.","highlights":["API Gateway","Service discovery where needed","Centralized configuration"],"body":[["h","Spring Boot service"],["code","java","@SpringBootApplication\npublic class OrderServiceApplication {\n\n    public static void main(String[] args) {\n        SpringApplication.run(\n            OrderServiceApplication.class, args);\n    }\n}"],["h","Service-to-service communication"],["p","For example:"],["code","text","Order Service\n      |\n      | request\n      v\nInventory Service"],["p","Modern Spring applications can use HTTP clients such as `RestClient` or declarative HTTP clients, depending on the architecture."],["h","Important microservice concepts"],["ul",["API Gateway","Service discovery where needed","Centralized configuration","Authentication/authorization","Timeouts","Retries","Circuit breakers","Distributed tracing","Centralized logging","Metrics","Message brokers","Database-per-service"]],["h","Important interview point"],["p","\"Microservices are not simply multiple Spring Boot projects. The architecture also requires independent ownership, deployment, data boundaries, observability, resilience, and well-defined communication contracts.\""],["h","Also worth knowing"],["p","Do not immediately split every class into a service."],["p","First identify business boundaries."],["p","Example monolith:"],["code","text","Banking Application\n ├── Customer\n ├── Account\n ├── Payment\n ├── Notification\n └── Reporting"],["p","Possible services:"],["code","text","Customer Service\nAccount Service\nPayment Service\nNotification Service\nReporting Service"],["h","Migration approach"],["p","A practical approach is the **Strangler Fig pattern**:"],["code","text","Old Monolith\n     |\n     +---- New Payment Service\n     |\n     +---- New Notification Service\n     |\n     +---- Remaining Monolith"],["p","Gradually move functionality."],["h","Important considerations"],["ul",["service boundaries","database ownership","API contracts","events","observability","deployment","rollback","data migration"]],["h","Interview answer"],["quote","I would start from business capabilities and identify bounded contexts. I would extract one service at a time, preferably around a well-defined domain, and use an API gateway or event-driven integration while gradually reducing the monolith."]],"realWorld":[["h","E-commerce example"],["code","text","                 API Gateway\n                      |\n       +--------------+--------------+\n       |              |              |\n       v              v              v\n Product Service   Order Service   Payment Service\n       |              |              |\n   Product DB      Order DB      Payment DB"],["p","Possible services:"],["code","text","product-service\norder-service\npayment-service\ninventory-service\nnotification-service"],["h","Insurance example"],["code","text","Policy Service\nClaim Service\nCustomer Service\nPayment Service\nDocument Service\nNotification Service"],["p","A claim can involve several services without putting all business logic into one large application."],["h","Banking example"],["code","text","Customer Service\nAccount Service\nTransaction Service\nPayment Service\nFraud Service\nNotification Service"],["p","**In practice.** An e-commerce monolith with checkout, catalogue and inventory is split along business capabilities, extracting the most independently scalable piece first (inventory). Each Spring Boot service owns its database, communicates by REST or events, and a gateway hides the change from clients."]]},{"id":2817,"category":"Microservices","difficulty":"Mid","question":"API Gateway Architecture","answer":"An API gateway is the single entry point that handles cross-cutting concerns so each service does not repeat them.","highlights":["authentication","authorization","rate limiting"],"body":[["code","text","                    Clients\n                       |\n                       v\n                 Load Balancer\n                       |\n                       v\n                  API Gateway\n                  /    |     \\\n                 /     |      \\\n                v      v       v\n             User   Order   Payment\n           Service Service  Service"],["h","Responsibilities"],["ul",["routing","authentication","authorization","rate limiting","request validation","TLS termination","logging","correlation ID","sometimes response aggregation"]]],"realWorld":[["p","**Why it matters.** An API gateway is the single entry point that handles cross-cutting concerns so each service does not repeat them."],["p","**Example.** A gateway (Spring Cloud Gateway/Kong) authenticates JWTs, rate-limits per client, routes `/orders` and `/payments` to the right services, aggregates responses for the mobile app and adds request logging. Services behind it can stay private."]]},{"id":2818,"category":"Microservices","difficulty":"Mid","question":"Where Would You Use Kafka and Why?","answer":"Kafka is a durable, partitioned event log for high-throughput streaming and decoupling, not a replacement for every queue or REST call.","highlights":["high throughput","event-driven architecture","asynchronous processing"],"body":[["h","Example"],["p","Bank transfer:"],["code","text","Payment Service\n      |\n      | PaymentCompleted\n      v\n    Kafka\n   /  |   \\\n  v   v    v\nAudit Notification Analytics"],["p","The payment service does not need to synchronously call all three systems."],["h","Kafka concepts"],["code","text","Producer\n   ↓\nTopic\n   ↓\nPartitions\n   ↓\nConsumer Group\n   ↓\nConsumers"],["h","Partitioning"],["p","For order events:"],["code","text","key = orderId"],["p","This can help keep events for the same order ordered within a partition."],["h","Use Kafka when"],["ul",["high throughput","event-driven architecture","asynchronous processing","integration between services","replay requirements","stream processing"]],["h","Don't use Kafka for everything"],["p","For a simple synchronous CRUD request, normal REST may be enough."]],"realWorld":[["p","**Why it matters.** Kafka is a durable, partitioned event log for high-throughput streaming and decoupling, not a replacement for every queue or REST call."],["p","**Example.** An e-commerce platform publishes `OrderPlaced` to Kafka. Inventory, analytics, email and fraud services each consume it at their own pace, and a new recommendation service can replay the last week of events later without changing the producer."]]},{"id":2819,"category":"Microservices","difficulty":"Senior","question":"How do you handle service failures and retries (exponential backoff, circuit breaker)?","answer":"I use bounded retries with exponential backoff and jitter, retry only transient failures, and make write operations idempotent where possible. For offline apps, failed operations can remain in a durable sync queue until they succeed or require user intervention.","highlights":["Retries can make an outage worse if used without limits.","Which errors are retryable?","How many times?"],"body":[["p","Never retry everything forever."],["p","A good retry strategy considers:"],["ul",["Which errors are retryable?","How many times?","How long to wait?","Is the operation idempotent?","Is the network available?","What happens after retries are exhausted?"]],["h","Exponential backoff"],["p","Example delays:"],["code","text","1 second\n2 seconds\n4 seconds\n8 seconds\n16 seconds"],["p","Add jitter to prevent many clients from retrying simultaneously."],["h","Example"],["code","js","async function retry(operation, maxRetries = 3) {\n  for (let attempt = 0; attempt <= maxRetries; attempt++) {\n    try {\n      return await operation();\n    } catch (error) {\n      if (attempt === maxRetries) {\n        throw error;\n      }\n\n      const delay =\n        1000 * Math.pow(2, attempt);\n\n      await new Promise(resolve =>\n        setTimeout(resolve, delay)\n      );\n    }\n  }\n}"],["h","What should not be blindly retried?"],["p","A request like:"],["code","http","POST /create-payment"],["p","could accidentally create duplicates if the server doesn't support idempotency."],["h","Idempotency"],["p","A client can send an idempotency key:"],["code","http","Idempotency-Key: payment-12345"],["p","The server remembers the result for that operation and avoids creating duplicates when the same request is retried."],["h","Offline queue"],["p","For an offline mobile app:"],["code","text","Operation failed\n      ↓\nStore in local queue\n      ↓\nNetwork returns\n      ↓\nRetry\n      ↓\nSuccess → remove from queue\n      ↓\nFailure → increase retry count\n      ↓\nPermanent failure → notify/user action"],["h","Also worth knowing"],["p","Never blindly retry every failure."],["p","Example:"],["code","text","Order Service\n     |\n     v\nPayment Service\n     |\n     X DOWN"],["p","Use:"],["ul",["timeout","retry with exponential backoff","jitter","circuit breaker","fallback","dead-letter processing where appropriate","idempotency"]],["h","Exponential backoff"],["code","text","Attempt 1 → 100ms\nAttempt 2 → 200ms\nAttempt 3 → 400ms\nAttempt 4 → 800ms"],["p","Add jitter so thousands of clients do not retry at exactly the same time."],["h","Circuit breaker"],["code","text","Normal\n ↓\nFailures increase\n ↓\nCircuit OPEN\n ↓\nStop calling failing service\n ↓\nWait\n ↓\nHalf-Open\n ↓\nTest request\n ↓\nSuccess → Closed"],["h","Important"],["p","Retries can make an outage worse if used without limits."]],"realWorld":[["h","Real-world example"],["p","A user uploads a document in a weak-network area. The upload fails. The app shouldn't make the user manually recreate the operation each time. It can keep a pending upload and retry when connectivity returns."],["p","**In practice.** A call to the shipping service times out. The order service retries after 1 s, 2 s and 4 s with jitter (exponential backoff), and a circuit breaker stops calls after repeated failures so the shipping service can recover instead of being flooded."]]},{"id":2820,"category":"Microservices","difficulty":"Senior","question":"Payment service is down: what will your application do?","answer":"I would avoid treating payment failure as a generic application failure. The order can move to a well-defined pending state, the payment request should be idempotent, and recovery can happen through controlled retry or reconciliation.","highlights":["circuit breaker","idempotency key","retry with backoff"],"body":[["p","Do not allow the entire application to fail."],["p","Example:"],["code","text","User\n ↓\nOrder Service\n ↓\nPayment Service X"],["p","Possible response:"],["code","text","Order status = PAYMENT_PENDING"],["p","Then:"],["code","text","Payment Service recovers\n        ↓\nRetry / reconciliation\n        ↓\nPayment completed\n        ↓\nOrder confirmed"],["h","Important techniques"],["ul",["timeout","circuit breaker","idempotency key","retry with backoff","asynchronous payment workflow","reconciliation","clear order state"]]],"realWorld":[["p","**Why it matters.** Dependencies fail. Senior engineers design for degraded operation using timeouts, retries, circuit breakers and fallbacks."],["p","**Example.** When the payment provider returns errors, the order service stops hammering it (circuit breaker opens), saves the order as `PAYMENT_PENDING`, shows the customer 'we will confirm shortly', retries from a queue with backoff and reconciles when the provider recovers."]]},{"id":2821,"category":"Microservices","difficulty":"Senior","question":"What is idempotency and why does it matter in payment systems?","answer":"for the same order if the business rule allows only one invoice.","highlights":[],"body":[["p","This is an important follow-up."],["p","Imagine the client sends:"],["code","http","POST /orders/123/invoice"],["p","twice because of a network retry."],["p","You don't want:"],["code","text","Invoice 1001\nInvoice 1002"],["h","Solution"],["p","Use idempotency and/or a database constraint."],["p","Example:"],["code","text","order_id = 123\ninvoice_type = STANDARD"],["p","can have a unique constraint if business rules require one invoice of that type per order."],["p","Conceptually:"],["code","sql","UNIQUE(order_id, invoice_type)"],["h","Idempotency key"],["p","Client sends:"],["code","http","Idempotency-Key: 9f4d..."],["p","The server stores the result associated with that key and returns the same result for a duplicate request."],["h","Interview answer"],["quote","I would make invoice creation idempotent. Depending on the business rule, I can enforce uniqueness at the database level and also support an idempotency key at the API level. This protects against duplicate requests caused by retries or users double-clicking."],["h","Also worth knowing"],["p","This is a very important interview concept."],["p","Suppose the client sends:"],["code","text","POST /payments"],["p","Network timeout happens."],["p","Client does not know whether payment succeeded."],["p","It retries."],["p","Without idempotency:"],["code","text","₹10,000\n+\n₹10,000\n=\n₹20,000 charged"],["p","With an idempotency key:"],["code","http","Idempotency-Key: payment-12345"],["p","The server recognizes the same request and avoids duplicate processing."],["h","Flow"],["code","text","Client\n ↓\nPayment Request\n ↓\nIdempotency Key\n ↓\nPayment Service\n ↓\nCheck existing request\n ↓\nAlready processed?\n   |\n   +-- Yes → Return previous result\n   |\n   +-- No → Process payment"],["h","Also worth knowing"],["p","Example:"],["code","text","DB commit\n   ↓\nApplication crashes\n   ↓\nClient receives no response"],["p","The client may retry."],["p","If invoice creation isn't idempotent:"],["code","text","Duplicate invoice"],["p","This is another reason idempotency matters."],["h","Correct design"],["code","text","Request\n  ↓\nIdempotent operation\n  ↓\nTransaction\n  ↓\nCommit\n  ↓\nReturn existing result if retried"]],"realWorld":[["p","**Why it matters.** Retries and double-clicks cause duplicate operations. Idempotency makes repeating a request safe."],["p","**Example.** A customer double-taps 'Pay' on a slow network. The client sends the same `Idempotency-Key: 8f3a...`. The server stores the key with the first result and returns that same response for the repeat instead of charging twice. The invoice service uses a unique constraint on (order_id, invoice_type) for the same reason."]]},{"id":2822,"category":"Production Scenarios","difficulty":"Senior","question":"An API got slow (200 ms to 5 s) or a search is slow: how do you diagnose and fix it?","answer":"I would not immediately increase server capacity. First I would use metrics and traces to locate the bottleneck, then inspect database queries, external calls, thread and connection pools, GC and recent deployments.","highlights":["slow queries","execution plans","connection pool exhaustion"],"body":[["p","I would investigate systematically."],["h","Step 1 --- Check metrics"],["code","text","CPU\nMemory\nGC\nThread pools\nConnection pools\nRequest rate\nError rate"],["h","Step 2 --- Distributed tracing"],["p","Find where the extra 4.8 seconds is spent."],["h","Step 3 --- Database"],["p","Check:"],["ul",["slow queries","execution plans","locks","connection pool exhaustion","missing indexes"]],["h","Step 4 --- External services"],["p","Check:"],["code","text","Payment API\nCustomer API\nThird-party API"],["h","Step 5 --- Recent deployment"],["p","Ask:"],["code","text","Did latency increase after a release?"],["h","Step 6 --- Traffic"],["p","Maybe traffic increased significantly."],["p","I would investigate the complete flow:"],["code","text","Frontend\n ↓\nAPI\n ↓\nBackend\n ↓\nDatabase"],["p","Then check:"],["h","Frontend"],["ul",["Unnecessary API calls","Debouncing search","Excessive rendering","Large response processing"]],["h","Backend"],["ul",["Query logic","Filtering","Pagination","Serialization","API latency"]],["h","Database"],["ul",["Indexes","Query execution plan","Full table scans","N+1 queries"]],["h","Network"],["ul",["Response size","Compression","Latency"]],["h","Strong answer"],["quote","I wouldn't immediately add caching or indexes. First I would measure where the latency occurs. Then I would optimize the specific bottleneck and compare before-and-after metrics."],["h","Also worth knowing"],["p","A strong answer should include measurable improvements."],["p","Example:"],["quote","One API was taking around 2 seconds because it was making multiple database queries. I analyzed the SQL execution plan, added the required indexes, removed unnecessary columns, introduced Redis caching for frequently accessed reference data, and reduced N+1 queries. After the changes, average response time dropped significantly."],["h","Things to investigate"],["code","text","API\n ↓\nController time\n ↓\nService time\n ↓\nDB time\n ↓\nExternal API time\n ↓\nSerialization"],["h","Techniques"],["ul",["Database indexes","Query optimization","Pagination","Redis","Connection pooling","Async processing","Batch operations","Reduce network calls","Avoid N+1","Compression where appropriate"]]],"realWorld":[["p","**Why it matters.** Diagnosing slowness is systematic: measure, locate the slow hop, then fix the cause rather than adding hardware blindly."],["p","**Example.** An API went from 200 ms to 5 s after a release. Traces showed a new query without an index on a growing table. Adding the index, plus caching a hot lookup in Redis, brought it back to 150 ms. Dashboards and an alert on p95 latency now catch regressions earlier."]]},{"id":2823,"category":"Production Scenarios","difficulty":"Senior","question":"One Microservice Has High CPU and Memory","answer":"Do not restart blindly unless needed to protect availability.","highlights":["infinite loops","expensive algorithms","excessive serialization"],"body":[["p","Check in this order:"],["h","CPU"],["p","Look for:"],["ul",["infinite loops","expensive algorithms","excessive serialization","high traffic","CPU-heavy requests","thread contention"]],["h","Memory"],["p","Look for:"],["ul",["memory leak","large collections","unbounded caches","large payloads","excessive object allocation"]],["h","JVM"],["p","Check:"],["code","text","Heap\nGC frequency\nGC pause\nThread count\nHeap dump\nThread dump"],["h","Production investigation"],["code","text","Monitoring\n   ↓\nMetrics\n   ↓\nLogs\n   ↓\nTraces\n   ↓\nThread dump / Heap dump\n   ↓\nRoot cause"]],"realWorld":[["p","**Why it matters.** High CPU or memory in one service needs evidence (metrics, profiles, heap dumps) before changing code or scaling."],["p","**Example.** A Java service hit 95% CPU after a feature launch. A thread dump and profiler showed a regex running on every request; precompiling the pattern and caching results dropped CPU to 30%. A separate memory growth issue was traced with a heap dump to an unbounded in-memory map."]]},{"id":2824,"category":"Production Scenarios","difficulty":"Senior","question":"Production Debugging Framework","answer":"A debugging framework shows calm, structured thinking in incidents: reproduce, scope, hypothesise, verify, fix and prevent.","highlights":[],"body":[["p","When something fails, use:"],["code","text","1. What changed?\n2. What is the impact?\n3. Is it one user or everyone?\n4. Check metrics.\n5. Check logs.\n6. Check traces.\n7. Check database.\n8. Check dependencies.\n9. Mitigate.\n10. Find root cause.\n11. Prevent recurrence."],["h","Example"],["p","API latency:"],["code","text","5 sec\n ↓\nTrace\n ↓\nDB = 4.5 sec\n ↓\nSlow query\n ↓\nEXPLAIN\n ↓\nMissing index\n ↓\nFix\n ↓\nMonitor"]],"realWorld":[["p","**Why it matters.** A debugging framework shows calm, structured thinking in incidents: reproduce, scope, hypothesise, verify, fix and prevent."],["p","**Example.** Orders fail intermittently. The team checks error rate dashboards (scope: only region X), recent deployments (a config change), logs by correlation id (timeouts to a service), rolls back the change, then adds a test and an alert so it cannot recur silently."]]},{"id":2825,"category":"Production Scenarios","difficulty":"Mid","question":"How do you monitor a production Spring Boot system (Actuator, metrics, alerts)?","answer":"Spring Boot Actuator provides production monitoring and management endpoints. Banking example: A load balancer or Kubernetes environment can use health information to determine whether a payment service instance is healthy.","highlights":[],"body":[["p","Common endpoints include:"],["code","text","/actuator/health\n/actuator/info\n/actuator/metrics"],["p","Example dependency:"],["code","xml","<dependency>\n    <groupId>org.springframework.boot</groupId>\n    <artifactId>spring-boot-starter-actuator</artifactId>\n</dependency>"],["p","Configuration example:"],["code","properties","management.endpoints.web.exposure.include=health,info,metrics"],["p","Health check:"],["code","text","GET /actuator/health"],["p","Possible response:"],["code","json","{\n  \"status\": \"UP\"\n}"],["p","**Interview point:** Actuator is mainly used for monitoring, health checks, metrics, and operational visibility."],["p","**Security warning:** Do not expose sensitive actuator endpoints publicly without proper security controls."],["h","Also worth knowing"],["p","Typical production stack:"],["code","text","Application\n    |\n    +--> Logs\n    |\n    +--> Metrics\n    |\n    +--> Traces\n    |\n    +--> Alerts"],["p","Common technologies:"],["h","Metrics"],["ul",["Prometheus","Grafana","CloudWatch","Azure Monitor","Datadog"]],["h","Logs"],["ul",["ELK / Elastic Stack","OpenSearch","Splunk"]],["h","Distributed tracing"],["ul",["OpenTelemetry","Jaeger","Zipkin","Datadog APM"]],["h","Spring Boot Actuator"],["code","text","/actuator/health\n/actuator/metrics"],["h","Interview answer"],["quote","I use metrics to identify resource problems, logs for detailed application events, and distributed tracing to understand where time is spent across microservices."]],"realWorld":[["p","**Why it matters.** Monitoring turns production from a black box into something you can reason about, using health checks, metrics and alerts."],["p","**Example.** Spring Boot Actuator exposes `/actuator/health` for Kubernetes probes and `/actuator/metrics` scraped by Prometheus. Grafana dashboards chart latency and error rate, and an alert pages the on-call engineer when the 5xx rate stays above 2% for 5 minutes."]]},{"id":2826,"category":"Production Scenarios","difficulty":"Senior","question":"How would you design invoice generation in a transactional system?","answer":"For invoice generation, I would first validate the customer and order and verify that the order is in a state where invoicing is allowed. Then I would start a database transaction and create the invoice, invoice items and required order-state changes as one atomic operation. If any database operation fails, I would roll back the transaction.","highlights":[],"body":[["h","Strong senior-level answer"],["quote","I would also make the API idempotent because the client may retry due to network failures. A unique database constraint or idempotency key can prevent duplicate invoices."],["quote","I would keep external operations such as PDF generation, email or notifications outside the database transaction. After the invoice transaction commits, I would publish an event or create a background job for PDF generation and notification. This keeps the database transaction short while allowing those operations to retry independently."],["quote","Finally, I would add structured logging, request IDs, monitoring and clear error handling so that failures can be traced in production."],["h","Also worth knowing"],["p","This is a very common senior-level scenario because it tests more than coding."],["p","The important question is:"],["quote","How do you guarantee data consistency if something fails halfway through?"],["h","Step 1: Understand the entities"],["p","Example:"],["code","text","Customer\nOrder\nOrderItem\nInvoice\nInvoiceItem\nPayment"],["p","Relationship:"],["code","text","Customer\n   ↓\nOrder\n   ↓\nOrder Items\n   ↓\nInvoice\n   ↓\nInvoice Items"],["h","Step 2: Invoice creation flow"],["code","text","Client\n  ↓\nPOST /orders/{orderId}/invoice\n  ↓\nValidate request\n  ↓\nAuthenticate user\n  ↓\nAuthorize operation\n  ↓\nBegin DB transaction\n  ↓\nValidate order\n  ↓\nValidate order status\n  ↓\nCreate invoice\n  ↓\nCreate invoice items\n  ↓\nCalculate totals\n  ↓\nCommit transaction\n  ↓\nReturn invoice"]],"realWorld":[["p","**Why it matters.** Invoice generation is a classic scenario that combines transactions, idempotency, concurrency and failure handling."],["p","**Example.** When a user clicks 'Generate invoice', the service validates the order, opens a transaction, creates the invoice with a unique invoice number, marks the order as invoiced and commits. PDF creation happens afterward through a retryable job, so a PDF failure never leaves a half-created invoice."]]},{"id":2827,"category":"Production Scenarios","difficulty":"Senior","question":"What if PDF generation fails?","answer":"Don't necessarily roll back the invoice itself. The invoice may already be valid business data.","highlights":[],"body":[["p","Use a separate asynchronous workflow:"],["code","text","Invoice transaction succeeds\n          ↓\nInvoiceCreated event\n          ↓\nMessage queue\n          ↓\nPDF generation worker\n          ↓\nPDF storage"],["p","If PDF generation fails:"],["code","text","Retry\n  ↓\nRetry\n  ↓\nDead-letter queue / manual intervention"],["p","The invoice remains available."],["h","Interview answer"],["quote","I would separate the transactional creation of invoice data from non-transactional operations such as PDF generation or email. The database transaction guarantees invoice consistency, while asynchronous processing handles document generation and notifications."]],"realWorld":[["p","**Why it matters.** Separate the critical data change from slow, failure-prone side effects such as PDF generation."],["p","**Example.** The invoice record is committed first with status `PDF_PENDING`. A worker generates the PDF and uploads it to storage; on failure it retries with backoff and finally flags the invoice for manual review, while the user sees 'Invoice created, PDF is being prepared'."]]},{"id":2828,"category":"Production Scenarios","difficulty":"Senior","question":"What if two users generate the invoice simultaneously?","answer":"I would protect the operation at the database level instead of relying only on frontend checks. A unique constraint can prevent duplicate invoices, while optimistic locking or appropriate transaction handling can protect against concurrent updates.","highlights":["Unique database constraint","Optimistic locking/versioning","Appropriate transaction isolation"],"body":[["p","This is a concurrency problem."],["p","Example:"],["code","text","User A → Generate invoice\nUser B → Generate invoice\n             ↓\n        Both see order as OPEN"],["p","Both could attempt to create an invoice."],["p","Possible solutions:"],["ul",["Unique database constraint","Optimistic locking/versioning","Appropriate transaction isolation","Pessimistic locking when justified"]],["h","Optimistic locking concept"],["code","text","Order version = 5\n\nUser A reads version 5\nUser B reads version 5\n\nUser A updates → version 6\nUser B attempts update using version 5\n        ↓\nConflict"],["p","User B must reload the latest state."]],"realWorld":[["p","**Why it matters.** Two users acting on the same record at once is a race condition; locking or unique constraints decide who wins."],["p","**Example.** Two finance users click 'Generate invoice' for the same order within a second. A unique constraint on `order_id` (or optimistic locking with a version column) lets one succeed while the other receives 'Invoice already exists' instead of creating a duplicate."]]},{"id":2829,"category":"Production Scenarios","difficulty":"Mid","question":"How would you structure the invoice APIs?","answer":"Clear, resource-oriented endpoints make an invoice system easy to integrate and evolve.","highlights":[],"body":[["p","Example:"],["code","http","POST /api/orders/{orderId}/invoices\nGET  /api/invoices/{invoiceId}\nGET  /api/orders/{orderId}/invoices\nPOST /api/invoices/{invoiceId}/cancel"],["h","Example request"],["code","http","POST /api/orders/ORD123/invoices\nIdempotency-Key: INV-REQUEST-123"],["p","Response:"],["code","json","{\n  \"invoiceId\": \"INV1001\",\n  \"orderId\": \"ORD123\",\n  \"status\": \"GENERATED\",\n  \"total\": 12500\n}"]],"realWorld":[["p","**Why it matters.** Clear, resource-oriented endpoints make an invoice system easy to integrate and evolve."],["p","**Example.** `POST /orders/{id}/invoices` creates one (idempotent), `GET /invoices/{id}` fetches it, `GET /invoices/{id}/pdf` downloads the file and `GET /invoices?customerId=...&page=1` lists them. Errors return `409 Conflict` for duplicates and `422` for invalid orders."]]},{"id":2830,"category":"Java","difficulty":"Junior","question":"What is the difference between JDK, JRE, and JVM?","answer":"Interview point: Java is platform-independent because Java code is compiled into bytecode, and a JVM implementation exists for different operating systems.","highlights":["JVM (Java Virtual Machine) runs Java bytecode.","JRE (Java Runtime Environment) contains the JVM plus libraries required to run Java applications.","JDK (Java Development Kit) contains the JRE plus development tools such as javac, debugger, and jar."],"body":[["p","**Simple interview answer:**"],["ul",["**JVM (Java Virtual Machine)** runs Java bytecode.","**JRE (Java Runtime Environment)** contains the JVM plus libraries required to run Java applications.","**JDK (Java Development Kit)** contains the JRE plus development tools such as `javac`, debugger, and `jar`."]],["h","Flow"],["code","text","Java source code (.java)\n        |\n        | javac\n        v\nBytecode (.class)\n        |\n        | JVM\n        v\nMachine code"],["h","Example"],["code","java","public class InsuranceApp {\n    public static void main(String[] args) {\n        System.out.println(\"Insurance policy created\");\n    }\n}"],["p","Compile:"],["code","bash","javac InsuranceApp.java"],["p","Run:"],["code","bash","java InsuranceApp"],["p","**Real-world examples:**"],["ul",["**Insurance:** JVM runs policy and claims-processing services.","**Banking:** JVM runs account, payment, and transaction services.","**E-commerce:** JVM runs product, cart, order, and payment services."]]],"realWorld":[["p","**Why it matters.** Interviewers use this to check you understand compilation, bytecode and platform independence, not just acronyms."],["p","**Example.** A claims service is built once into a `.jar` containing bytecode and runs unchanged on a developer's Windows laptop, a Linux CI agent and a production container, because each has a JVM. Installing only a JRE on a server is enough to run it; the JDK is needed to build it."]]},{"id":2831,"category":"Java","difficulty":"Junior","question":"Explain OOP principles in Java","answer":"Encapsulation means keeping data private and accessing it through controlled methods. Here, balance cannot be directly modified from outside the class.","highlights":["Encapsulation","Inheritance","Polymorphism"],"body":[["p","The four main OOP principles are:"],["ol",["Encapsulation","Inheritance","Polymorphism","Abstraction"]],["h","2.1 Encapsulation"],["code","java","public class BankAccount {\n\n    private double balance;\n\n    public double getBalance() {\n        return balance;\n    }\n\n    public void deposit(double amount) {\n        if (amount > 0) {\n            balance += amount;\n        }\n    }\n}"],["p","**Banking example:** A bank account should not allow arbitrary code to set the balance to `1,000,000`. Deposits and withdrawals should go through controlled business methods."],["h","2.2 Inheritance"],["p","Inheritance allows one class to reuse properties and behavior of another class."],["code","java","class InsurancePolicy {\n    void calculatePremium() {\n        System.out.println(\"Calculating premium\");\n    }\n}\n\nclass MotorPolicy extends InsurancePolicy {\n    void calculateMotorPremium() {\n        System.out.println(\"Motor premium\");\n    }\n}"],["p","`MotorPolicy` inherits behavior from `InsurancePolicy`."],["p","**Insurance example:**"],["code","text","InsurancePolicy\n      |\n      +-- MotorPolicy\n      +-- HealthPolicy\n      +-- LifePolicy"],["h","2.3 Polymorphism"],["p","Polymorphism means the same method/interface can behave differently depending on the object."],["code","java","interface Payment {\n    void pay(double amount);\n}\n\nclass CreditCardPayment implements Payment {\n    public void pay(double amount) {\n        System.out.println(\"Paid by credit card: \" + amount);\n    }\n}\n\nclass UpiPayment implements Payment {\n    public void pay(double amount) {\n        System.out.println(\"Paid using UPI: \" + amount);\n    }\n}"],["p","Usage:"],["code","java","Payment payment = new UpiPayment();\npayment.pay(5000);"],["p","The same `pay()` contract can have different implementations."],["p","**E-commerce example:** Checkout can support UPI, card, net banking, and wallet payments without changing the checkout business logic."],["h","2.4 Abstraction"],["p","Abstraction hides implementation details and exposes only what the caller needs."],["code","java","interface ClaimService {\n    void submitClaim(String policyNumber);\n}"],["p","Implementation:"],["code","java","class MotorClaimService implements ClaimService {\n\n    @Override\n    public void submitClaim(String policyNumber) {\n        // Validate policy\n        // Check documents\n        // Create claim\n        System.out.println(\"Claim submitted\");\n    }\n}"],["p","The caller only knows `submitClaim()`, not all internal processing."]],"realWorld":[["p","**Why it matters.** The four OOP principles are design tools. A good answer shows each with a practical reason, not a textbook definition."],["p","**Example.** A banking `Account` hides its balance (encapsulation) and exposes `deposit()` with validation. `SavingsAccount` and `CurrentAccount` extend it (inheritance), `calculateInterest()` behaves differently per type (polymorphism), and callers depend on an `InterestCalculator` interface (abstraction)."]]},{"id":2832,"category":"Java","difficulty":"Mid","question":"What is Multithreading and Synchronization?","answer":"Multithreading means executing multiple tasks concurrently within a process.","highlights":[],"body":[["h","Multithreading"],["code","java","class PaymentTask implements Runnable {\n\n    @Override\n    public void run() {\n        System.out.println(\"Processing payment...\");\n    }\n}\n\npublic class App {\n    public static void main(String[] args) {\n        Thread thread = new Thread(new PaymentTask());\n        thread.start();\n    }\n}"],["p","A better approach in real applications is usually an executor:"],["code","java","ExecutorService executor = Executors.newFixedThreadPool(10);\n\nexecutor.submit(() -> {\n    System.out.println(\"Processing order\");\n});\n\nexecutor.shutdown();"],["h","Synchronization"],["p","Synchronization protects shared data from concurrent access problems."],["code","java","class Account {\n\n    private double balance;\n\n    public synchronized void withdraw(double amount) {\n        if (balance >= amount) {\n            balance -= amount;\n        }\n    }\n}"],["p","Without proper synchronization, two threads could read the same balance and both perform a withdrawal."],["p","**Banking example:**"],["code","text","Initial balance = ₹10,000\n\nThread A -> withdraw ₹7,000\nThread B -> withdraw ₹7,000\n\nWithout proper concurrency control:\nBoth may see ₹10,000 and incorrectly approve."],["p","In production banking systems, database transactions, row locks, optimistic locking, and carefully designed distributed transaction strategies are also important."]],"realWorld":[["p","**Why it matters.** Concurrency bugs are rare but costly. Interviewers want to see you can explain race conditions and the tools to prevent them."],["p","**Example.** Two threads processing payments both read a wallet balance of 1,000 and each deduct 800, producing a wrong result. Using `synchronized`, `AtomicLong`, `ReentrantLock` or a database transaction with locking makes the check-and-update step atomic."]]},{"id":2833,"category":"Java","difficulty":"Senior","question":"Java memory: JVM memory areas and the Java Memory Model","answer":"The Java Memory Model defines how Java threads interact with memory. Each thread can work with values in its own working memory/cache, so simply changing a shared variable does not always guarantee that another thread immediately sees the change.","highlights":["Visibility","Atomicity","Happens-before relationships"],"body":[["p","It explains concepts such as:"],["ul",["Visibility","Atomicity","Ordering","Happens-before relationships"]],["h","volatile"],["code","java","class Service {\n\n    private volatile boolean running = true;\n\n    void stop() {\n        running = false;\n    }\n\n    void process() {\n        while (running) {\n            // process\n        }\n    }\n}"],["p","`volatile` helps guarantee visibility of changes to the variable between threads."],["h","synchronized"],["code","java","public synchronized void updateStatus() {\n    status = \"COMPLETED\";\n}"],["p","Synchronization provides mutual exclusion and establishes memory visibility guarantees."],["p","**Real-world example:** A banking transaction-processing service may use thread-safe mechanisms so that transaction status changes are correctly observed by worker threads."],["p","**Interview answer:** \"The Java Memory Model defines how shared variables are stored, accessed, and made visible between threads. It provides rules around visibility, atomicity, ordering, and happens-before relationships.\""],["h","Also worth knowing"],["p","The JVM divides memory into several important areas."],["code","text","JVM\n│\n├── Heap\n│   ├── Young Generation\n│   └── Old Generation\n│\n├── Stack\n│\n├── Metaspace\n│\n├── PC Register\n│\n└── Native Method Stack"],["h","Heap"],["p","Objects are generally created in the heap."],["code","java","Customer customer = new Customer();"],["p","The `Customer` object is stored in heap memory."],["h","Stack"],["p","Each thread has its own stack."],["p","Local variables and method call information are stored there."],["code","java","public void calculate() {\n\n    int amount = 100;\n\n    process(amount);\n}"],["h","Metaspace"],["p","Stores class metadata."],["p","For example:"],["code","text","Class information\nMethod metadata\nRuntime constant information"],["h","PC Register"],["p","Each thread has a program counter that tracks the current instruction."]],"realWorld":[["p","**Why it matters.** The JVM memory model and runtime areas explain performance issues, leaks and visibility bugs between threads."],["p","**Example.** A service gets `OutOfMemoryError: Java heap space` because a static `Map` caches every customer forever (heap leak), while another incident is `StackOverflowError` from runaway recursion (stack). A flag written by one thread but never seen by another is fixed with `volatile`."]]},{"id":2834,"category":"Java","difficulty":"Senior","question":"Garbage Collection","answer":"Garbage Collection automatically removes objects that are no longer reachable. The object may become eligible for garbage collection if nothing else references it.","highlights":["Do not say:","GC immediately deletes unused objects.","When an object becomes unreachable, it becomes eligible for garbage collection. The JVM decides when and how the collector runs."],"body":[["p","Example:"],["code","java","Customer customer = new Customer();\n\ncustomer = null;"],["h","Simplified lifecycle"],["code","text","New Object\n    ↓\nYoung Generation\n    ↓\nSurvives GC\n    ↓\nOld Generation\n    ↓\nEventually collected"],["h","Common collectors"],["p","Modern Java provides collectors such as:"],["ul",["G1 GC","ZGC","Shenandoah","Serial GC","Parallel GC"]],["h","Important interview point"],["p","Do not say:"],["quote","GC immediately deletes unused objects."],["p","Better:"],["quote","When an object becomes unreachable, it becomes eligible for garbage collection. The JVM decides when and how the collector runs."]],"realWorld":[["h","Production example"],["p","If an application has:"],["code","text","High memory\n+\nFrequent GC\n+\nLong GC pauses"],["p","Investigate:"],["ul",["heap sizing","allocation rate","object retention","memory leaks","GC logs","heap dump"]],["p","**In practice.** A trading application suffered 2-second pauses. GC logs showed long stop-the-world pauses from a large heap; switching to G1/ZGC, reducing allocation in hot paths and right-sizing the heap cut pauses to a few milliseconds."]]},{"id":2835,"category":"Java","difficulty":"Senior","question":"HashMap vs ConcurrentHashMap (vs ConcurrentSkipListMap)","answer":"HashMap is not thread-safe. ConcurrentHashMap provides concurrent access with good performance. ConcurrentSkipListMap is also thread-safe but maintains sorted key order and provides O(log N) operations.","highlights":["thread safety","sorted keys","range queries"],"body":[["table",["Feature","HashMap","ConcurrentHashMap","ConcurrentSkipListMap"],[["Thread-safe","No","Yes","Yes"],["Ordering","No","No","Sorted"],["Average lookup","O(1)","O(1)","O(log N)"],["Null keys","Yes","No","No"],["Best use","Single-threaded","Concurrent access","Sorted concurrent data"]]],["h","HashMap"],["code","java","Map<String, Integer> map = new HashMap<>();"],["p","Use when there is no concurrent modification."],["h","ConcurrentHashMap"],["code","java","Map<String, Integer> map =\n    new ConcurrentHashMap<>();"],["p","Useful for shared data accessed by multiple threads."],["p","Example:"],["code","text","Multiple payment-processing threads\n              ↓\n      ConcurrentHashMap"],["h","ConcurrentSkipListMap"],["code","java","ConcurrentSkipListMap<Integer, String> map =\n    new ConcurrentSkipListMap<>();"],["p","Useful when you need:"],["ul",["thread safety","sorted keys","range queries"]],["h","Also worth knowing"],["table",["Feature","HashMap","ConcurrentHashMap"],[["Thread-safe","No","Yes"],["Null key/value","Allows null","Does not allow null keys/values"],["Concurrent access","Unsafe for concurrent modification","Designed for concurrent access"],["Performance","Good for single-threaded use","Good for concurrent applications"],["Typical use","Local/non-shared data","Shared data across threads"]]],["h","HashMap"],["code","java","Map<String, Integer> products = new HashMap<>();\n\nproducts.put(\"LAPTOP\", 10);\nproducts.put(\"PHONE\", 20);"],["h","ConcurrentHashMap"],["code","java","Map<String, Integer> inventory = new ConcurrentHashMap<>();\n\ninventory.put(\"LAPTOP\", 10);\ninventory.put(\"PHONE\", 20);"],["p","**E-commerce example:** Multiple order-processing threads may update/read inventory concurrently. A `ConcurrentHashMap` can be useful for in-memory concurrent access."],["p","**Important:** `ConcurrentHashMap` does not automatically make an entire business operation atomic."],["p","For example:"],["code","java","if (inventory.get(\"LAPTOP\") > 0) {\n    inventory.put(\"LAPTOP\", inventory.get(\"LAPTOP\") - 1);\n}"],["p","The read-check-write sequence can still have a race condition."],["p","Prefer atomic operations where appropriate:"],["code","java","inventory.computeIfPresent(\n    \"LAPTOP\",\n    (key, quantity) -> quantity > 0 ? quantity - 1 : quantity\n);"]],"realWorld":[["p","**Why it matters.** Choosing the right map affects correctness under concurrency and performance."],["p","**Example.** A shared `HashMap` of live sessions updated by many request threads can corrupt or loop forever. Switching to `ConcurrentHashMap` makes updates safe with fine-grained locking, and `ConcurrentSkipListMap` is used when you need a sorted, thread-safe map such as a time-ordered leaderboard."]]},{"id":2836,"category":"Java","difficulty":"Mid","question":"What is Stream API?","answer":"The Stream API provides a declarative way to process collections.","highlights":["distinct()","collect()","forEach()"],"body":[["p","Example:"],["code","java","List<Integer> amounts = List.of(1000, 2500, 5000, 7000);\n\nList<Integer> largeAmounts = amounts.stream()\n        .filter(amount -> amount > 3000)\n        .toList();"],["p","Common operations:"],["ul",["`filter()`","`map()`","`sorted()`","`distinct()`","`limit()`","`collect()`","`reduce()`","`forEach()`"]]],"realWorld":[["h","Insurance example"],["p","Find high-value claims:"],["code","java","List<Claim> highValueClaims = claims.stream()\n        .filter(claim -> claim.getAmount() > 100000)\n        .toList();"],["h","Banking example"],["p","Calculate total successful transactions:"],["code","java","double total = transactions.stream()\n        .filter(Transaction::isSuccessful)\n        .mapToDouble(Transaction::getAmount)\n        .sum();"],["h","E-commerce example"],["p","Get product names below ₹1,000:"],["code","java","List<String> products = productList.stream()\n        .filter(p -> p.getPrice() < 1000)\n        .map(Product::getName)\n        .toList();"],["p","**Interview point:** Streams do not store data. They provide a pipeline for processing data from a source such as a collection."]]},{"id":2837,"category":"Java","difficulty":"Mid","question":"What are Functional Interfaces and Lambda Expressions?","answer":"A functional interface has exactly one abstract method.","highlights":[],"body":[["h","Functional Interface"],["code","java","@FunctionalInterface\ninterface DiscountCalculator {\n    double calculate(double price);\n}"],["h","Lambda expression"],["p","A lambda provides an implementation of a functional interface."],["code","java","DiscountCalculator calculator =\n        price -> price * 0.90;\n\nSystem.out.println(calculator.calculate(1000));"],["p","Common built-in functional interfaces:"],["code","text","Predicate<T>  -> T -> boolean\nFunction<T,R> -> T -> R\nConsumer<T>   -> T -> void\nSupplier<T>   -> () -> T"]],"realWorld":[["h","E-commerce example"],["code","java","Predicate<Product> expensiveProduct =\n        product -> product.getPrice() > 50000;\n\nList<Product> expensiveProducts =\n        products.stream()\n                .filter(expensiveProduct)\n                .toList();"],["p","**Interview answer:** \"A functional interface has exactly one abstract method. Lambda expressions provide a concise implementation of that method and are commonly used with Streams and functional programming.\""],["p","**In practice.** Instead of a custom comparator class, `orders.sort(Comparator.comparing(Order::getTotal))` or `list.stream().filter(o -> o.isPaid()).map(Order::getId)` uses functional interfaces (`Comparator`, `Predicate`, `Function`) to express intent concisely and compose behaviour."]]},{"id":2838,"category":"Java","difficulty":"Mid","question":"Exception handling in Java and global exception handling in Spring Boot","answer":"Consistent exception handling gives clients predictable errors and prevents leaking stack traces.","highlights":["Do not expose:","to the client.","Log technical details internally."],"body":[["p","The basic hierarchy is:"],["code","text","Throwable\n├── Error\n│   ├── OutOfMemoryError\n│   └── StackOverflowError\n│\n└── Exception\n    ├── RuntimeException\n    │   ├── NullPointerException\n    │   ├── IllegalArgumentException\n    │   └── IndexOutOfBoundsException\n    │\n    └── Other checked exceptions\n        ├── IOException\n        └── SQLException"],["h","Checked exception"],["code","java","public void readFile() throws IOException {\n    Files.readString(Path.of(\"data.txt\"));\n}"],["h","Unchecked exception"],["p","Usually subclasses of `RuntimeException`."],["code","java","public void validateAmount(double amount) {\n    if (amount <= 0) {\n        throw new IllegalArgumentException(\"Amount must be positive\");\n    }\n}"],["h","Spring Boot REST exception handling"],["code","java","@RestControllerAdvice\npublic class GlobalExceptionHandler {\n\n    @ExceptionHandler(ResourceNotFoundException.class)\n    public ResponseEntity<String> handleNotFound(\n            ResourceNotFoundException ex) {\n\n        return ResponseEntity\n                .status(HttpStatus.NOT_FOUND)\n                .body(ex.getMessage());\n    }\n}"],["p","**Insurance example:** If a policy number does not exist, return `404 NOT_FOUND` instead of exposing a Java stack trace."],["h","Also worth knowing"],["p","Use `@RestControllerAdvice`."],["code","java","@RestControllerAdvice\npublic class GlobalExceptionHandler {\n\n    @ExceptionHandler(ResourceNotFoundException.class)\n    public ResponseEntity<ApiError> handleNotFound(\n            ResourceNotFoundException ex) {\n\n        ApiError error = new ApiError(\n            404,\n            ex.getMessage()\n        );\n\n        return ResponseEntity\n            .status(HttpStatus.NOT_FOUND)\n            .body(error);\n    }\n\n    @ExceptionHandler(Exception.class)\n    public ResponseEntity<ApiError> handleGeneric(\n            Exception ex) {\n\n        ApiError error = new ApiError(\n            500,\n            \"Internal server error\"\n        );\n\n        return ResponseEntity\n            .status(HttpStatus.INTERNAL_SERVER_ERROR)\n            .body(error);\n    }\n}"],["h","Good API response"],["code","json","{\n  \"status\": 404,\n  \"message\": \"Policy not found\",\n  \"timestamp\": \"2026-10-06T10:30:00Z\",\n  \"path\": \"/api/policies/123\"\n}"],["h","Important production practice"],["p","Do not expose:"],["code","text","Stack trace\nDatabase credentials\nInternal class names\nSQL details"],["p","to the client."],["p","Log technical details internally."]],"realWorld":[["p","**Why it matters.** Consistent exception handling gives clients predictable errors and prevents leaking stack traces."],["p","**Example.** A service throws `PolicyNotFoundException`. A `@RestControllerAdvice` maps it to HTTP 404 with a JSON body `{code, message, traceId}`, validation errors to 400, and unexpected exceptions to a generic 500 while the full stack trace is logged only on the server."]]},{"id":2839,"category":"Java","difficulty":"Senior","question":"CompletableFuture","answer":"CompletableFuture is used for asynchronous and non-blocking workflows.","highlights":["CompletableFuture does not automatically make CPU work faster.","It helps when work can be performed asynchronously or concurrently, especially I/O-bound work."],"body":[["h","Sequential approach"],["code","java","User user = userService.getUser();\nOrders orders = orderService.getOrders(user.getId());"],["p","The second call waits for the first."],["h","CompletableFuture"],["code","java","CompletableFuture<User> userFuture =\n    userService.getUserAsync();\n\nCompletableFuture<Orders> ordersFuture =\n    userFuture.thenCompose(\n        user -> orderService.getOrdersAsync(user.getId())\n    );"],["h","Parallel operations"],["p","Suppose an e-commerce product page needs:"],["code","text","Product details\nReviews\nRecommendations"],["p","These calls can happen in parallel."],["code","java","CompletableFuture<Product> product =\n    productService.getProductAsync(id);\n\nCompletableFuture<List<Review>> reviews =\n    reviewService.getReviewsAsync(id);\n\nCompletableFuture<List<Product>> recommendations =\n    recommendationService.getRecommendationsAsync(id);\n\nCompletableFuture.allOf(\n    product,\n    reviews,\n    recommendations\n).join();"],["h","Important point"],["p","CompletableFuture does not automatically make CPU work faster."],["p","It helps when work can be performed asynchronously or concurrently, especially I/O-bound work."],["h","Interview answer"],["quote","CompletableFuture helps compose asynchronous operations without blocking the current thread. For independent remote calls such as product, review and recommendation services, I can execute them concurrently and reduce overall response time."]],"realWorld":[["p","**Why it matters.** `CompletableFuture` composes asynchronous steps without blocking threads, which is key for calling several services in parallel."],["p","**Example.** A dashboard needs profile, orders and recommendations from three services. Calling them sequentially takes 900 ms; starting three `CompletableFuture.supplyAsync` tasks and combining them with `allOf` returns in roughly the slowest call, ~350 ms, with a fallback if one fails."]]},{"id":2840,"category":"Spring","difficulty":"Mid","question":"What is Spring Boot Auto Configuration?","answer":"Spring Boot can automatically configure common web application infrastructure. With suitable datasource configuration, Spring Boot can configure much of the JPA infrastructure automatically.","highlights":["Dependencies available on the classpath","Application properties","Existing beans"],"body":[["p","Spring Boot Auto Configuration automatically configures application components based on:"],["ul",["Dependencies available on the classpath","Application properties","Existing beans","Spring Boot configuration rules"]],["p","Example dependency:"],["code","xml","<dependency>\n    <groupId>org.springframework.boot</groupId>\n    <artifactId>spring-boot-starter-web</artifactId>\n</dependency>"],["p","Another example:"],["code","xml","<dependency>\n    <groupId>org.springframework.boot</groupId>\n    <artifactId>spring-boot-starter-data-jpa</artifactId>\n</dependency>"],["h","Interview answer"],["p","\"Spring Boot Auto Configuration reduces boilerplate by automatically configuring beans based on the application's classpath, properties, and existing configuration.\""]],"realWorld":[["p","**Why it matters.** Auto-configuration is what makes Spring Boot productive, so interviewers check that you know it is conditional and overridable."],["p","**Example.** Adding `spring-boot-starter-data-jpa` plus a PostgreSQL driver makes Boot create the `DataSource`, `EntityManager` and transaction manager automatically from `application.yml` properties. Defining your own `DataSource` bean tells Boot to back off. `--debug` prints which auto-configurations applied."]]},{"id":2841,"category":"Spring","difficulty":"Junior","question":"Difference between @Component, @Service, and @Repository","answer":"All three are Spring stereotype annotations used to register classes as Spring beans.","highlights":[],"body":[["h","@Component"],["p","Generic Spring-managed component."],["code","java","@Component\npublic class EmailValidator {\n}"],["h","@Service"],["p","Used for business/service logic."],["code","java","@Service\npublic class ClaimService {\n\n    public void processClaim() {\n        // business logic\n    }\n}"],["h","@Repository"],["p","Used for persistence/data-access logic."],["code","java","@Repository\npublic class PolicyRepository {\n}"],["p","With Spring Data JPA, repositories are commonly interfaces:"],["code","java","public interface PolicyRepository\n        extends JpaRepository<Policy, Long> {\n}"],["h","Typical architecture"],["code","text","Controller\n    |\n    v\nService\n    |\n    v\nRepository\n    |\n    v\nDatabase"],["p","**Insurance example:**"],["code","text","ClaimController\n      |\n      v\nClaimService\n      |\n      v\nClaimRepository\n      |\n      v\nInsurance DB"]],"realWorld":[["p","**Why it matters.** The stereotype annotations all register beans, but they communicate layer responsibility and `@Repository` adds exception translation."],["p","**Example.** In an insurance app, `PolicyController` handles HTTP, `@Service PolicyService` contains business rules, and `@Repository PolicyRepository` talks to the database. Any JPA exception from the repository is translated into Spring's `DataAccessException` hierarchy."]]},{"id":2842,"category":"Spring","difficulty":"Junior","question":"What is Dependency Injection (IoC)?","answer":"Inversion of Control means Spring manages object creation and dependencies instead of the application manually creating everything. Spring creates ClaimRepository and injects it into ClaimService.","highlights":["Makes dependencies explicit","Supports immutability with final","Makes unit testing easier"],"body":[["h","IoC"],["p","Without DI:"],["code","java","ClaimService service = new ClaimService();"],["p","With Spring DI:"],["code","java","@Service\npublic class ClaimService {\n\n    private final ClaimRepository repository;\n\n    public ClaimService(ClaimRepository repository) {\n        this.repository = repository;\n    }\n}"],["h","Why constructor injection?"],["p","It:"],["ul",["Makes dependencies explicit","Supports immutability with `final`","Makes unit testing easier","Avoids field injection problems"]],["h","Testing example"],["code","java","ClaimRepository mockRepository = mock(ClaimRepository.class);\n\nClaimService service =\n        new ClaimService(mockRepository);"],["p","**Interview answer:** \"Dependency Injection is a design pattern used by Spring's IoC container to provide objects with their required dependencies instead of the objects creating those dependencies themselves.\""]],"realWorld":[["p","**Why it matters.** Dependency injection makes code loosely coupled and testable, and constructor injection is the preferred style."],["p","**Example.** `OrderService` receives a `PaymentGateway` interface through its constructor. In production Spring injects `StripeGateway`; in a unit test you pass a mock, so tests never call the real payment provider."]]},{"id":2843,"category":"Spring","difficulty":"Mid","question":"What is Spring Security?","answer":"Spring Security provides authentication and authorization capabilities.","highlights":[],"body":[["h","Authentication"],["p","\"Who are you?\""],["p","Example:"],["code","text","Username + Password\n        |\n        v\nAuthentication"],["h","Authorization"],["p","\"What are you allowed to do?\""],["p","Example:"],["code","text","ROLE_CUSTOMER -> View own orders\nROLE_ADMIN    -> Manage products\nROLE_AGENT    -> Process insurance claims"],["p","Example configuration:"],["code","java","@Configuration\n@EnableWebSecurity\npublic class SecurityConfig {\n\n    @Bean\n    SecurityFilterChain securityFilterChain(HttpSecurity http)\n            throws Exception {\n\n        http\n            .authorizeHttpRequests(auth -> auth\n                .requestMatchers(\"/public/**\").permitAll()\n                .requestMatchers(\"/admin/**\").hasRole(\"ADMIN\")\n                .anyRequest().authenticated()\n            );\n\n        return http.build();\n    }\n}"],["p","**Banking example:**"],["code","text","/customer/accounts -> CUSTOMER\n/admin/accounts    -> ADMIN"],["p","A customer should not be able to access administrative endpoints just because they are authenticated."]],"realWorld":[["p","**Why it matters.** Spring Security protects applications through a filter chain handling authentication and authorisation."],["p","**Example.** An API uses a `SecurityFilterChain` bean: `/auth/**` is public, `/admin/**` requires `ROLE_ADMIN`, everything else needs a valid JWT. A custom filter extracts the token and populates the `SecurityContext`, and `@PreAuthorize` protects sensitive service methods."]]},{"id":2844,"category":"Spring","difficulty":"Mid","question":"How does REST API development work in Spring Boot?","answer":"This checks you can build a clean layered REST API: controller, service, repository, DTOs and validation.","highlights":[],"body":[["p","A typical REST API uses:"],["h","Controller"],["code","java","@RestController\n@RequestMapping(\"/api/policies\")\npublic class PolicyController {\n\n    private final PolicyService service;\n\n    public PolicyController(PolicyService service) {\n        this.service = service;\n    }\n\n    @GetMapping(\"/{id}\")\n    public PolicyDto getPolicy(@PathVariable Long id) {\n        return service.getPolicy(id);\n    }\n\n    @PostMapping\n    public PolicyDto createPolicy(\n            @RequestBody CreatePolicyRequest request) {\n\n        return service.createPolicy(request);\n    }\n}"],["h","Service"],["code","java","@Service\npublic class PolicyService {\n\n    private final PolicyRepository repository;\n\n    public PolicyService(PolicyRepository repository) {\n        this.repository = repository;\n    }\n\n    public PolicyDto getPolicy(Long id) {\n        Policy policy = repository.findById(id)\n                .orElseThrow(() ->\n                    new ResourceNotFoundException(\"Policy not found\"));\n\n        return new PolicyDto(\n                policy.getId(),\n                policy.getPolicyNumber()\n        );\n    }\n}"],["h","REST endpoints"],["code","text","GET    /api/policies/100\nPOST   /api/policies\nPUT    /api/policies/100\nDELETE /api/policies/100"],["p","**Insurance example:**"],["code","text","POST /api/policies\nGET  /api/policies/{id}\nPOST /api/claims\nGET  /api/claims/{id}"],["p","**Banking example:**"],["code","text","GET  /api/accounts/{id}\nPOST /api/transfers\nGET  /api/transactions"],["p","**E-commerce example:**"],["code","text","GET  /api/products\nPOST /api/orders\nGET  /api/orders/{id}"]],"realWorld":[["p","**Why it matters.** This checks you can build a clean layered REST API: controller, service, repository, DTOs and validation."],["p","**Example.** `POST /api/policies` accepts a `CreatePolicyRequest` DTO validated with `@Valid`, the controller delegates to `PolicyService`, which saves a `Policy` entity via `JpaRepository` and returns `201 Created` with a `Location` header and a `PolicyResponse` DTO, never exposing the entity directly."]]},{"id":2845,"category":"Spring","difficulty":"Mid","question":"What is JPA and Hibernate?","answer":"JPA (Jakarta Persistence) is a specification/API for object-relational persistence.","highlights":[],"body":[["h","Hibernate"],["p","Hibernate is a popular implementation of JPA."],["p","Simple relationship:"],["code","text","JPA\n  |\n  | specification\n  v\nHibernate\n  |\n  v\nDatabase"],["h","Entity example"],["code","java","@Entity\n@Table(name = \"policies\")\npublic class Policy {\n\n    @Id\n    @GeneratedValue(strategy = GenerationType.IDENTITY)\n    private Long id;\n\n    private String policyNumber;\n\n    private double premium;\n\n    // getters/setters\n}"],["p","Repository:"],["code","java","public interface PolicyRepository\n        extends JpaRepository<Policy, Long> {\n\n    Optional<Policy> findByPolicyNumber(String policyNumber);\n}"],["p","**Insurance example:** Java `Policy` objects are persisted into a `policies` database table."],["p","**Banking example:**"],["code","java","@Entity\npublic class Account {\n\n    @Id\n    private Long id;\n\n    private String accountNumber;\n\n    private BigDecimal balance;\n}"],["p","**Interview point:** JPA defines the persistence contract; Hibernate is one implementation that provides ORM functionality."]],"realWorld":[["p","**Why it matters.** JPA is the specification and Hibernate is the implementation. Understanding lazy loading and N+1 queries is what separates senior answers."],["p","**Example.** Loading 100 orders and then accessing each order's items fires 101 SQL queries (N+1). Using `JOIN FETCH`, an `@EntityGraph` or DTO projections reduces it to one query and cuts an API from 2 s to 200 ms."]]},{"id":2846,"category":"DSA","difficulty":"Mid","question":"LRU Cache","answer":"An LRU cache removes the item that has not been used for the longest time when the cache becomes full.","highlights":["HashMap for O(1) lookup","Doubly linked list for O(1) insertion/removal"],"body":[["h","What is an LRU Cache?"],["p","LRU means **Least Recently Used**."],["p","A common implementation uses:"],["ul",["`HashMap` for O(1) lookup","Doubly linked list for O(1) insertion/removal"]],["h","Example"],["p","Suppose cache capacity is 3:"],["code","text","put(1, A)\nput(2, B)\nput(3, C)\n\nCache:\n3 -> 2 -> 1\n\nget(1)\n\nCache:\n1 -> 3 -> 2\n\nput(4, D)\n\n2 is removed because it is least recently used."],["h","Java implementation"],["code","java","class LRUCache<K, V> {\n\n    private final int capacity;\n\n    private final Map<K, V> cache;\n\n    public LRUCache(int capacity) {\n        this.capacity = capacity;\n        this.cache = new LinkedHashMap<>(capacity, 0.75f, true) {\n            @Override\n            protected boolean removeEldestEntry(\n                    Map.Entry<K, V> eldest) {\n                return size() > LRUCache.this.capacity;\n            }\n        };\n    }\n\n    public V get(K key) {\n        return cache.get(key);\n    }\n\n    public void put(K key, V value) {\n        cache.put(key, value);\n    }\n}"],["h","Complexity"],["p","Operation       Complexity"],["h","Interview answer"],["quote","I would implement an LRU cache using a HashMap and doubly linked list so both get and put are O(1). In Java, LinkedHashMap can also provide a clean implementation because it maintains access order."]],"realWorld":[["h","Real-world example --- E-commerce"],["p","An e-commerce application frequently displays product details."],["p","Instead of querying the database every time:"],["code","text","User\n ↓\nProduct API\n ↓\nRedis / LRU Cache\n ↓\nDatabase"],["p","Frequently requested products remain in cache."],["p","**In practice.** An LRU cache is exactly how a product-detail cache behaves: when memory is full the least recently viewed product is evicted first. `HashMap` gives O(1) lookup and a doubly linked list keeps usage order, which is how Redis-like caches and browser caches are modelled."]]},{"id":2847,"category":"DSA","difficulty":"Mid","question":"Merge K Sorted Lists","answer":"I use a priority queue containing one node from each list. Every extraction gives me the smallest available element, so the total complexity is O(N log K), which is better than repeatedly scanning all K lists.","highlights":["Remove the smallest node.","Add it to the result.","Add that node's next element."],"body":[["h","Problem"],["p","You have K sorted linked lists and need to merge them into one sorted list."],["p","Example:"],["code","text","List 1: 1 → 4 → 7\nList 2: 2 → 5 → 8\nList 3: 3 → 6 → 9\n\nResult:\n1 → 2 → 3 → 4 → 5 → 6 → 7 → 8 → 9"],["h","Efficient approach"],["p","Use a **PriorityQueue / Min Heap**."],["p","Put the first element of every list into the heap."],["p","Then:"],["ol",["Remove the smallest node.","Add it to the result.","Add that node's next element.","Continue until the heap is empty."]],["h","Java"],["code","java","class ListNode {\n    int val;\n    ListNode next;\n\n    ListNode(int val) {\n        this.val = val;\n    }\n}\n\npublic ListNode mergeKLists(ListNode[] lists) {\n\n    PriorityQueue<ListNode> pq =\n        new PriorityQueue<>(Comparator.comparingInt(n -> n.val));\n\n    for (ListNode node : lists) {\n        if (node != null) {\n            pq.offer(node);\n        }\n    }\n\n    ListNode dummy = new ListNode(0);\n    ListNode current = dummy;\n\n    while (!pq.isEmpty()) {\n\n        ListNode node = pq.poll();\n\n        current.next = node;\n        current = current.next;\n\n        if (node.next != null) {\n            pq.offer(node.next);\n        }\n    }\n\n    return dummy.next;\n}"],["h","Complexity"],["p","If:"],["ul",["K = number of lists","N = total number of elements"]],["p","Then:"],["code","text","Time:  O(N log K)\nSpace: O(K)"]],"realWorld":[["h","Real-world example"],["p","Imagine an insurance company receives claim transactions from multiple systems:"],["code","text","Claim System A → sorted claims\nClaim System B → sorted claims\nClaim System C → sorted claims"],["p","The reporting system can merge them efficiently using a min heap."],["p","**In practice.** Merging K sorted lists mirrors merging sorted log files from K servers into one timeline. A min-heap always yields the next earliest entry, so the cost is O(N log K) instead of sorting everything again."]]},{"id":2848,"category":"DSA","difficulty":"Senior","question":"Design Add and Search Words Data Structure","answer":"This problem is commonly solved using a Trie.","highlights":["searching customer names","autocomplete","fraud-rule keywords"],"body":[["p","The data structure supports:"],["code","text","addWord(\"bad\")\naddWord(\"dad\")\naddWord(\"mad\")\n\nsearch(\"bad\") → true\nsearch(\".ad\") → true\nsearch(\"b..\") → true"],["p","`.` represents any character."],["h","Trie Node"],["code","java","class TrieNode {\n\n    TrieNode[] children = new TrieNode[26];\n\n    boolean isWord;\n}"],["h","Java implementation"],["code","java","class WordDictionary {\n\n    private final TrieNode root = new TrieNode();\n\n    public void addWord(String word) {\n\n        TrieNode current = root;\n\n        for (char c : word.toCharArray()) {\n\n            int index = c - 'a';\n\n            if (current.children[index] == null) {\n                current.children[index] = new TrieNode();\n            }\n\n            current = current.children[index];\n        }\n\n        current.isWord = true;\n    }\n\n    public boolean search(String word) {\n        return search(word, 0, root);\n    }\n\n    private boolean search(\n            String word,\n            int index,\n            TrieNode node) {\n\n        if (node == null) {\n            return false;\n        }\n\n        if (index == word.length()) {\n            return node.isWord;\n        }\n\n        char c = word.charAt(index);\n\n        if (c == '.') {\n\n            for (TrieNode child : node.children) {\n\n                if (child != null &&\n                    search(word, index + 1, child)) {\n\n                    return true;\n                }\n            }\n\n            return false;\n        }\n\n        return search(\n            word,\n            index + 1,\n            node.children[c - 'a']\n        );\n    }\n}"],["h","Complexity"],["p","For normal search:"],["code","text","O(L)"],["p","where L is word length."],["p","With `.` wildcard, worst case can branch significantly."]],"realWorld":[["h","Real-world example"],["p","A banking application can use a Trie for:"],["ul",["searching customer names","autocomplete","fraud-rule keywords","merchant search"]],["p","**In practice.** A trie powers autocomplete and spell-check: typing 'ban' walks three nodes and returns 'bank', 'banana', 'band' without scanning the full dictionary. The wildcard search variant handles patterns like `b.nk`."]]},{"id":2849,"category":"DSA","difficulty":"Mid","question":"Given an array and a target number, how would you find three values that sum to it efficiently?","answer":"I would sort the array first and then fix one element. For the remaining two elements, I would use two pointers from the left and right. If the sum is too small, I move the left pointer forward; if it is too large, I move the right pointer backward. This gives O(N²) time after sorting, instead of O(N³) for a brute-force solution.","highlights":[],"body":[["p","This is the classic **3Sum** problem."],["h","Example"],["p","Input:"],["code","text","[2, 7, 11, 15, 3, 6]"],["p","Target:"],["code","text","18"],["p","Possible answer:"],["code","text","2 + 7 + 9 = 18"],["p","If `9` isn't present, that combination doesn't work."],["p","Let's use:"],["code","text","[1, 2, 3, 4, 5, 10]\ntarget = 9"],["p","Answer:"],["code","text","1 + 3 + 5 = 9"],["h","Efficient approach: Sort + Two Pointers"],["p","First sort:"],["code","text","[1, 2, 3, 4, 5, 10]"],["p","Then:"],["code","text","for each i:\n\n    left = i + 1\n    right = n - 1\n\n    while left < right:\n\n        sum = arr[i] + arr[left] + arr[right]\n\n        if sum == target:\n            found\n\n        if sum < target:\n            left++\n\n        if sum > target:\n            right--"],["h","Java code"],["code","java","import java.util.Arrays;\n\npublic class ThreeSum {\n\n    public static boolean hasThreeSum(int[] nums, int target) {\n\n        Arrays.sort(nums);\n\n        for (int i = 0; i < nums.length - 2; i++) {\n\n            int left = i + 1;\n            int right = nums.length - 1;\n\n            while (left < right) {\n\n                long sum = (long) nums[i]\n                        + nums[left]\n                        + nums[right];\n\n                if (sum == target) {\n                    return true;\n                }\n\n                if (sum < target) {\n                    left++;\n                } else {\n                    right--;\n                }\n            }\n        }\n\n        return false;\n    }\n}"],["h","Complexity"],["p","Sorting:"],["code","text","O(N log N)"],["p","Two-pointer search:"],["code","text","O(N²)"],["p","Overall:"],["code","text","O(N²)"],["p","Extra space depends on the sorting implementation and whether you need to preserve the original array."],["h","Why two pointers work"],["p","Because the array is sorted:"],["code","text","1  2  3  4  5  10\n^              ^\nL              R"],["p","If the sum is too small:"],["code","text","sum < target"],["p","Move `L` right."],["p","If the sum is too large:"],["code","text","sum > target"],["p","Move `R` left."]],"realWorld":[["h","Real-world connection"],["p","This pattern isn't normally used directly for banking or insurance business logic, but the underlying skill—sorting, reducing search space, and selecting the right algorithm—is frequently tested in backend interviews."],["p","**In practice.** Three-sum style problems appear in reconciliation: finding three transactions that add up to a target amount. Sorting and two pointers solve it in O(n²) instead of the brute-force O(n³), which matters when the list has thousands of entries."]]},{"id":2850,"category":"DSA","difficulty":"Junior","question":"How to Explain Time and Space Complexity","answer":"Complexity analysis shows you can predict how code scales before it fails in production.","highlights":[],"body":[["p","Always identify:"],["code","text","Input size = N"],["h","Common complexities"],["p","Complexity   Example"],["h","Interview example"],["p","Instead of saying:"],["quote","This code is fast."],["p","Say:"],["quote","The algorithm takes O(N log N) time and O(N) additional space because we process N elements and use an auxiliary data structure."]],"realWorld":[["p","**Why it matters.** Complexity analysis shows you can predict how code scales before it fails in production."],["p","**Example.** Checking duplicates in a list of 1 million customer ids with nested loops is O(n²) and effectively never finishes, while putting ids in a `HashSet` is O(n) time with O(n) extra memory. State the trade-off: faster time for more space."]]},{"id":2851,"category":"DSA","difficulty":"Senior","question":"What Happens With 10 Million Records?","answer":"Never assume that an algorithm that works for 10,000 records will automatically work for 10 million.","highlights":["pagination","projections","batch processing"],"body":[["p","Check:"],["h","1. Time complexity"],["p","An O(N²) algorithm becomes dangerous."],["code","text","10 million²"],["p","is enormous."],["p","Prefer:"],["code","text","O(N)\nO(N log N)"],["p","where possible."],["h","2. Memory"],["p","Avoid loading everything into memory."],["p","Bad:"],["code","java","List<Order> orders = repository.findAll();"],["p","Better:"],["code","text","Database\n ↓\nPagination\n ↓\nProcess batch\n ↓\nRelease memory\n ↓\nNext batch"],["h","3. Database"],["p","Use:"],["ul",["indexes","pagination","projections","batch processing","query optimization"]],["h","4. Distributed processing"],["p","For huge datasets:"],["code","text","Kafka\n ↓\nConsumer Workers\n ↓\nBatch Processing\n ↓\nDatabase"],["h","Interview answer"],["quote","For 10 million records, I would first check algorithmic complexity, memory usage, database query plans and network calls. I would avoid loading the complete dataset into memory and use pagination, streaming or batch processing."]],"realWorld":[["p","**Why it matters.** Interviewers ask this to see whether you think about memory, database load and distribution when data grows beyond a laptop."],["p","**Example.** Processing 10 million transactions: do not load them all into memory. Read in batches or stream with a database cursor, aggregate in SQL where possible, use indexes, and for very large jobs split work across workers (Spark/Kafka consumers) and checkpoint progress."]]},{"id":2852,"category":"DSA","difficulty":"Junior","question":"Java Coding Interview Strategy","answer":"A calm, repeatable strategy matters as much as the final code in a coding round.","highlights":[],"body":[["p","When given a coding problem:"],["h","Step 1"],["p","Clarify input."],["h","Step 2"],["p","Give brute force solution."],["h","Step 3"],["p","Explain why it is slow."],["h","Step 4"],["p","Optimize."],["h","Step 5"],["p","Write code."],["h","Step 6"],["p","Test edge cases."],["h","Step 7"],["p","Explain complexity."],["h","Step 8"],["p","Discuss large-scale behavior."],["h","Example"],["p","For Two Sum:"],["p","Brute force:"],["code","text","O(N²)"],["p","Optimized:"],["code","text","HashMap\nO(N)"],["h","Always test"],["code","text","Empty input\nSingle element\nDuplicates\nNegative numbers\nLarge input\nNull values where applicable\nAlready sorted input"]],"realWorld":[["p","**Why it matters.** A calm, repeatable strategy matters as much as the final code in a coding round."],["p","**Example.** Given 'merge K sorted lists', restate the problem, ask about constraints, give a brute-force idea, improve it with a min-heap, state complexity O(N log K), code carefully, then test with empty lists and duplicates before the interviewer asks."]]},{"id":2853,"category":"React Native","difficulty":"Mid","question":"Why does a screen re-render even when props look unchanged?","answer":"A component can re-render even when the displayed prop values appear unchanged.","highlights":["Don't automatically add useMemo, useCallback, or React.memo everywhere. They also have overhead and complexity.","Its own state changed","A parent rendered"],"body":[["p","One major reason is **reference identity**."],["h","Example"],["code","js","const user = {\n  name: \"Gopi\"\n};\n\n<Profile user={user} />"],["p","If a parent creates a new object every render:"],["code","js","<Profile\n  user={{\n    name: \"Gopi\"\n  }}\n/>"],["p","The values look the same, but:"],["code","js","{ name: \"Gopi\" } === { name: \"Gopi\" }\n// false"],["p","A new object reference is created."],["h","Function example"],["code","js","<Button onPress={() => saveUser()} />"],["p","A new function is created on every parent render."],["p","This can cause memoized children to re-render."],["h","Other causes"],["p","A React Native screen may render because:"],["ul",["Its own state changed","A parent rendered","Context value changed","Redux/store subscription changed","A prop has a new object/array/function reference","A hook updates state","Navigation state changed"]],["h","Optimization"],["p","For expensive children:"],["code","js","const Profile = React.memo(function Profile({ user }) {\n  return <Text>{user.name}</Text>;\n});"],["p","And stabilize references when appropriate:"],["code","js","const user = useMemo(() => ({\n  name: \"Gopi\"\n}), []);\n\nconst saveUser = useCallback(() => {\n  // save\n}, []);"],["h","Important warning"],["p","Don't automatically add `useMemo`, `useCallback`, or `React.memo` everywhere. They also have overhead and complexity."],["h","Interview answer"],["quote","Props can look unchanged by value but still be different by reference, especially objects, arrays, and functions. Re-renders can also come from state, context, store updates, parent renders, or navigation. I first profile the component tree and then use memoization or stable references only where they provide measurable benefit."]],"realWorld":[["h","Real-world example"],["p","A dashboard has:"],["code","text","Dashboard\n ├── Header\n ├── Search\n ├── Large document list\n └── Profile"],["p","If typing in Search causes the entire list to re-render, scrolling can become slower. The goal is to identify unnecessary rendering rather than blindly memoizing everything."],["p","**In practice.** A React Native list screen re-rendered on every keystroke because the parent created a new `onPress` function and a new style object on every render. Memoising row components, using `useCallback` and moving styles to `StyleSheet.create` stopped the needless re-renders."]]},{"id":2854,"category":"React Native","difficulty":"Mid","question":"Difference between useRef vs useState vs useMemo in React Native","answer":"useState is for values that drive UI and trigger renders. useRef stores mutable values across renders without triggering a render. useMemo caches the result of an expensive calculation. I choose the hook based on whether the value should update the UI and whether computation or reference stability actually needs optimization.","highlights":["Timer IDs","Previous values","Native component references"],"body":[["table",[],[["`useState`","Store UI state","Yes","Input value"],["`useRef`","Store mutable value/reference","No","Timer ID"],["`useMemo`","Cache calculated value","No by itself","Expensive calculation"]]],["h","useState"],["code","js","const [count, setCount] = useState(0);\n\nsetCount(count + 1);"],["p","Updating state schedules a re-render."],["p","Use it when the value affects the UI."],["h","useRef"],["code","js","const timerRef = useRef(null);\n\ntimerRef.current = setTimeout(() => {\n  console.log(\"Done\");\n}, 1000);"],["p","Changing:"],["code","js","timerRef.current"],["p","doesn't cause a render."],["p","Use it for:"],["ul",["Timer IDs","Previous values","Native component references","Mutable values that don't directly drive UI"]],["h","useMemo"],["code","js","const filteredUsers = useMemo(() => {\n  return users.filter(user =>\n    user.name.includes(search)\n  );\n}, [users, search]);"],["p","It caches the calculated result until dependencies change."]],"realWorld":[["h","Real-world example"],["p","A React Native document viewer has 5,000 records. Filtering/sorting a large collection repeatedly can be expensive."],["code","js","const filteredDocuments = useMemo(() => {\n  return documents\n    .filter(doc => doc.name.includes(search))\n    .sort((a, b) => a.name.localeCompare(b.name));\n}, [documents, search]);"],["p","But if the calculation is cheap, `useMemo` may provide little or no benefit."],["p","**In practice.** A timer id stored in `useRef` survives re-renders without triggering them, `useState` holds the selected tab that must update the UI, and `useMemo` caches an expensive filtered list so scrolling stays smooth on a mid-range Android phone."]]},{"id":2855,"category":"React Native","difficulty":"Mid","question":"How do you optimize FlatList for large datasets?","answer":"FlatList is designed for efficient rendering of large lists, but it still needs proper configuration.","highlights":["Layout work","JS thread time"],"body":[["h","Basic example"],["code","js","<FlatList\n  data={documents}\n  renderItem={renderDocument}\n  keyExtractor={item => item.id}\n/>"],["h","1. Keep renderItem stable"],["code","js","const renderDocument = useCallback(({ item }) => (\n  <DocumentRow document={item} />\n), []);"],["h","2. Memoize expensive row components"],["code","js","const DocumentRow = React.memo(({ document }) => {\n  return <Text>{document.name}</Text>;\n});"],["h","3. Use a stable key"],["code","js","keyExtractor={item => String(item.id)}"],["p","Avoid:"],["code","js","keyExtractor={(item, index) => String(index)}"],["p","when items can be inserted, removed, or reordered."],["h","4. Tune rendering window"],["code","js","<FlatList\n  initialNumToRender={10}\n  maxToRenderPerBatch={10}\n  windowSize={7}\n/>"],["p","These values should be tested against the actual device and row complexity."],["h","5. Avoid expensive work inside rows"],["p","Bad:"],["code","js","renderItem={({ item }) => {\n  const sorted = hugeArray.sort(expensiveFunction);\n  return <Row item={item} />;\n}}"],["p","Move expensive calculations outside the row or memoize them appropriately."],["h","6. Avoid unnecessary object creation"],["p","Be careful with:"],["code","js","renderItem={({ item }) => (\n  <Row style={{ margin: 10 }} item={item} />\n)}"],["p","when it interacts with memoized children. Stable styles and props can help when profiling shows a problem."],["h","Interview answer"],["quote","For large FlatLists, I focus on virtualization, stable keys, lightweight row components, memoized rows where useful, stable render callbacks, and avoiding expensive work during rendering. I also tune batch/window settings based on real-device profiling rather than blindly using one configuration."]],"realWorld":[["h","Real-world example"],["p","Suppose a document app has 5,000 documents."],["p","Rendering all 5,000 rows at once would waste:"],["ul",["Memory","CPU","Layout work","JS thread time"]],["p","`FlatList` renders a smaller window and virtualizes the list."],["p","**In practice.** A product feed with 5,000 items janked on low-end devices. Tuning `FlatList` (`getItemLayout`, `windowSize`, `removeClippedSubviews`, memoised `renderItem`, stable `keyExtractor`) and resizing images made scrolling smooth."]]},{"id":2856,"category":"React Native","difficulty":"Mid","question":"Why does blocking the JS thread freeze the UI?","answer":"React Native relies heavily on JavaScript for application logic. If the JS thread is occupied by expensive synchronous work, it cannot process other JavaScript-driven work efficiently.","highlights":["Huge loops","Large JSON parsing","Expensive sorting"],"body":[["h","Example"],["code","js","function processHugeData() {\n  for (let i = 0; i < 1e9; i++) {\n    // expensive work\n  }\n}\n\nprocessHugeData();"],["p","During this work:"],["code","text","User taps button\n       ↓\nJS thread is busy\n       ↓\nEvent processing is delayed\n       ↓\nAnimations/interactions can become unresponsive\n       ↓\nUI feels frozen"],["h","Common causes"],["ul",["Huge loops","Large JSON parsing","Expensive sorting","Complex filtering","Heavy synchronous transformations","Poor list rendering","Excessive JavaScript work during gestures/animations"]],["h","Better approach"],["p","Break work into smaller chunks, reduce the amount of data processed, move suitable work away from the JS thread, or use appropriate native/background mechanisms."],["p","For example, instead of processing everything in one synchronous operation, process smaller chunks:"],["code","js","function processInChunks(items, chunkSize = 100) {\n  let index = 0;\n\n  function processChunk() {\n    const chunk = items.slice(index, index + chunkSize);\n\n    chunk.forEach(processItem);\n\n    index += chunkSize;\n\n    if (index < items.length) {\n      setTimeout(processChunk, 0);\n    }\n  }\n\n  processChunk();\n}"],["p","This does not make the total work disappear, but it gives the runtime opportunities to process other work between chunks."],["h","Interview answer"],["quote","Blocking the JS thread means JavaScript cannot respond promptly to events, updates, and other JS-driven work. In React Native, heavy synchronous processing can therefore make the application feel frozen. I identify the expensive operation through profiling and then reduce, batch, memoize, or move the work to an appropriate background/native mechanism."]],"realWorld":[["h","Real-world example"],["p","A mobile app downloads thousands of documents and immediately performs expensive parsing and transformation on the JS thread. The user taps a button, but the interaction feels delayed."],["p","The solution is to reduce, batch, cache, or move expensive processing appropriately."]]},{"id":2857,"category":"React Native","difficulty":"Senior","question":"How do you debug performance issues on a real device?","answer":"For real-device performance problems, I reproduce with realistic data, profile instead of guessing, identify whether the bottleneck is JS, rendering, memory, network, or native work, make one targeted change at a time, and compare measurements on a release build.","highlights":["Is JS work slow?","Is rendering slow?","Is memory increasing?"],"body":[["p","I would not guess. I would measure."],["h","Step 1: Reproduce the issue"],["p","Use the same device class and realistic data."],["p","Example:"],["code","text","5,000 documents\nLarge images/PDFs\nSlow network\nOlder Android device"],["h","Step 2: Identify the type of problem"],["p","Ask:"],["ul",["Is JS work slow?","Is rendering slow?","Is memory increasing?","Is the network slow?","Is native code slow?","Is the list rendering too many rows?"]],["h","Step 3: Profile"],["p","Depending on the React Native version and setup, use available React Native/React profiling tools and platform tools."],["p","Look for:"],["ul",["Long JS tasks","Frequent renders","Expensive components","Memory growth","Slow network requests","Dropped frames"]],["h","Step 4: Inspect component rendering"],["p","Check whether:"],["code","text","Parent renders\n   ↓\n1,000 children render again"],["p","when only one child actually changed."],["h","Step 5: Test on release builds"],["p","Development mode can have different performance characteristics."],["p","Always validate important performance fixes in a production-like/release configuration."],["h","Step 6: Measure before and after"],["p","For example:"],["code","text","Before:\nScreen interaction = 800 ms\n\nAfter:\nScreen interaction = 120 ms"]],"realWorld":[["h","Real-world example"],["p","A document viewer becomes slow when 500 documents are selected."],["p","I would:"],["ol",["Reproduce with 500 documents.","Profile JS activity.","Check whether all document viewers mount at once.","Inspect memory.","Check rendering frequency.","Virtualize or limit simultaneous viewers.","Load documents lazily.","Measure again on a physical device."]]]},{"id":2858,"category":"Offline-First","difficulty":"Senior","question":"How would you design an offline-first mobile app?","answer":"Offline-first means the application remains useful even when the network is unavailable. The UI should not depend entirely on a live server connection.","highlights":["Local database","Network detection","Sync queue"],"body":[["p","The key principle is:"],["h","Architecture"],["code","text","                 ┌──────────────┐\n                 │     UI       │\n                 └──────┬───────┘\n                        ↓\n                Local data layer\n                        ↓\n              ┌─────────┴─────────┐\n              ↓                   ↓\n        Local database       Sync queue\n              ↓                   ↓\n              └──────────┬────────┘\n                         ↓\n                       API\n                         ↓\n                      Server"],["h","Example workflow"],["p","User edits a document while offline:"],["code","text","User edits document\n        ↓\nSave locally\n        ↓\nShow updated UI immediately\n        ↓\nCreate sync operation\n        ↓\nNetwork becomes available\n        ↓\nUpload pending operation\n        ↓\nServer confirms\n        ↓\nMark operation as synced"],["h","Data model example"],["code","js","{\n  id: \"doc-123\",\n  title: \"Policy.pdf\",\n  content: \"...\",\n  updatedAt: 1728200000,\n  syncStatus: \"pending\"\n}"],["p","Queue:"],["code","js","{\n  operationId: \"op-100\",\n  type: \"UPDATE_DOCUMENT\",\n  entityId: \"doc-123\",\n  payload: {\n    title: \"Updated Policy\"\n  },\n  createdAt: 1728200000,\n  retryCount: 0\n}"],["h","Important design areas"],["ul",["Local database","Network detection","Sync queue","Idempotent APIs","Retry strategy","Conflict resolution","Sync status","Data versioning","Secure local storage"]],["h","Interview answer"],["quote","For an offline-first app, I treat local storage/database as the immediate source for the UI, persist user operations in a sync queue, and synchronize them when connectivity returns. The design also needs retries, idempotency, conflict resolution, versioning, and a clear sync status."]],"realWorld":[["h","Real-world example"],["p","A field employee edits customer information in an area with poor connectivity. The app saves the update locally and synchronizes when the network returns."],["p","**In practice.** A field-service app lets engineers fill inspection forms in areas with no signal. Data is saved to local SQLite, queued as pending changes, synced in the background when the network returns, and conflicts are resolved by rules agreed with the business."]]},{"id":2859,"category":"Offline-First","difficulty":"Senior","question":"How do you resolve data conflicts when the device comes back online?","answer":"A conflict occurs when both the device and server changed the same data before synchronization. When the phone reconnects, there are two versions.","highlights":[],"body":[["p","Example:"],["code","text","Server:\nName = John\n\nPhone changes:\nName = Johnny\n\nAnother user changes:\nName = Jonathan"],["h","Strategy 1: Last-write-wins"],["p","The newest update wins."],["p","Simple, but it can overwrite valid changes."],["h","Strategy 2: Version-based conflict detection"],["p","Server stores:"],["code","js","{\n  id: \"123\",\n  name: \"John\",\n  version: 5\n}"],["p","Client last saw:"],["code","text","version = 5"],["p","Client sends:"],["code","http","If-Match: 5"],["p","But server is already at:"],["code","text","version = 6"],["p","Server can reject the update:"],["code","text","409 Conflict"],["p","The client then fetches the latest data and resolves the conflict."],["h","Strategy 3: Field-level merge"],["p","If one device changes:"],["code","text","name"],["p","and another changes:"],["code","text","phoneNumber"],["p","both changes may be safely merged."],["h","Strategy 4: Domain-specific conflict resolution"],["p","For business-critical data, define explicit rules."],["p","For example:"],["code","text","Inventory quantity:\nserver authoritative\n\nUser draft:\nclient can preserve draft\n\nApproval status:\nserver authoritative"],["h","Interview answer"],["quote","I don't automatically choose last-write-wins for every system. For simple data it can work, but for important business data I prefer versioning or optimistic concurrency and domain-specific conflict rules. A conflict can return 409, after which the client fetches the latest version and merges or asks the user to resolve it."]],"realWorld":[["h","Real-world example"],["p","An offline document app has:"],["code","text","Device A → edits document title\nDevice B → changes document approval status"],["p","Instead of blindly overwriting the entire document, the server can merge fields or enforce business rules."],["p","**In practice.** Two technicians edit the same work order offline. On sync the server compares version numbers; non-overlapping fields are merged automatically, while genuinely conflicting fields (e.g. the status) follow a business rule or ask the user to choose."]]},{"id":2860,"category":"Offline-First","difficulty":"Mid","question":"Where should offline data be stored --- AsyncStorage, SQLite, or server cache?","answer":"I choose storage based on the data. AsyncStorage is suitable for small key-value data, SQLite is better for large structured offline datasets and queries, and server cache improves backend performance but cannot provide device-side offline capability.","highlights":["Preferences","Small cached values","Simple flags"],"body":[["p","There is no single correct choice."],["table",["Storage","Best for","Limitation"],[["AsyncStorage","Small key-value data","Not ideal for complex relational datasets"],["SQLite","Structured offline data","More database design/management"],["Server cache","Temporary server-side data","Doesn't provide true device offline storage"]]],["h","AsyncStorage"],["p","Good for:"],["code","js","await AsyncStorage.setItem(\n  \"theme\",\n  \"dark\"\n);"],["p","Useful for:"],["ul",["Preferences","Small cached values","Simple flags"]],["p","Not ideal for thousands of structured documents."],["h","SQLite"],["p","Better for:"],["code","text","Documents\nUsers\nMetadata\nSync queue\nRelationships\nIndexes\nQueries"],["p","Example conceptual query:"],["code","sql","SELECT *\nFROM documents\nWHERE title LIKE '%policy%';"],["p","This is much more suitable for large offline datasets."],["h","Server cache"],["p","Examples include Redis-like server-side caches."],["p","The cache is useful for improving server performance, but it does not solve:"],["quote","The phone has no internet."]],"realWorld":[["h","Real-world choice"],["p","For an offline document application:"],["code","text","Preferences → AsyncStorage\nLarge structured document metadata → SQLite\nTemporary server cache → Server cache\nSensitive credentials → Secure platform storage"],["p","**In practice.** A banking app keeps small settings in AsyncStorage, transaction history and drafts in SQLite (queryable, transactional) and treats the server as the source of truth with a cache layer for fast reads, instead of storing everything in one place."]]},{"id":2861,"category":"AI Tooling","difficulty":"Mid","question":"How do you use AI tools without blindly trusting the output?","answer":"AI is an accelerator, not the final authority.","highlights":["What happens for 404?","What happens for 500?","Is authentication required?"],"body":[["p","My workflow is:"],["code","text","Understand requirement\n       ↓\nAsk AI for implementation/ideas\n       ↓\nReview generated code\n       ↓\nRun tests\n       ↓\nCheck edge cases\n       ↓\nSecurity review\n       ↓\nPerformance review\n       ↓\nHuman approval"],["h","Example"],["p","AI generates:"],["code","js","function getUser(id) {\n  return fetch(`/users/${id}`)\n    .then(res => res.json());\n}"],["p","I don't automatically merge it."],["p","I ask:"],["ul",["What happens for 404?","What happens for 500?","Is authentication required?","Is the response shape validated?","Is there a timeout?","Is cancellation needed?","Could this leak sensitive information?","Are tests present?"]],["h","Interview answer"],["quote","I use AI to accelerate development, but I treat its output as untrusted code. I verify the requirement, review the implementation, run tests, inspect edge cases, and perform security and performance checks before using it in production."]],"realWorld":[["h","Real-world example"],["p","If AI generates authentication code, I would be especially careful because a seemingly correct implementation could contain:"],["ul",["Weak token storage","Missing authorization checks","Token leakage","Improper validation","Insecure error messages"]]]},{"id":2862,"category":"AI Tooling","difficulty":"Mid","question":"What risks does AI-generated code introduce in production?","answer":"AI-generated code can introduce the same categories of bugs as human-written code, plus risks caused by confidently generated incorrect assumptions.","highlights":["Unnecessary libraries","Outdated APIs","Packages with security concerns"],"body":[["h","1. Security vulnerabilities"],["p","Example:"],["code","js","const query =\n  `SELECT * FROM users WHERE id = ${req.params.id}`;"],["p","AI might generate unsafe code if the prompt/context is poor."],["h","2. Incorrect assumptions"],["p","AI may assume:"],["code","text","API always returns 200"],["p","when the real API returns:"],["code","text","204 / 401 / 403 / 404 / 409 / 500"],["h","3. Dependency risks"],["p","It may suggest:"],["ul",["Unnecessary libraries","Outdated APIs","Packages with security concerns","More dependencies than needed"]],["h","4. Performance problems"],["p","Example:"],["code","js","users.map(user => {\n  return expensiveOperation(user);\n});"],["p","This may be fine for 50 records and terrible for 500,000."],["h","5. Incorrect business logic"],["p","AI doesn't automatically know company-specific rules."],["h","6. Privacy/data leakage"],["p","Developers can accidentally send:"],["ul",["Credentials","Customer data","Proprietary code","Production logs"]],["p","to AI systems if organizational policies do not allow it."],["h","7. Licensing/IP concerns"],["p","Generated code and suggested dependencies should be reviewed according to organizational policy."],["h","Interview answer"],["quote","The major risks are security vulnerabilities, incorrect assumptions, poor performance, dependency issues, business-logic errors, privacy concerns, and potentially licensing/IP concerns. I mitigate these through code review, testing, security scanning, dependency review, and organizational AI policies."]],"realWorld":[["p","**Why it matters.** AI-generated code can look right and still be insecure or wrong, so teams need guardrails."],["p","**Example.** A generated endpoint concatenates user input into a SQL string and logs full card numbers. It passes a quick manual test but contains SQL injection and a privacy leak. Static analysis, code review, tests and dependency checks catch what the demo did not."]]},{"id":2863,"category":"AI Tooling","difficulty":"Mid","question":"How do you review AI-written code differently from human code?","answer":"I review both carefully, but AI-generated code deserves extra attention around assumptions and unnecessary complexity.","highlights":["Happy path","Error path","Boundary cases"],"body":[["h","1. Requirement correctness"],["p","Does the code actually solve the requested problem?"],["h","2. Edge cases"],["code","text","null\nundefined\nempty arrays\nlarge datasets\nnetwork failure\nduplicate requests\ntimeouts\npermissions"],["h","3. Security"],["p","Check:"],["code","text","authentication\nauthorization\ninput validation\ninjection\nsecrets\nsensitive data\nlogging"],["h","4. Performance"],["p","Ask:"],["code","text","What is the complexity?\nDoes it create unnecessary objects?\nDoes it trigger unnecessary renders?\nDoes it make N+1 API/database calls?"],["h","5. Maintainability"],["p","AI can produce code that technically works but is unnecessarily complex."],["h","6. Tests"],["p","I want tests for:"],["ul",["Happy path","Error path","Boundary cases","Important business rules"]],["h","Example"],["p","AI produces:"],["code","js","const result = data\n  .filter(...)\n  .map(...)\n  .sort(...)\n  .reduce(...);"],["p","I don't reject it just because it looks complex."],["p","I ask:"],["ul",["Is each operation necessary?","What's the dataset size?","Can operations be combined?","Is the result correct for empty input?","Does sorting make sense?","Is this called on every render?"]],["h","Interview answer"],["quote","I don't use a different quality standard for AI code, but I pay extra attention to assumptions, generated abstractions, dependency choices, security, and edge cases. I validate it with tests, static analysis, profiling where needed, and normal human code review."]],"realWorld":[["h","Real-world example"],["p","For an AI-generated React Native `FlatList`, I would specifically inspect:"],["code","text","keyExtractor\nrenderItem stability\nrow memoization\nlarge-data behavior\nimage loading\nunnecessary state updates"],["p","For AI-generated Node.js code:"],["code","text","error propagation\nasync handling\ntimeouts\ninput validation\nauthentication\ndatabase query safety\nlogging"],["p","**In practice.** A developer pastes AI-generated pagination code into a pull request. The reviewer checks the edge cases the AI missed (empty page, negative offset, concurrent inserts), runs the tests, verifies dependencies and security, and rejects the part that logs customer data."]]},{"id":2864,"category":"AI Tooling","difficulty":"Mid","question":"Where does AI help the most --- and where should it NOT be used?","answer":"AI is most valuable for repetitive development, boilerplate, test generation, explanation, refactoring ideas, and debugging assistance. I would not blindly use it for security-critical, business-critical, or high-risk decisions. My approach is AI for acceleration, with human ownership of correctness, security, architecture, and production decisions.","highlights":[],"body":[["h","1. Boilerplate"],["code","text","CRUD endpoints\nDTOs\nbasic components\ntest templates\nconfiguration"],["h","2. Repetitive development work"],["p","For example, generating similar document-viewing components or standard API integration patterns."],["h","3. Code explanation"],["p","AI can explain unfamiliar code:"],["code","text","What does this hook do?\nWhy is this dependency required?\nWhat causes this render?"],["h","4. Test generation"],["p","AI can suggest:"],["code","text","unit tests\nedge cases\nnegative scenarios\nmock data"],["h","5. Refactoring ideas"],["p","It can identify:"],["code","text","duplicate logic\nlarge functions\nrepeated patterns\npossible abstractions"],["h","6. Debugging assistance"],["p","You can provide:"],["code","text","error\nstack trace\nrelevant code\nexpected behavior\nactual behavior"],["p","and use AI to generate hypotheses."],["h","1. Security-critical decisions"],["p","Don't blindly accept generated:"],["code","text","authentication\nauthorization\nencryption\ntoken handling\npayment logic"],["h","2. Business-critical decisions"],["p","AI may not understand organizational rules."],["h","3. Production architecture without human review"],["p","AI can suggest an architecture, but experienced engineers need to evaluate:"],["code","text","scalability\ncost\navailability\nsecurity\noperability\nteam capability\nmaintenance"],["h","4. Medical/legal/financial decisions"],["p","These require appropriate qualified human expertise and authoritative sources."],["h","5. Secrets and sensitive information"],["p","Do not paste confidential information into an AI tool unless your organization's policies explicitly permit that workflow."],["h","Practical rule"],["p","Use AI heavily for:"],["code","text","Speed + exploration + repetitive work"],["p","Use human judgment heavily for:"],["code","text","Risk + architecture + security + business decisions"]],"realWorld":[["h","Real-world example"],["p","For a document management application, AI can help generate:"],["code","text","React components\nAPI boilerplate\nunit tests\nPlaywright tests\ndocumentation\nrepetitive scaffolding"],["p","But I would keep human review for:"],["code","text","RBAC\ndocument authorization\nPII handling\nauthentication\nproduction deployment\ndata deletion\naudit requirements"],["p","**In practice.** AI is excellent at generating test cases, boilerplate and explaining legacy code, but a payment-calculation rule or a security design should be written and reviewed by a person who understands the business consequences."]]},{"id":2865,"category":"Resume & Projects","difficulty":"Junior","question":"Tell me about yourself (30-second introduction)","answer":"I'm a full-stack engineer with 5+ years of experience working mainly with React, TypeScript, Java, Spring Boot and the MERN stack. Currently, I'm working as a Senior Associate Consultant at Infosys, where I work on an insurance document management platform for Northwestern Mutual.","highlights":[],"body":[["h","Interview answer"],["quote","My current responsibilities cover frontend development using React, TypeScript, Redux Toolkit and RTK Query, along with backend development using Spring Boot microservices, REST APIs, PostgreSQL and Node.js services."],["quote","I've worked on document workflows such as search, create, update, delete, check-in/check-out, multi-document support and document viewing. I'm also involved in automated testing using Playwright and JUnit/Mockito and GitLab CI/CD."],["quote","Before Infosys, I worked on projects including Estée Lauder's Virtual Try-On experience and reusable React component libraries. More recently, I've also worked on AI-assisted engineering using MCP servers and GitHub Copilot to automate repetitive frontend development work."],["p","Your resume supports these responsibilities and technologies."],["h","Also worth knowing"],["quote","I am a Java Full Stack Developer with experience building applications using Java, Spring Boot, React and relational databases. My work involves developing REST APIs, implementing authentication and authorization, optimizing database queries and building responsive React applications. I have also worked with technologies such as Redis, Kafka and monitoring tools for scalable production systems. I enjoy solving real-world problems, improving application performance and taking features from development through production."],["p","Customize this with your actual experience."],["h","Also worth knowing"],["p","If an interviewer asks:"],["quote","How would you design a scalable full-stack application?"],["p","A strong answer is:"],["quote","I would start with a React frontend served through a CDN and protect the edge with a WAF. Requests would go through a load balancer or API gateway to horizontally scalable, stateless Node.js services. I would use Redis for carefully selected caching and distributed rate limiting, and SQL or MongoDB depending on the data and consistency requirements. For asynchronous work such as notifications, analytics, and background processing, I would use a message broker and worker services. Authentication would use a suitable identity provider with OAuth2/OIDC and access tokens, with authorization enforced at the API layer. For reliability I would add timeouts, retries where safe, idempotency, health checks and observability. Finally, I would use database indexes and query plans to optimize important queries rather than indexing everything."],["p","This demonstrates:"],["code","text","Frontend\n+\nBackend\n+\nDatabase\n+\nCaching\n+\nSecurity\n+\nScalability\n+\nAsynchronous processing\n+\nReliability\n+\nObservability"]],"realWorld":[["p","**Why it matters.** The introduction frames the whole interview. A crisp story of experience, strengths and current work sets the direction."],["p","**Example.** Structure it as present, past, future: current role and main technologies, one or two projects with measurable impact, and what you want next, in about 30-60 seconds, then stop and let the interviewer pick a thread to explore."]]},{"id":2866,"category":"Resume & Projects","difficulty":"Mid","question":"Explain your current project and its architecture end to end","answer":"The application follows a layered full-stack architecture. The React frontend handles presentation and user interaction. Redux Toolkit manages application state, while RTK Query handles API communication and caching.","highlights":[],"body":[["h","Simple architecture"],["code","text","                 User\n                  |\n                  v\n        React / TypeScript UI\n                  |\n        Redux Toolkit / RTK Query\n                  |\n                  v\n             REST APIs\n                  |\n                  v\n       Spring Boot Microservices\n             /          \\\n            /            \\\n           v              v\n      PostgreSQL      Node.js Services"],["h","Interview answer"],["quote","Requests go through REST APIs to Spring Boot microservices. Spring Boot handles business logic and persistence through Spring Data JPA and Hibernate. PostgreSQL stores the application data, and Node.js services are also involved in the overall data flow."],["quote","This separation allows the frontend, business logic and persistence layers to evolve independently."],["p","The resume confirms React/TypeScript/Redux Toolkit/RTK Query on the frontend and Spring Boot/PostgreSQL/Node.js in the backend stack."],["h","Strong interview answer"],["quote","My current project is an insurance document management platform for Northwestern Mutual. It is used to manage insurance-related documents and their lifecycle."],["quote","From the frontend, we use React, TypeScript, Redux Toolkit and RTK Query. The backend consists of Spring Boot microservices, REST APIs, Spring Data JPA and Hibernate, with PostgreSQL as the database. Node.js services are also part of the data flow."],["quote","The application supports document operations such as create, update, delete, search, check-in/check-out, multi-document handling, e-signature and document viewing."],["quote","My role is full-stack. I work on UI development, API integration, backend services, database-related functionality, automated testing and troubleshooting issues across environments."],["p","Your resume specifically lists the platform architecture and document workflows."],["h","Also worth knowing"],["p","A strong answer should follow:"],["code","text","User\n ↓\nReact\n ↓\nAPI Gateway / Load Balancer\n ↓\nSpring Boot Services\n ↓\nRedis / Kafka\n ↓\nDatabase\n ↓\nExternal Systems"],["h","Interview structure"],["p","Explain:"],["ol",["Business requirement","Frontend","API layer","Services","Database","Cache","Messaging","Authentication","Monitoring","Deployment"]],["h","Also worth knowing"],["p","Use this structure:"],["code","text","1. Business problem\n2. Users\n3. Frontend\n4. Backend\n5. APIs\n6. Database\n7. Cache\n8. Messaging\n9. Security\n10. Deployment\n11. Monitoring"],["h","Sample answer"],["quote","My current project is a business application where users interact through a React frontend. Requests go through an API gateway or load balancer to Spring Boot services. We use REST APIs for synchronous operations and Kafka for asynchronous workflows. Data is stored in a relational database, and Redis is used for selected frequently accessed data. Authentication is handled through JWT-based security and authorization is implemented using roles and permissions. We monitor application health, logs, metrics and distributed traces. For deployment, services are containerized and deployed through our CI/CD pipeline."],["p","Replace the generic details with your actual project."]],"realWorld":[["h","Example --- Insurance platform"],["code","text","React UI\n   |\n   v\nAPI Gateway\n   |\n   +---- Customer Service\n   |\n   +---- Policy Service\n   |\n   +---- Claims Service\n   |\n   +---- Payment Service\n             |\n             v\n           Kafka\n             |\n       Notification Service\n\nServices\n   |\n   +---- MySQL/PostgreSQL\n   +---- Redis"],["p","**In practice.** For a document-management platform: the React/TypeScript front end with RTK Query calls Spring Boot microservices, which use JPA with PostgreSQL, with Playwright and JUnit tests running in GitLab CI. Walk the interviewer through one request (search a document) from click to database and back."]]},{"id":2867,"category":"Resume & Projects","difficulty":"Mid","question":"What exactly was your contribution?","answer":"My contribution was not limited to UI development. I worked across the feature lifecycle. I implemented React and TypeScript functionality, integrated REST APIs, worked with Redux Toolkit and RTK Query, participated in backend development using Spring Boot, and worked with PostgreSQL-backed functionality. I also contributed to automated testing with Playwright and JUnit/Mockito and helped troubleshoot issues through the deployment lifecycle.","highlights":["Don't say:","I built the entire application alone.","Instead explain:"],"body":[["h","Important"],["p","Don't say:"],["quote","I built the entire application alone."],["p","Instead explain:"],["code","text","Team responsibility\n       ↓\nMy module/features\n       ↓\nMy technical contribution\n       ↓\nMy specific problem-solving work"]],"realWorld":[["p","**Why it matters.** Interviewers want to know what you personally did, not what the team did."],["p","**Example.** Instead of 'we built document search', say 'I designed the search API contract, implemented the RTK Query integration and pagination, reduced response time by adding an index, and wrote Playwright tests for the flow', then name the measurable result."]]},{"id":2868,"category":"Resume & Projects","difficulty":"Mid","question":"Explain one feature end to end (and a feature you designed from scratch)","answer":"For a document search feature, the user enters a document name or identifier in the React UI. The frontend sends the search request through the API layer. The backend controller receives the request and passes it to the service layer, where business rules are applied. The repository accesses PostgreSQL through JPA/Hibernate. The backend returns the matching documents, and RTK Query manages the API response on the frontend.","highlights":["validation","authorization","idempotency"],"body":[["h","Flow"],["code","text","User enters document ID/name\n          ↓\nReact search component\n          ↓\nRedux / RTK Query\n          ↓\nREST API\n          ↓\nSpring Boot controller\n          ↓\nService layer\n          ↓\nRepository / JPA\n          ↓\nPostgreSQL\n          ↓\nResponse\n          ↓\nReact UI"],["h","Interview answer"],["quote","For large datasets, I would also make sure the query is indexed appropriately and that pagination is applied rather than returning every document."],["h","Also worth knowing"],["p","Use this structure:"],["code","text","Requirement\n ↓\nAPI design\n ↓\nDatabase design\n ↓\nBackend implementation\n ↓\nFrontend\n ↓\nSecurity\n ↓\nTesting\n ↓\nDeployment\n ↓\nMonitoring"],["h","Backend"],["code","java","@PostMapping(\"/claims\")\npublic ResponseEntity<ClaimResponse> createClaim(\n        @RequestBody ClaimRequest request) {\n\n    ClaimResponse response =\n        claimService.createClaim(request);\n\n    return ResponseEntity\n        .status(HttpStatus.CREATED)\n        .body(response);\n}"],["h","Important interview points"],["p","Mention:"],["ul",["validation","authorization","idempotency","transaction boundaries","error handling","audit logs","monitoring","testing"]]],"realWorld":[["h","Example --- Insurance Claim Feature"],["p","Requirement:"],["code","text","Customer submits claim"],["p","Architecture:"],["code","text","React\n ↓\nPOST /claims\n ↓\nClaim Service\n ↓\nDatabase\n ↓\nKafka: ClaimCreated\n ↓\nNotification Service\n ↓\nCustomer notification"],["p","**In practice.** For 'document check-out': the UI disables the button and calls `POST /documents/{id}/checkout`, the service verifies permission, sets a lock in a transaction and returns the lock owner; the UI updates through RTK Query cache invalidation, and Playwright covers the full flow."]]},{"id":2869,"category":"Resume & Projects","difficulty":"Mid","question":"Tell me about a challenging problem or production issue you solved","answer":"One challenging type of issue in a document management system is maintaining the correct document version during check-in and check-out. For example, after a document is checked in and a new version is created, the UI must not continue showing an older version.","highlights":["Do not invent numbers in an actual interview.","Use your real production numbers."],"body":[["h","Good example: document version/check-in issue"],["quote","I would debug this across the complete flow rather than assuming the problem is only in React. First I would verify the API response and document version returned by the backend. Then I would check the Redux/RTK Query cache and component state to see whether stale data is being reused. Finally, I would verify the viewer is receiving the latest document identifier/version."],["quote","The key lesson is that debugging distributed application behavior requires checking the complete data flow from database to API to client state to UI."],["h","Also worth knowing"],["p","Use:"],["code","text","Problem\n ↓\nImpact\n ↓\nInvestigation\n ↓\nRoot Cause\n ↓\nFix\n ↓\nPrevention"],["h","Sample"],["quote","We had an API whose response time increased during peak traffic. I first checked application metrics and found that database time had increased. Tracing showed that one API was making several repeated database queries. After analyzing the query plan, we optimized the query and removed unnecessary calls. We also added monitoring around the query latency so we could detect similar issues earlier."],["h","Strong closing"],["quote","The important lesson for me was not just fixing the immediate problem but adding monitoring and preventive measures."],["h","Also worth knowing"],["p","Use the STAR format."],["h","Situation"],["quote","A claims API became slow during peak business hours."],["h","Task"],["quote","I was responsible for identifying the bottleneck and restoring acceptable response time."],["h","Action"],["quote","I checked application metrics and traces, identified slow database queries, analyzed the query plan, added an appropriate index and introduced caching for frequently accessed policy data."],["h","Result"],["quote","The response time dropped from several seconds to sub-second for normal traffic and database CPU usage reduced."],["h","Important"],["p","Do not invent numbers in an actual interview."],["p","Use your real production numbers."]],"realWorld":[["p","**Why it matters.** This is a behavioural question about problem solving. Use a clear structure and show your reasoning."],["p","**Example.** Use STAR: Situation (search was slow for large result sets), Task (reduce latency), Action (profiled the query, added an index, introduced pagination, cached repeated filters), Result (page load dropped from several seconds to under one second)."]]},{"id":2870,"category":"Resume & Projects","difficulty":"Mid","question":"Explain your VTO project.","answer":"Your resume describes an Estée Lauder Virtual Try-On experience using React, SCSS, JavaScript and third-party rendering APIs, serving millions of global users with sub-100 ms rendering.","highlights":[],"body":[["h","Interview answer"],["quote","One of my previous projects was a Virtual Try-On experience for Estée Lauder. It was a customer-facing React application where users could virtually try products. The application integrated third-party rendering APIs to produce the visual experience."],["quote","My focus was on the frontend implementation, API integration, reusable components and performance. Because this was a high-traffic customer-facing feature, performance was important. The project achieved sub-100 ms rendering for the visual output."],["h","Follow-up: What was challenging?"],["quote","The main challenge was maintaining a responsive user experience while integrating real-time third-party rendering. I focused on efficient component rendering, minimizing unnecessary work and ensuring the API integration didn't negatively affect the user experience."]],"realWorld":[["p","**Why it matters.** Project questions test depth. Be ready for follow-ups on architecture, performance and decisions."],["p","**Example.** For a Virtual Try-On experience, explain the user flow (camera/image input to product overlay), the technology (React components, image processing and APIs), performance concerns on mobile devices and how you tested across browsers."]]},{"id":2871,"category":"Resume & Projects","difficulty":"Mid","question":"Explain your MCP / AI automation project.","answer":"Your resume states that the MCP server generates frontend scaffolding such as Filter, Search, Advanced Search and Check-in/Check-out workflows together with Jest/RTL tests.","highlights":[],"body":[["h","Interview answer"],["quote","I worked on a frontend scaffolding MCP server to automate repetitive development work. Instead of developers manually creating the same structure for common business-area features, the MCP workflow can generate frontend scaffolding such as Search, Filter, Advanced Search and Check-in/Check-out functionality along with Jest and React Testing Library test scaffolding."],["quote","The goal was not to replace developers. The goal was to automate repetitive boilerplate so developers could spend more time on business logic and review the generated code for correctness."],["quote","We also used GitHub Copilot custom instructions, skills and LLM-based automation for requirements analysis, code generation and test scaffolding."],["p","The resume explicitly describes this AI-assisted engineering workflow."]],"realWorld":[["p","**Why it matters.** AI automation questions test whether you use AI tools critically and measure the benefit."],["p","**Example.** Describe automating repetitive frontend scaffolding with MCP servers and Copilot: what was automated (components, tests, boilerplate), the review process that kept quality high and the time saved per feature, while noting that generated code still goes through normal code review."]]},{"id":2872,"category":"Resume & Projects","difficulty":"Mid","question":"Why did you use Redux Toolkit?","answer":"Redux Toolkit provides a standardized way to manage client-side application state while reducing the boilerplate traditionally associated with Redux. It also provides utilities that make immutable state updates easier to write and maintain.","highlights":[],"body":[],"realWorld":[["p","**Why it matters.** State management choices should be justified by problems solved, not popularity."],["p","**Example.** Redux Toolkit gave a predictable store with less boilerplate (slices, immer), good DevTools and clear patterns for a large document workflow with shared state across many screens, where plain Context would cause re-render and structure problems."]]},{"id":2873,"category":"Resume & Projects","difficulty":"Mid","question":"Why did you use RTK Query?","answer":"RTK Query is useful for server-state management. It handles API requests, caching, loading and error states, and helps avoid writing repetitive data-fetching logic manually.","highlights":[],"body":[],"realWorld":[["h","Real-world example"],["code","text","Component\n   ↓\nRTK Query\n   ↓\nAPI\n   ↓\nCache\n   ↓\nComponent"],["p","This is especially useful when multiple components need the same server data."],["p","**In practice.** RTK Query replaced hand-written fetch, loading and error code for document APIs. It caches responses, de-duplicates identical requests and invalidates tags after create/update/delete, so the document list refreshes automatically after an edit."]]},{"id":2874,"category":"Resume & Projects","difficulty":"Senior","question":"How do you explain scalability using your project?","answer":"For a large document management platform, scalability needs to be considered at multiple layers. On the frontend, I avoid loading and rendering unnecessary documents. At the API layer, I use pagination and efficient endpoints. At the backend, services should remain as stateless as possible so they can scale horizontally. At the database layer, I use appropriate indexes and optimize queries. Caching can be introduced for suitable read-heavy data, and monitoring helps identify bottlenecks as traffic increases.","highlights":[],"body":[],"realWorld":[["p","**Why it matters.** Show you can connect design principles to a real system you have worked on."],["p","**Example.** Explain how the platform scales: stateless services behind a load balancer, database indexes and pagination for document queries, caching of hot reads, asynchronous processing for slow tasks, and monitoring to know when to scale."]]},{"id":2875,"category":"Resume & Projects","difficulty":"Mid","question":"What production practices have you worked with?","answer":"Your resume lists GitLab CI/CD, canary releases, Playwright, JUnit and Mockito.","highlights":[],"body":[["h","Interview answer"],["quote","I have worked with automated testing and CI/CD as part of the development lifecycle. On the frontend, I worked with Playwright for end-to-end testing, and on the backend with JUnit and Mockito. We also used GitLab CI/CD with canary releases. The goal was to catch regressions before release and reduce deployment risk."]],"realWorld":[["p","**Why it matters.** Production practices show maturity beyond writing features."],["p","**Example.** Mention CI/CD in GitLab, automated tests (Playwright, JUnit/Mockito), code reviews, feature flags, logging and monitoring, and incident follow-ups with root-cause analysis and preventive tests."]]},{"id":2876,"category":"Resume & Projects","difficulty":"Mid","question":"What makes your current experience full-stack?","answer":"I work across multiple layers rather than only the frontend. On the UI side, I work with React, TypeScript, Redux Toolkit and RTK Query. On the backend, I work with REST APIs, Spring Boot services and database-backed functionality. I also participate in testing, CI/CD and troubleshooting. So I can follow a feature from UI interaction through API and business logic to database and back.","highlights":[],"body":[],"realWorld":[["p","**Why it matters.** A good answer demonstrates ownership of the full request path rather than listing technologies."],["p","**Example.** Walk through one feature: UI in React, state/API layer in RTK Query, Spring Boot REST endpoint, JPA and PostgreSQL schema, plus deployment and testing, showing you can debug a problem at any layer."]]},{"id":2877,"category":"Behavioral","difficulty":"Mid","question":"Describe a Situation Where You Disagreed With Your Team","answer":"We had a discussion about whether a feature should be implemented synchronously or asynchronously. My initial preference was asynchronous processing because the operation involved external systems. Instead of pushing my approach immediately, I discussed the latency, failure handling and operational trade-offs with the team. We evaluated both options and chose the approach that best matched the business requirement.","highlights":["communication","technical reasoning","willingness to listen"],"body":[["p","Do not say:"],["quote","My teammate was wrong."],["p","Instead:"],["quote","We had different technical approaches."],["h","Key message"],["p","Show:"],["ul",["communication","technical reasoning","willingness to listen","business awareness","no ego"]]],"realWorld":[["p","**Why it matters.** Disagreement questions test collaboration, communication and maturity."],["p","**Example.** Describe a disagreement over a technical approach: you gathered data (prototype/benchmark), listened to the other side, proposed a trade-off, agreed on a decision criteria, committed to the outcome and kept the relationship strong."]]},{"id":2878,"category":"Behavioral","difficulty":"Junior","question":"Why Are You Looking for a Change?","answer":"I am looking for an opportunity where I can work on larger-scale systems and take more ownership of backend and full-stack development. I have gained valuable experience in my current role, and now I want to work on more challenging engineering problems involving Java, Spring Boot, React, distributed systems and scalable architecture.","highlights":["criticizing your manager","criticizing your company","saying only \"salary\""],"body":[["p","Keep the answer positive."],["h","Good sample"],["p","Avoid:"],["ul",["criticizing your manager","criticizing your company","saying only \"salary\"","complaining about colleagues"]]],"realWorld":[["p","**Why it matters.** Be positive and forward-looking. Focus on growth rather than complaints."],["p","**Example.** Explain you have learned a lot in the current role and now want broader ownership, larger-scale systems or new technologies, and that this role matches those goals; never criticise your current employer."]]},{"id":2879,"category":"Behavioral","difficulty":"Junior","question":"Where Do You See Yourself in the Next Few Years?","answer":"Over the next few years, I want to become a strong senior engineer who can own features end to end, from requirements and design through implementation, production deployment and monitoring. I also want to deepen my understanding of distributed systems, cloud architecture and system design, while helping junior engineers and contributing to technical decisions.","highlights":[],"body":[],"realWorld":[["p","**Why it matters.** Interviewers look for ambition aligned with the role and the team."],["p","**Example.** Say you want to deepen technical depth in system design, mentor others and lead features end to end, growing toward a senior or lead role, with examples of steps you are already taking such as owning designs and mentoring juniors."]]},{"id":2880,"category":"Behavioral","difficulty":"Mid","question":"What are the most common interview mistakes, and how do you avoid them?","answer":"Virtual DOM means React updates only one DOM node. React uses reconciliation to determine the necessary DOM changes; the actual update depends on the rendered tree and React's reconciliation/commit process.","highlights":[],"body":[["h","Mistake 1"],["p","Better:"],["h","Mistake 2"],["quote","useRef is faster than useState."],["p","Better:"],["quote","`useRef` and `useState` serve different purposes. Updating a ref does not itself trigger a render, while updating state schedules a render."],["h","Mistake 3"],["quote","GraphQL is always better than REST."],["p","Better:"],["quote","The choice depends on data requirements, client flexibility, caching, operational complexity, and team needs."],["h","Mistake 4"],["quote","More indexes always mean better performance."],["p","Better:"],["quote","Indexes can improve reads but increase storage and write-maintenance cost."],["h","Mistake 5"],["quote","JWT is an authentication protocol."],["p","Better:"],["quote","JWT is a token format. OAuth 2.0 is an authorization framework, and OpenID Connect adds an identity layer for authentication."],["h","Mistake 6"],["quote","Node.js is single-threaded, so it can only handle one request."],["p","Better:"],["quote","JavaScript execution uses an event-loop model, while Node.js uses asynchronous I/O and underlying system/libuv mechanisms to handle many concurrent I/O operations. CPU-heavy JavaScript can still block the event loop."],["h","Mistake 7"],["quote","Microservices automatically make a system scalable."],["p","Better:"],["quote","Microservices can enable independent scaling and deployment, but they also introduce network, data consistency, observability, and operational complexity."],["h","Mistake 1"],["p","Giving definitions without examples."],["p","Instead:"],["quote","ConcurrentHashMap is thread-safe."],["p","Add:"],["quote","I would use it when multiple threads update shared application state."],["h","Mistake 2"],["p","Using Kafka everywhere."],["p","Explain why Kafka is needed."],["h","Mistake 3"],["p","Saying \"Redis makes everything faster.\""],["p","Explain:"],["ul",["cache hit ratio","TTL","invalidation","consistency","memory limits"]],["h","Mistake 4"],["p","Saying \"microservices solve scalability.\""],["p","Microservices introduce:"],["ul",["network failures","distributed transactions","observability complexity","deployment complexity","data consistency challenges"]],["h","Mistake 5"],["p","Using retries without discussing idempotency."],["p","Especially dangerous for:"],["code","text","Payments\nOrders\nMoney transfers"],["h","Mistake 6"],["p","Only discussing happy paths."],["p","Always mention:"],["code","text","Failure\nTimeout\nRetry\nDuplicate request\nPartial failure\nRecovery"]],"realWorld":[["p","**Why it matters.** Knowing common mistakes helps you avoid them under pressure."],["p","**Example.** A candidate starts coding immediately without clarifying requirements, then discovers a missing edge case in the last 5 minutes. Spending the first minutes on questions and examples, and narrating your reasoning, avoids that."]]},{"id":2881,"category":"Behavioral","difficulty":"Senior","question":"What is the senior-level answer pattern (and how to answer as a 5+ year engineer)?","answer":"Indexes can improve lookup performance by reducing the amount of data the database needs to scan, but I don't add indexes blindly. I look at actual query patterns and execution plans because indexes also introduce storage and write overhead.","highlights":[],"body":[["p","Avoid answers like:"],["quote","Index is used to make queries fast."],["p","Instead say:"],["p","Avoid:"],["quote","useMemo improves performance."],["p","Say:"],["quote","`useMemo` can avoid repeating an expensive calculation, but it isn't automatically a performance improvement. I use it when the calculation is expensive or reference stability is important and the optimization is justified."],["p","Avoid:"],["quote","Use a transaction for invoice generation."],["p","Say:"],["quote","I would keep consistency-critical database operations inside an atomic transaction, but I would avoid long-running external operations such as PDF generation inside that transaction. After commit, I would use an asynchronous workflow for those operations."],["p","That difference is important in senior interviews: **don't just name a technology or concept --- explain why, where, trade-offs, and what happens when something fails.**"],["h","Also worth knowing"],["p","For almost every architecture question, structure the answer like this:"],["code","text","Requirement\n    ↓\nAPI\n    ↓\nService\n    ↓\nDatabase\n    ↓\nCache\n    ↓\nMessaging\n    ↓\nSecurity\n    ↓\nScaling\n    ↓\nFailure handling\n    ↓\nObservability"],["p","For a production problem:"],["code","text","Impact\n ↓\nMetrics\n ↓\nLogs\n ↓\nTraces\n ↓\nRoot Cause\n ↓\nImmediate Mitigation\n ↓\nPermanent Fix\n ↓\nPrevention"],["p","For a coding problem:"],["code","text","Understand\n ↓\nBrute Force\n ↓\nOptimize\n ↓\nCode\n ↓\nTest\n ↓\nComplexity\n ↓\nLarge-scale behavior"],["h","Also worth knowing"],["p","For almost every system-design answer, discuss these dimensions:"],["code","text","                    System Design\n                         |\n        +----------------+----------------+\n        |                |                |\n   Scalability       Reliability       Security\n        |                |                |\n   Performance       Availability    Authentication\n   Caching           Failover        Authorization\n   Load balance      Retries         Rate limits\n        |\n        +----------------+----------------+\n                         |\n                    Data Design\n                         |\n              SQL / NoSQL / Cache\n                         |\n                    Consistency"],["p","The strongest answers do not simply list technologies."],["p","They explain:"],["quote","**Why this component is needed, what problem it solves, what trade-off it introduces, and what happens when it fails.**"],["h","Also worth knowing"],["p","For almost every practical question, structure your answer like this:"],["h","1. What is the problem?"],["p","Explain the behavior in simple terms."],["h","2. Why does it happen?"],["p","Explain the underlying mechanism."],["h","3. Show a small example"],["p","Use a short code snippet."],["h","4. Explain the production impact"],["p","Say what can break in a real application."],["h","5. Explain how you would solve it"],["p","Give the practical approach."],["h","6. Mention the trade-off"],["p","Senior-level answers should not sound like:"],["quote","Always use X."],["p","Instead:"],["quote","I would choose X when this condition exists, measure the impact, and use Y when the requirements are different."],["p","This demonstrates **real-world engineering judgment**, rather than only theoretical knowledge."],["h","Also worth knowing"],["p","Do not only memorize definitions."],["p","For each topic, explain it in this order:"],["code","text","1. Definition\n2. Why we use it\n3. Simple code example\n4. Real-world example\n5. Important limitation/trade-off"],["p","For example, for `ConcurrentHashMap`:"],["quote","ConcurrentHashMap is a thread-safe map designed for concurrent access. I use it when multiple threads need to access shared in-memory map data. For example, an e-commerce inventory cache may be accessed by multiple request threads. However, thread safety of the map does not automatically make a multi-step business operation atomic, so I use atomic map operations or proper synchronization when needed."],["p","This style demonstrates both **theory and practical engineering understanding**."]],"realWorld":[["p","**Why it matters.** A repeatable answer pattern keeps senior-level answers structured and complete."],["p","**Example.** For any scenario: state the problem, explain why it happens, show a small example, describe production impact, give the solution and name the trade-off. For example, with a slow API: cause (missing index), impact (timeouts), fix (index + cache), trade-off (slower writes)."]]},{"id":2882,"category":"Managerial","difficulty":"Mid","question":"How Do You Estimate Tasks?","answer":"I avoid estimating a large feature as one number. I break it into technical tasks, identify dependencies and unknowns, estimate development and testing separately, and include risk for external integrations or unfamiliar areas.","highlights":["complexity","dependencies","integration"],"body":[["p","Break the feature into smaller pieces."],["p","Example:"],["code","text","Feature: Payment integration\n\nRequirements\n   ↓\nAPI design\n   ↓\nDatabase changes\n   ↓\nPayment integration\n   ↓\nError handling\n   ↓\nTesting\n   ↓\nDeployment"],["p","Estimate each separately."],["h","Consider"],["ul",["complexity","dependencies","unknowns","testing","integration","deployment","risk"]]],"realWorld":[["p","**Why it matters.** Estimation is about honesty and risk management, not exact prediction."],["p","**Example.** Break the task into pieces, identify unknowns and dependencies, give a range (e.g. 5-8 days), include testing and review time, revisit the estimate as you learn more and communicate early if the scope changes."]]},{"id":2883,"category":"System Design","difficulty":"Senior","question":"Combined design walkthrough: how indexes, caching, rate limiting, scaling and async fit together","answer":"Let's combine several of these interview concepts into an e-commerce system.","highlights":[],"body":[["code","text","                         Users\n                           |\n                           v\n                         CDN\n                           |\n                           v\n                         WAF\n                           |\n                           v\n                    Load Balancer\n                           |\n            +--------------+--------------+\n            |              |              |\n            v              v              v\n         Node API       Node API       Node API\n            |              |              |\n            +--------------+--------------+\n                           |\n                    +------+------+\n                    |             |\n                    v             v\n                  Redis        Database\n                    |             |\n                    |        +----+----+\n                    |        |         |\n                    |      Indexes   Tables\n                    |\n                    +--> Cache\n                    +--> Rate limits\n                    +--> Negative cache\n\n                           |\n                           v\n                     Message Broker\n                      /     |      \\\n                     v      v       v\n                Inventory  Email  Analytics"],["h","Database indexes"],["code","text","products.sku\nusers.email\norders.customer_id\ntransactions.transaction_id"],["h","Negative caching"],["code","text","Invalid product ID\nInvalid short URL\nMissing resource"],["h","Rate limiting"],["code","text","Login\nOTP requests\nPassword reset\nPayment APIs"],["h","Horizontal scaling"],["code","text","Node API 1\nNode API 2\nNode API 3\n..."],["h","Async processing"],["code","text","Order created\n     |\n     v\nMessage broker\n     |\n     +--> Email\n     +--> Inventory\n     +--> Analytics"],["h","Redis"],["p","Possible uses:"],["code","text","Session/cache\nRate limiting\nDistributed counters\nNegative cache\nShort-lived data"]],"realWorld":[["p","**Why it matters.** Interviewers like candidates who connect individual concepts into one working system, showing where each concept solves a real bottleneck."],["p","**Example.** In an e-commerce flash sale the CDN and WAF absorb static traffic and attacks, a load balancer spreads requests over stateless Node API instances, Redis serves product pages and enforces rate limits, indexed database queries handle orders, and a message queue sends emails and updates inventory asynchronously so checkout stays fast when traffic spikes."]]},{"id":2884,"category":"System Design","difficulty":"Senior","question":"Banking platform architecture: what to include and why","answer":"Banking systems put correctness, security and auditability ahead of raw speed, and your design should say so explicitly.","highlights":[],"body":[["code","text","Mobile/Web\n    |\n    v\nWAF\n    |\n    v\nAPI Gateway\n    |\n    +--> Auth Service\n    |\n    +--> Account Service\n    |\n    +--> Transaction Service\n    |\n    +--> Fraud Service\n    |\n    +--> Notification Service\n             |\n             v\n        Message Broker"],["p","Important design concerns:"],["code","text","Strong authentication\nAuthorization\nTransactions\nIdempotency\nAudit logging\nEncryption\nFraud detection\nRate limiting\nObservability"]],"realWorld":[["p","**Why it matters.** Banking systems put correctness, security and auditability ahead of raw speed, and your design should say so explicitly."],["p","**Example.** A funds transfer goes through the WAF and API gateway to the transaction service, which authenticates the user, checks fraud rules, runs the debit and credit in one database transaction with an idempotency key, writes an audit log and publishes an event so notifications are sent after the money has actually moved."]]},{"id":2885,"category":"System Design","difficulty":"Senior","question":"Insurance platform architecture: what to include and why","answer":"Insurance platforms revolve around long-lived policies, claims workflows and documents, so data integrity, access control and traceability dominate the design.","highlights":[],"body":[["code","text","Customer / Agent\n       |\n       v\nWeb/Mobile App\n       |\n       v\nAPI Gateway\n       |\n       +--> Customer Service\n       +--> Policy Service\n       +--> Claims Service\n       +--> Document Service\n       +--> Payment Service\n       +--> Notification Service"],["p","Claim workflow:"],["code","text","Claim submitted\n      |\n      v\nClaims Service\n      |\n      v\nDatabase\n      |\n      v\nMessage Broker\n   /      |       \\\n  v       v        v\nDocument Fraud  Notification\nService  Service    Service"]],"realWorld":[["p","**Why it matters.** Insurance platforms revolve around long-lived policies, claims workflows and documents, so data integrity, access control and traceability dominate the design."],["p","**Example.** A claim moves through submitted, assessed, approved and paid stages in a claims service. Documents are stored in object storage with access checks, each status change emits an event for notifications and audit, and role-based rules ensure an adjuster sees only assigned claims while customers see only their own policies."]]},{"id":2886,"category":"JWT","difficulty":"Senior","question":"Security design by domain: insurance, banking and e-commerce","answer":"A client may accidentally submit a payment twice. The server can use the idempotency key to avoid processing the same payment twice.","highlights":["OAuth2/OIDC where appropriate","JWT validation","Role/permission-based authorization"],"body":[["h","Idempotency example"],["code","text","POST /payments\nIdempotency-Key: 12345"]],"realWorld":[["h","Insurance"],["p","Protect:"],["code","text","Customer personal information\nPolicy information\nClaims\nDocuments\nPayment information"],["p","Example authorization:"],["code","text","CUSTOMER -> View own policy\nAGENT    -> Process assigned claims\nADMIN    -> Manage policies"],["p","Use:"],["ul",["HTTPS","OAuth2/OIDC where appropriate","JWT validation","Role/permission-based authorization","Input validation","Audit logging","Encryption","Secure file/document storage","Rate limiting"]],["h","Banking"],["p","Security requirements are especially strict."],["p","Protect:"],["code","text","Account data\nTransaction data\nPayment information\nCustomer identity"],["p","Example:"],["code","text","CUSTOMER\n   |\n   +--> View own accounts\n   +--> Transfer money\n\nADMIN\n   |\n   +--> Operational administration"],["p","Important controls:"],["ul",["MFA","Strong authentication","Authorization","Transaction limits","Fraud detection","Audit trails","Encryption in transit and at rest","Idempotency for payment operations","Rate limiting","Secure secrets management"]],["h","E-commerce"],["p","Protect:"],["code","text","Customer account\nOrders\nPayment information\nAddress information"],["p","Example:"],["code","text","CUSTOMER -> Own orders\nSELLER   -> Own products/orders\nADMIN    -> Platform administration"],["p","Use:"],["ul",["OAuth2/OIDC or another secure authentication mechanism","JWT validation for APIs","HTTPS","CSRF protection where applicable to the authentication mechanism","Input validation","Rate limiting","Secure payment-provider integration","Authorization checks","Secure cookies/token storage strategy"]]]},{"id":2887,"category":"System Design","difficulty":"Mid","question":"Quick revision cheat sheet: key points to remember before the interview","answer":"A short revision sheet helps you recall the main idea of each topic quickly in the last days before an interview.","highlights":[],"body":[["table",["\\#","Question","Key phrase to remember"],[["1","`setTimeout(0)`","Minimum delay, not immediate"],["2","Promises vs timers","Microtasks before next task"],["3","Shallow vs deep copy","Nested references can be shared"],["4","Mutability","New references make state changes predictable"],["5","Currying","Partial application and reusable functions"],["6","React Native re-render","Reference identity + state/context/parent changes"],["7","`useRef` / `useState` / `useMemo`","Mutable value / UI state / cached calculation"],["8","`FlatList`","Virtualization + stable keys + lightweight rows"],["9","JS thread","Heavy synchronous work blocks JS"],["10","Real-device debugging","Measure and profile, don't guess"],["11","Node concurrency","Event loop + non-blocking I/O"],["12","Blocking I/O","Don't block the event loop"],["13","Promise rejection","Handle errors explicitly"],["14","JWT","Authentication + token verification + authorization"],["15","Production errors","Central handling + structured logs + request IDs"],["16","Offline-first","Local data + durable sync queue"],["17","Conflicts","Versioning + domain-specific resolution"],["18","Storage","Choose based on data shape and scale"],["19","Retries","Backoff + jitter + idempotency"],["20","AI trust","AI output is untrusted until verified"],["21","AI risks","Security + correctness + privacy + performance"],["22","AI code review","Check assumptions and edge cases"],["23","AI usage","Automate low-risk work; retain human ownership of high-risk decisions"]]],["h","Also worth knowing"],["table",["Topic","Strong one-line answer"],[["Virtual DOM","React's in-memory UI representation used as part of its rendering/reconciliation model"],["Real DOM","Browser's actual document tree"],["Reconciliation","Process of determining how rendered UI should change"],["`useState`","Reactive state that triggers rendering when updated"],["`useRef`","Persistent mutable reference that doesn't itself trigger rendering"],["`useContext`","Reads values from React context"],["React optimization","Measure first; optimize renders, bundles, lists, images, and data fetching"],["Event loop","Coordinates JavaScript execution and asynchronous callbacks/promises"],["Express middleware","Functions in the HTTP request/response pipeline"],["REST","Resource-oriented API style using HTTP semantics"],["GraphQL","Schema/query-based API where clients select requested fields"],["Authentication","Verifies identity"],["Authorization","Determines permissions"],["JWT","Token format often used for stateless API access"],["OAuth2","Authorization framework; OIDC adds identity/authentication semantics"],["Normalization","Reduces relational redundancy and update anomalies"],["Denormalization","Intentionally duplicates/precomputes data for read performance"],["SQL index","Data structure used to efficiently locate rows"],["MongoDB index","Index supporting efficient document queries"],["Transaction","Atomic logical unit of database work"],["ACID","Atomicity, Consistency, Isolation, Durability"],["MongoDB aggregation","Pipeline-based document processing"],["Cache-aside","Application checks cache, then loads DB on miss"],["Load balancer","Distributes traffic among healthy instances"],["Horizontal scaling","Add more instances"],["Vertical scaling","Add more resources to one instance"]]],["h","Also worth knowing"],["table",["Topic","One-line answer"],[["JDK","Development kit containing tools and runtime components"],["JRE","Runtime environment used to run Java applications"],["JVM","Executes Java bytecode"],["Encapsulation","Protect data through controlled access"],["Inheritance","Reuse behavior from a parent class"],["Polymorphism","Same contract, different implementations"],["Abstraction","Hide implementation details"],["Multithreading","Running multiple tasks concurrently"],["Synchronization","Controls concurrent access to shared state"],["JMM","Rules for memory visibility, ordering, and concurrency"],["HashMap","Non-thread-safe map"],["ConcurrentHashMap","Map designed for concurrent access"],["Stream API","Declarative processing of data"],["Functional Interface","Interface with one abstract method"],["Lambda","Concise implementation of a functional interface"],["Auto Configuration","Spring Boot automatically configures common infrastructure"],["`@Component`","Generic Spring bean"],["`@Service`","Business/service layer bean"],["`@Repository`","Persistence/data-access layer bean"],["IoC","Spring controls object creation/lifecycle"],["DI","Dependencies are provided to objects"],["Spring Security","Authentication and authorization framework"],["REST","Resource-oriented HTTP API style"],["JPA","Persistence specification"],["Hibernate","JPA implementation/ORM framework"],["Microservices","Independently deployable business services"],["Actuator","Production monitoring and management"],["JWT","Token format commonly used for stateless API authentication/authorization"],["OAuth2","Authorization framework"],["Scalability","Ability to handle increased load effectively"]]],["h","Also worth knowing"],["p","Topic                Must Remember"],["h","Also worth knowing"],["table",["Topic","Senior-level point"],[["Node request lifecycle","Follow request through middleware → controller → service → DB → response"],["Client/server","HTTP/HTTPS + methods + headers + body + status"],["API flow","Separate presentation, business logic and persistence"],["Indexing","Optimize real query patterns; indexes have write/storage cost"],["Pagination","Don't move huge datasets unnecessarily"],["React","Component-based, declarative UI"],["Virtual DOM","React determines required UI updates"],["`useEffect`","Synchronize with external systems"],["`useMemo`","Optimize expensive calculations when justified"],["Context","Avoid unnecessary prop drilling"],["Query optimization","Measure execution plans and bottlenecks"],["API scalability","Stateless services + efficient data access"],["Data retrieval","Return only what the UI needs"],["Transactions","Atomic database changes"],["Invoice generation","Keep consistency-critical DB operations transactional"],["PDF generation","Prefer asynchronous processing after commit"],["Duplicate invoices","Idempotency + database constraints"],["Concurrent invoice creation","Locking/versioning/constraints"],["Production failures","Logging + monitoring + retry strategy"]]]],"realWorld":[["p","**Why it matters.** A short revision sheet helps you recall the main idea of each topic quickly in the last days before an interview."],["p","**Example.** The night before an interview, scan the sheet: event loop order (sync, microtasks, macrotasks), how to find a slow API (metrics, tracing, DB), offline-first sync steps, and how to review AI-written code. Then explain each aloud in 30 seconds with one real example."]]},{"id":2888,"category":"Behavioral","difficulty":"Senior","question":"Interview mindset: what interviewers look for in senior answers","answer":"The strongest answers are not the ones with the most buzzwords. When answering system-design questions, continuously explain why you selected a technology.","highlights":["Clear fundamentals","Good coding ability","Understanding of trade-offs"],"body":[["p","A strong Java Full Stack candidate should show:"],["ul",["Clear fundamentals","Good coding ability","Understanding of trade-offs","Secure API design","Database awareness","React performance knowledge","Distributed-system fundamentals","Production debugging ability","Ownership","Communication"]],["p","For example:"],["p","Bad:"],["quote","I will use Kafka, Redis and microservices."],["p","Better:"],["quote","I would use Redis for frequently accessed data where low latency is important, Kafka for asynchronous event-driven workflows, and microservices where independent scaling and clear business boundaries justify the operational complexity."],["p","That difference is what makes an answer sound more senior."],["h","Also worth knowing"],["p","For senior-level questions, interviewers usually don't only want the definition."],["p","They are looking for whether you understand:"],["code","text","Performance\n   +\nScalability\n   +\nConcurrency\n   +\nReliability\n   +\nSecurity\n   +\nTrade-offs"],["p","For almost every system-design question, explicitly say:"],["quote","The right design depends on the workload and requirements."],["p","Then discuss:"],["code","text","Read vs Write\nConsistency vs Availability\nLatency vs Throughput\nCost vs Performance\nSimplicity vs Scalability\nSecurity vs Convenience"],["p","That demonstrates engineering judgment rather than memorization."]],"realWorld":[["p","**Why it matters.** Interviewers hire for judgement. Fundamentals plus clear trade-off reasoning matter more than buzzwords."],["p","**Example.** Asked to choose between a SQL and a NoSQL store, a senior answer states requirements first (consistency, query patterns, scale), compares options, names the trade-off and says what would change the decision, rather than simply declaring a favourite technology."]]}];
